const STORIES = [

{e:"🦔",t:"Ёжик и потерянное яблоко",len:"short",x:`В лесу жил маленький ёжик по имени Тишка. Однажды осенью он нашёл на полянке большое красное яблоко и очень обрадовался.
Тишка покатил яблоко к своей норке, но по пути споткнулся о корень дерева, и яблоко укатилось в кусты.
Ёжик долго искал его и чуть не заплакал. Тут ему помогла белка Рыжик: она увидела яблоко с высокой ветки и показала лапкой, куда бежать.
Ёжик нашёл яблоко и в благодарность угостил белку половинкой. Домой они пошли вместе, весёлые и довольные.`,
q:[["Как звали ёжика?","Тишка."],["Что нашёл ёжик на полянке?","Большое красное яблоко."],["Кто помог ёжику найти яблоко?","Белка Рыжик — она увидела яблоко с ветки."]]},

{e:"🌧️",t:"Зонтик для муравья",len:"short",x:`Летним днём маленький муравей Фомка спешил домой с крошкой хлеба. Вдруг начался дождь, и капли для муравья были огромными, как ведро воды.
Фомка спрятался под лист лопуха, но лист закачался от ветра. Мимо пролетал жук-солдатик и предложил муравью залезть к нему на спину.
Жук раскрыл жёсткие крылья, будто настоящий зонтик, и довёз Фомку прямо до муравейника. Крошка хлеба даже не намокла.`,
q:[["Что нёс муравей Фомка?","Крошку хлеба."],["От чего он прятался под листом лопуха?","От дождя."],["Кто помог муравью добраться домой?","Жук-солдатик: подвёз его и прикрыл крыльями, как зонтиком."]]},

{e:"⭐",t:"Мальчик, который считал звёзды",len:"short",x:`Каждый вечер мальчик Стёпа выходил во двор и считал звёзды на небе. Один раз он досчитал до пятидесяти, запутался и начал сначала.
Бабушка вышла к нему и сказала: «Звёзды сосчитать нельзя, их слишком много. Зато можно загадать желание на самую яркую».
Стёпа нашёл самую яркую звезду и загадал, чтобы завтра была ясная погода. Наутро небо было чистым и солнечным.`,
q:[["Чем занимался Стёпа каждый вечер?","Считал звёзды на небе."],["Что посоветовала бабушка?","Загадать желание на самую яркую звезду."],["Какое желание загадал Стёпа?","Чтобы завтра была ясная погода."]]},

{e:"🐢",t:"Черепаха, которая никуда не спешила",len:"short",x:`На берегу пруда жила черепаха Клаша. Все звери вокруг вечно торопились, а Клаша всегда двигалась медленно.
Однажды заяц посмеялся над её медлительностью. Клаша не обиделась, а предложила соревнование: кто первым найдёт камешек, спрятанный у пруда.
Заяц помчался вперёд и проскочил мимо. А Клаша шла вдоль берега и заглядывала под каждый листик — и нашла камешек первой.`,
q:[["Как звали черепаху?","Клаша."],["Какое соревнование она придумала?","Кто первым найдёт камешек, спрятанный у пруда."],["Почему заяц проиграл?","Он слишком торопился и не заметил камешек."]]},

{e:"🐱",t:"Кот, который боялся первого снега",len:"short",x:`Рыжий кот Барсик прожил только одно лето и никогда не видел снега. Когда за окном закружились белые хлопья, он спрятался под диван.
Хозяйка вынесла его во двор на руках. Барсик осторожно тронул снег лапой: снег был холодный, но совсем не страшный — он просто таял.
Через час кот уже носился по сугробам и ловил снежинки лапой.`,
q:[["Почему Барсик испугался?","Он никогда раньше не видел снега."],["Куда он спрятался?","Под диван."],["Что кот делал во дворе через час?","Бегал по сугробам и ловил снежинки лапой."]]},

{e:"🐝",t:"Пчёлка, которая не любила делиться",len:"short",x:`Пчёлка Майя собрала целую каплю мёда и не хотела делиться ни с кем, даже с сестрой Лизой.
Скоро Майя заболела и не смогла летать за нектаром. Есть стало нечего. Тогда Лиза, не помня обиды, принесла ей мёд из своих запасов.
Майе стало стыдно. Когда она выздоровела, то сама позвала всех пчёл попробовать её мёд.`,
q:[["Чем не хотела делиться пчёлка Майя?","Мёдом."],["Кто помог ей, когда она заболела?","Её сестра Лиза."],["Что сделала Майя, когда выздоровела?","Сама угостила мёдом всех пчёл в улье."]]},

{e:"🦫",t:"Бобрёнок-строитель",len:"short",x:`Бобрёнок Тоша очень хотел построить плотину, как взрослые бобры. Но ветки всё время падали в воду и уплывали.
Папа-бобр показал ему хитрость: сначала кладут самые толстые ветки, а тонкие — сверху. Тогда стена держится крепко.
Тоша попробовал ещё раз, делая всё по порядку. Плотина устояла! Он так гордился, что позвал всех соседей смотреть.`,
q:[["Что хотел построить Тоша?","Плотину."],["Какой совет дал папа-бобр?","Сначала класть толстые ветки, а тонкие — сверху."],["Что сделал Тоша, когда плотина устояла?","Позвал соседей посмотреть на свою постройку."]]},

{e:"🎈",t:"Воздушный шарик мышки",len:"short",x:`Мышка Крошка получила на празднике у котят один красный шарик и очень боялась, что он лопнет.
Она держала верёвочку так крепко, что не могла ни бегать, ни играть с друзьями. Старший брат сказал ей: «Шарик нужен, чтобы радоваться, а не чтобы бояться».
Крошка стала подбрасывать шарик и смеяться со всеми. Вечером шарик всё-таки лопнул, но день уже был весёлым.`,
q:[["Что получила мышка на празднике?","Красный воздушный шарик."],["Почему она не играла с друзьями?","Слишком крепко держала шарик и боялась, что он лопнет."],["Что сказал ей старший брат?","Что шарик нужен, чтобы радоваться, а не бояться."]]},

{e:"🌻",t:"Самый упрямый подсолнух",len:"short",x:`На краю поля рос подсолнух Гриша. Все подсолнухи поворачивали головы за солнцем, а Гриша решил, что будет смотреть только в одну сторону.
Скоро его листья пожелтели, а голова опустилась. Соседний подсолнух объяснил: «Мы поворачиваемся не из вредности, а чтобы поймать больше света».
Гриша послушался и стал поворачиваться вместе со всеми. К концу лета его семечки были самыми крупными на поле.`,
q:[["Что решил подсолнух Гриша?","Смотреть только в одну сторону и не поворачиваться за солнцем."],["Почему подсолнухи поворачиваются за солнцем?","Чтобы поймать больше света."],["Что случилось с Гришей в конце лета?","У него выросли самые крупные семечки."]]},

{e:"🚂",t:"Паровозик и крутая горка",len:"short",x:`Маленький паровозик Пых вёз вагончик с игрушками для детского сада. На пути была высокая горка.
Пых разогнался и поехал вверх, но на середине силы кончились, и он покатился назад. Второй раз получилось то же самое.
Тогда паровозик поехал медленно-медленно, но не останавливался ни на секунду. Так он и добрался до вершины, а вниз покатился уже сам.`,
q:[["Что вёз паровозик Пых?","Вагончик с игрушками для детского сада."],["Почему он два раза скатывался назад?","Он слишком разгонялся и на середине горки терял силы."],["Как Пых всё-таки заехал на гору?","Поехал медленно, но ни разу не остановился."]]},

{e:"🐶",t:"Щенок и потерянный ботинок",len:"short",x:`Щенок Кузя нашёл в прихожей папин ботинок и утащил его под кровать, чтобы погрызть.
Утром папа искал ботинок повсюду и опаздывал на работу. Кузя понял, что натворил, и сам вытащил ботинок из-под кровати.
Папа сначала рассердился, а потом рассмеялся: ботинок был цел, только шнурок стал коротким. С тех пор Кузе купили свою игрушку-косточку.`,
q:[["Что утащил щенок Кузя?","Папин ботинок."],["Куда он его спрятал?","Под кровать."],["Что купили щенку после этого случая?","Свою игрушку-косточку."]]},

{e:"❄️",t:"Снеговик, который хотел в гости",len:"short",x:`Дети слепили во дворе снеговика Митю и надели ему ведро на голову. Митя очень хотел зайти в дом, где горел тёплый свет.
Воробей объяснил ему: «В доме тепло, и ты растаешь. Твой дом — двор». Митя расстроился, но остался снаружи.
Зато дети каждый день выбегали к нему играть, приносили морковку для носа и лепили рядом снежных друзей. Митя понял, что и во дворе бывает весело.`,
q:[["Кого слепили дети во дворе?","Снеговика Митю."],["Почему Мите нельзя было заходить в дом?","В тепле он растаял бы."],["Что делали дети, чтобы Мите не было скучно?","Выбегали играть, приносили морковку и лепили рядом снежных друзей."]]},

{e:"🐟",t:"Рыбка, которая боялась глубины",len:"short",x:`Маленькая рыбка Лу жила у самого берега и никогда не заплывала на глубину, потому что там было темно.
Однажды сильная волна унесла её далеко от берега. Лу зажмурилась от страха, а когда открыла глаза, увидела разноцветные кораллы и стайку весёлых рыбок.
Оказалось, глубина совсем не страшная. Теперь Лу каждый день плавала туда и звала с собой других.`,
q:[["Почему рыбка Лу не заплывала на глубину?","Там было темно, и она боялась."],["Как она оказалась далеко от берега?","Её унесла сильная волна."],["Что Лу увидела на глубине?","Разноцветные кораллы и стайку весёлых рыбок."]]},

{e:"🍄",t:"Гриб под шапкой",len:"short",x:`После дождя в лесу вырос крепкий боровик. Он был так горд собой, что не заметил, как под его широкой шляпкой спрятались от воды улитка, жук и маленькая лягушка.
Когда дождь кончился, гости вылезли и поблагодарили гриб. Боровик удивился: он и не думал, что может быть кому-то домиком.
С тех пор он всегда расправлял шляпку пошире, когда собирался дождь.`,
q:[["Кто спрятался под шляпкой боровика?","Улитка, жук и маленькая лягушка."],["Знал ли гриб, что под ним прячутся?","Нет, он этого сначала не заметил."],["Что боровик делал перед дождём после этого случая?","Расправлял шляпку пошире."]]},

{e:"🎨",t:"Кисточка без краски",len:"short",x:`У девочки Ани была любимая кисточка. Однажды все краски закончились, и кисточка загрустила: рисовать было нечем.
Аня взяла воду и стала водить кисточкой по серому асфальту. На камне появлялись тёмные линии — получился целый рисунок, пусть и ненадолго.
Кисточка поняла: чтобы творить, не всегда нужны дорогие краски, иногда хватает воды и выдумки.`,
q:[["Почему кисточка загрустила?","Все краски закончились."],["Чем Аня рисовала на асфальте?","Обычной водой."],["Что поняла кисточка?","Что для рисования иногда хватает воды и выдумки."]]},

{e:"🦉",t:"Совёнок, который не спал днём",len:"short",x:`Все совы в лесу спят днём и охотятся ночью. А совёнок Уф решил, что хочет жить как все птицы — днём.
Он весь день летал с синицами, а к вечеру так устал, что уснул прямо на ветке и проспал охоту. Утром Уф был голодным и сонным.
Мама-сова сказала: «Каждому хорошо жить по своим силам». Уф вернулся к ночным делам, но с синицами по утрам всё равно здоровался.`,
q:[["Когда обычно спят совы?","Днём."],["Что случилось с совёнком, когда он летал днём?","Он устал, уснул на ветке и проспал охоту."],["Что сказала мама-сова?","Что каждому хорошо жить по своим силам."]]},

{e:"🥕",t:"Морковка, которая не хотела расти",len:"short",x:`На грядке росли морковки. Одна из них, по имени Ринка, решила, что расти вниз — скучно, и потянулась вверх, к солнцу.
Но у морковки вкусная часть растёт именно в земле. Ринка выросла с большой зелёной ботвой и совсем тоненьким корешком.
Осенью хозяйка сказала: «Ботва пойдёт кроликам, а морковки-то и нет». Ринке стало обидно, но семечки её запомнили урок.`,
q:[["Куда решила расти морковка Ринка?","Вверх, к солнцу."],["Где у морковки растёт вкусная часть?","В земле."],["Что выросло у Ринки вместо корешка?","Большая зелёная ботва."]]},

{e:"🌊",t:"Камешек и море",len:"short",x:`На берегу лежал острый серый камешек. Он колол ноги всем, кто гулял по пляжу, и очень этим гордился.
Море каждый день накатывало на него волну за волной. Сначала камешек сопротивлялся, но проходили месяцы, и его острые углы становились всё глаже.
Через год он стал круглым и гладким. Девочка подняла его, положила в карман и сказала: «Какой красивый!»`,
q:[["Чем гордился камешек в начале?","Тем, что он острый и колет ноги."],["Что делало море с камешком?","Накатывало волны и постепенно сглаживало его углы."],["Что случилось с камешком через год?","Он стал круглым и гладким, и девочка забрала его себе."]]},

{e:"🐘",t:"Слонёнок и качели",len:"short",x:`В зоопарке повесили новые качели, и все звери по очереди катались. Слонёнок Бим тоже захотел, но боялся, что верёвка не выдержит.
Он долго стоял в стороне и смотрел. Смотритель заметил это и принёс толстый канат специально для слонёнка.
Бим сел, оттолкнулся — и качели выдержали. Оказалось, ему просто нужны были качели по размеру.`,
q:[["Почему слонёнок не садился на качели?","Боялся, что верёвка не выдержит его вес."],["Кто помог слонёнку?","Смотритель зоопарка."],["Что принёс смотритель?","Толстый канат специально для слонёнка."]]},

{e:"📚",t:"Книжка, которую никто не открывал",len:"short",x:`На верхней полке в библиотеке стояла книжка о путешествиях. Она была очень интересная, но пыльная, и её никто не брал.
Однажды мальчик Тимур залез на стремянку за другой книгой и случайно задел эту. Книжка упала прямо ему в руки.
Тимур прочитал первую страницу и не смог оторваться. Он взял книжку домой, а потом рассказал о ней всему классу.`,
q:[["Где стояла книжка о путешествиях?","На верхней полке в библиотеке."],["Как Тимур её нашёл?","Случайно задел, когда лез на стремянку за другой книгой."],["Что Тимур сделал после того, как прочитал книгу?","Рассказал о ней всему классу."]]},

{e:"🐰",t:"Зайчонок и первая морковка с грядки",len:"short",x:`Зайчонок Пушок впервые пошёл на огород вместе с мамой. Мама показала, как правильно выбирать морковку: нужно смотреть на ботву, а не тянуть подряд всё зелёное.
Пушок заторопился и выдернул петрушку. Потом укроп. Потом ещё раз петрушку.
Мама не ругалась, а спокойно показала снова. С четвёртого раза Пушок вытащил настоящую морковку и был счастлив, будто нашёл клад.`,
q:[["Куда зайчонок пошёл с мамой?","На огород."],["Что Пушок выдёргивал вместо морковки?","Петрушку и укроп."],["Что сделала мама, когда он ошибся?","Не ругалась, а спокойно показала снова."]]},

{e:"🏫",t:"Первый день в новой школе",len:"short",x:`Девочка Соня переехала в другой город и очень боялась идти в новый класс. Всю дорогу она молчала и держала маму за руку.
На перемене к ней подошла девочка Вера и просто спросила: «Хочешь конфету?» Соня кивнула, и они разговорились.
К концу дня у Сони было уже трое знакомых, а страх куда-то делся. Дома она сказала маме, что завтра пойдёт в школу сама.`,
q:[["Почему Соня боялась идти в школу?","Она переехала в другой город и шла в новый класс."],["Кто первым заговорил с Соней?","Девочка Вера."],["Что Соня сказала маме вечером?","Что завтра пойдёт в школу сама."]]},

{e:"🎂",t:"Торт для бабушки",len:"short",x:`Митя решил сам испечь бабушке торт на день рождения. Он смешал муку, яйца и сахар, но забыл поставить будильник.
Торт немного подгорел снизу. Митя расстроился и хотел выбросить его в мусор.
Мама предложила срезать подгоревший край и намазать сверху крем. Бабушка съела два кусочка и сказала, что вкуснее торта у неё в жизни не было.`,
q:[["Что решил сделать Митя для бабушки?","Испечь торт на день рождения."],["Что случилось с тортом?","Он немного подгорел снизу."],["Как торт спасли?","Срезали подгоревший край и намазали сверху крем."]]},

{e:"🐦",t:"Кормушка за окном",len:"short",x:`Зимой Аня повесила за окном кормушку и каждое утро насыпала туда семечки. Сначала прилетал один воробей, потом два, потом целая стайка.
Однажды Аня заболела и три дня не выходила из комнаты. Птицы прилетали, но кормушка была пуста.
Когда Аня поправилась, она первым делом насыпала двойную порцию. С тех пор она поняла: если начал заботиться — нужно делать это каждый день.`,
q:[["Что Аня повесила за окном?","Кормушку для птиц."],["Почему кормушка три дня была пустой?","Аня заболела и не выходила из комнаты."],["Что поняла Аня?","Что если начал о ком-то заботиться, делать это нужно каждый день."]]},

{e:"🦆",t:"Утёнок, который отстал",len:"short",x:`Мама-утка вела утят через большую поляну к пруду. Утёнок Кряк засмотрелся на бабочку и отстал.
Когда он поднял голову, никого рядом не было. Кряк испугался, но вспомнил мамино правило: «Потерялся — стой на месте и кричи».
Он громко закрякал и не сдвинулся с места. Через пять минут мама нашла его по голосу.`,
q:[["Почему утёнок отстал?","Он засмотрелся на бабочку."],["Какое правило вспомнил Кряк?","Потерялся — стой на месте и кричи."],["Как мама его нашла?","Услышала его крик и пришла на голос."]]},

{e:"🌳",t:"Дерево, которое посадил дедушка",len:"short",x:`Когда Максиму было пять лет, дедушка посадил во дворе тоненький дубок. Максим думал, что дерево вырастет за лето.
Прошёл год — дубок стал чуть выше. Прошло ещё три года — он был уже по плечо Максиму.
Дедушка объяснил: настоящие дубы растут сто лет и живут ещё дольше. «Это дерево увидят твои дети», — сказал он.`,
q:[["Что посадил дедушка во дворе?","Тоненький дубок."],["Каким стал дубок через три года?","Вырос Максиму по плечо."],["Что дедушка сказал про дерево?","Что оно будет расти долго и его увидят даже дети Максима."]]},

{e:"🍯",t:"Медвежонок и полная бочка",len:"short",x:`Медвежонок Топа нашёл в кладовке бочку мёда и решил съесть всё сразу. Он ел и ел, пока живот не стал круглым, как мяч.
Ночью у Топы разболелся живот, и он не мог уснуть. Мама дала ему тёплой воды и уложила на бок.
Утром медвежонок посмотрел на оставшийся мёд и впервые в жизни съел всего одну ложку.`,
q:[["Что медвежонок нашёл в кладовке?","Бочку мёда."],["Что случилось ночью?","У него разболелся живот, и он не мог уснуть."],["Сколько мёда Топа съел утром?","Всего одну ложку."]]},

{e:"⚽",t:"Мяч, который улетел к соседям",len:"short",x:`Ребята играли во дворе, и Гоша сильно ударил по мячу. Мяч перелетел забор и упал в соседский огород.
Все растерялись: соседа побаивались. Гоша решил не прятаться и сам постучал в калитку.
Сосед вышел, выслушал и вернул мяч. А потом сказал: «Хорошо, что пришёл сам, а не полез через забор».`,
q:[["Куда улетел мяч?","В соседский огород, за забор."],["Что сделал Гоша?","Сам пошёл и постучал в калитку."],["Что сказал сосед?","Что хорошо, что мальчик пришёл сам, а не полез через забор."]]},

{e:"🐴",t:"Жеребёнок учится бегать",len:"short",x:`Жеребёнок Ветерок родился утром, а к вечеру уже пытался бегать. Ноги у него разъезжались, и он несколько раз упал в траву.
Мама-лошадь стояла рядом и не поднимала его: она знала, что вставать он должен сам.
На третий день Ветерок бегал по всему лугу и даже обгонял бабочек.`,
q:[["Когда жеребёнок попробовал бегать?","В тот же день, вечером после рождения."],["Почему мама не поднимала его?","Она знала, что вставать он должен сам."],["Что Ветерок делал на третий день?","Бегал по всему лугу и обгонял бабочек."]]},

{e:"🧩",t:"Пазл без одной детали",len:"short",x:`Лиза собирала пазл из тысячи кусочков целую неделю. Когда осталась последняя деталь, она нигде не нашлась.
Лиза перевернула весь ковёр, заглянула под диван и чуть не заплакала. Оказалось, деталь прилипла к её же носку.
Лиза вставила последний кусочек и позвала всю семью смотреть на готовую картину.`,
q:[["Сколько кусочков было в пазле?","Тысяча."],["Куда пропала последняя деталь?","Она прилипла к носку самой Лизы."],["Что Лиза сделала, когда собрала пазл?","Позвала всю семью смотреть."]]},

{e:"🐺",t:"Волчонок, который хотел дружить",len:"short",x:`Волчонок Серый очень хотел играть с лесными зверятами, но при его появлении все разбегались.
Однажды он увидел, как в яму упал зайчонок. Серый лёг на землю, свесил в яму хвост и вытащил малыша.
Зайчонок рассказал друзьям, и на следующий день зверята сами позвали волчонка играть в догонялки.`,
q:[["Почему зверята разбегались от волчонка?","Они его боялись."],["Как Серый спас зайчонка?","Свесил в яму хвост и вытащил его."],["Что случилось на следующий день?","Зверята сами позвали волчонка играть."]]},

{e:"🌙",t:"Луна, которая уставала светить",len:"short",x:`Каждую ночь Луна выходила на небо и светила спящему городу. Однажды она подумала: «Меня никто не благодарит, зачем я стараюсь?»
Той ночью Луна спряталась за облако. В городе стало так темно, что заблудился поздний путник и не могли найти дорогу домой кораблики.
Луна выглянула, и всё сразу наладилось. Она поняла: важное дело часто делают тихо, и это не значит, что оно не нужно.`,
q:[["О чём подумала Луна?","Что её никто не благодарит и стараться незачем."],["Что случилось, когда Луна спряталась?","Стало темно, заблудился путник и кораблики не могли найти дорогу."],["Что поняла Луна в конце?","Что важное дело часто делают тихо, но оно всё равно нужно."]]},

{e:"🧦",t:"Носок, который сбежал",len:"short",x:`В стиральной машине жили два носка — левый и правый. Левый мечтал посмотреть мир и однажды закатился за барабан.
Правый остался один. Его никто не надевал, и он скучал в ящике целый месяц.
Когда мастер чинил машину, левый носок нашёлся. Они снова стали парой, и левый признался, что за барабаном было тесно и скучно.`,
q:[["О чём мечтал левый носок?","Посмотреть мир."],["Что случилось с правым носком?","Он остался один, и его никто не надевал."],["Как левый носок нашёлся?","Его нашли, когда мастер чинил стиральную машину."]]},

{e:"🐜",t:"Как муравьи строили мост",len:"short",x:`Муравьям нужно было перебраться через ручей, но моста не было. Один муравей попробовал переплыть и чуть не утонул.
Тогда самый старший сказал: «По одному не выйдет — давайте вместе». Муравьи сцепились лапками и сделали живой мостик.
По этому мостику отряд перешёл ручей за пять минут. Никто не промок.`,
q:[["Какая была у муравьёв проблема?","Нужно было перейти ручей, а моста не было."],["Что предложил самый старший муравей?","Сцепиться вместе и сделать живой мостик."],["Сколько времени заняла переправа?","Пять минут."]]},

{e:"🍎",t:"Яблоня, которая обиделась",len:"short",x:`Старая яблоня каждый год давала много яблок, но дети срывали их и часто бросали недоеденными.
Яблоня обиделась и решила, что в следующем году не даст ни одного яблока. Весной она нарочно не расцвела.
Летом дети пришли к ней и загрустили. Тогда яблоня поняла: она хочет не мести, а чтобы её труд ценили. Она рассказала обо всём садовнику, и тот научил детей собирать яблоки бережно.`,
q:[["Почему яблоня обиделась?","Дети бросали недоеденные яблоки."],["Что она решила сделать?","Не давать яблок в следующем году."],["Чему садовник научил детей?","Собирать яблоки бережно."]]},

{e:"🎻",t:"Скрипка на чердаке",len:"short",x:`На чердаке у бабушки Кирилл нашёл старую скрипку в пыльном футляре. Струны были ослабшие, а смычок кривой.
Бабушка рассказала, что это скрипка её отца, который играл на деревенских праздниках. Кирилл отнёс скрипку мастеру, и её починили.
Через год мальчик сыграл на ней свою первую мелодию, а бабушка слушала и плакала от радости.`,
q:[["Что Кирилл нашёл на чердаке?","Старую скрипку в пыльном футляре."],["Чья это была скрипка?","Отца бабушки."],["Что произошло через год?","Кирилл сыграл на этой скрипке свою первую мелодию."]]},

{e:"🐸",t:"Лягушонок и высокая кочка",len:"short",x:`Лягушонок Кваня мечтал запрыгнуть на самую высокую кочку в болоте. Он пробовал целый день, но каждый раз соскальзывал.
Вечером старая лягушка сказала: «Ты прыгаешь высоко, но не смотришь, куда садишься. Целься не в верх кочки, а в её край».
Кваня попробовал так — и с первого раза оказался наверху.`,
q:[["О чём мечтал лягушонок?","Запрыгнуть на самую высокую кочку."],["Какой совет дала старая лягушка?","Целиться не в верх кочки, а в её край."],["Получилось ли у Квани?","Да, с первого раза после совета."]]},

{e:"🚲",t:"Велосипед без страховочных колёс",len:"short",x:`Папа снял с велосипеда Дани маленькие боковые колёсики. Даня проехал два метра и упал в траву.
Он хотел бросить всё, но папа сказал: «Ты падаешь не потому, что не умеешь, а потому что едешь слишком медленно».
Даня разогнался посильнее — и вдруг поехал ровно. В тот вечер он объехал двор двадцать раз.`,
q:[["Что папа снял с велосипеда?","Маленькие боковые колёсики."],["Почему Даня падал?","Он ехал слишком медленно."],["Сколько раз он объехал двор вечером?","Двадцать раз."]]},

{e:"🐭",t:"Мышка и большая сыроварня",len:"short",x:`Мышка Пуля мечтала попасть в сыроварню. Однажды дверь оставили открытой, и она проскользнула внутрь.
Сыра было столько, что глаза разбегались. Пуля хотела унести всё, но норка была узкой, и с большим куском она застряла бы.
Тогда мышка отгрызла кусочек по размеру входа и спокойно принесла его домой. Потом сходила ещё раз. И ещё.`,
q:[["Куда мечтала попасть мышка?","В сыроварню."],["Почему она не взяла большой кусок?","Он не пролез бы в узкую норку."],["Как Пуля всё-таки принесла сыр домой?","Носила по кусочку нужного размера, за несколько раз."]]},

{e:"🌈",t:"Радуга после ссоры",len:"short",x:`Брат и сестра, Гриша и Катя, поссорились из-за одной игрушки и разбежались по разным комнатам.
За окном шёл дождь. Когда он кончился, Катя увидела огромную радугу и побежала звать брата, забыв про обиду.
Они смотрели на радугу вместе, а игрушка так и осталась лежать на полу — про неё оба уже не вспомнили.`,
q:[["Из-за чего поссорились Гриша и Катя?","Из-за одной игрушки."],["Что Катя увидела за окном?","Огромную радугу после дождя."],["Что стало с игрушкой?","Она осталась лежать на полу, о ней забыли."]]},

{e:"🐧",t:"Пингвинёнок и первое плавание",len:"short",x:`Пингвинёнок Пим стоял на краю льдины и не решался прыгнуть в воду. Все его братья уже плавали и звали его.
Пим боялся, что утонет. Он не знал, что у пингвинов перья не намокают, а под кожей есть жир, который держит на воде.
Наконец он зажмурился и прыгнул. Вода приняла его мягко, и Пим поплыл быстрее всех братьев.`,
q:[["Чего боялся пингвинёнок?","Что утонет, если прыгнет в воду."],["Что помогает пингвинам держаться на воде?","Перья, которые не намокают, и жир под кожей."],["Как Пим плавал после первого прыжка?","Быстрее всех братьев."]]},

{e:"📦",t:"Коробка вместо игрушки",len:"short",x:`Мише подарили дорогую машинку в большой коробке. Он поиграл машинкой пять минут, а потом залез в коробку.
Коробка стала кораблём, потом ракетой, потом домиком с окошком, которое Миша вырезал сам.
Мама вздохнула, но потом призналась, что в детстве делала точно так же.`,
q:[["Что подарили Мише?","Дорогую машинку в большой коробке."],["Во что превращалась коробка?","В корабль, ракету и домик с окошком."],["Что призналась мама?","Что в детстве играла так же."]]},

{e:"🦋",t:"Гусеница, которая торопилась",len:"short",x:`Гусеница Тася завидовала бабочкам и хотела летать прямо сейчас. Она пыталась махать боками, но только уставала.
Старая бабочка сказала: «Тебе нужно сначала стать куколкой и подождать. Крылья растут в тишине».
Тася свернулась в кокон и терпеливо ждала. Через две недели она вылетела оттуда с оранжевыми крыльями.`,
q:[["Чему завидовала гусеница Тася?","Тому, что бабочки умеют летать."],["Что нужно было сделать сначала?","Стать куколкой и подождать."],["Какими были её крылья?","Оранжевыми."]]},

{e:"🔑",t:"Потерянный ключ",len:"short",x:`Мама попросила Витю не терять ключ от квартиры, но он всё равно оставил его в кармане куртки в раздевалке.
После школы куртка была на месте, а ключа в кармане не было. Витя расстроился и пошёл к вахтёру.
Оказалось, ключ выпал на пол, и вахтёр его подобрал. Витя поблагодарил и с тех пор носил ключ на шнурке.`,
q:[["Где Витя оставил ключ?","В кармане куртки в раздевалке."],["Кто нашёл ключ?","Вахтёр — ключ выпал на пол."],["Как Витя стал носить ключ потом?","На шнурке."]]},

{e:"🌰",t:"Белка и забытые орехи",len:"short",x:`Осенью белка Тася спрятала орехи в двадцати разных местах и была очень довольна собой.
Зимой она нашла только пятнадцать тайников, а про пять забыла. Всю зиму она вздыхала о потерянных орехах.
А весной на тех местах выросли пять молодых ореховых деревьев. Оказалось, забытые орехи тоже пригодились — только не белке, а лесу.`,
q:[["Сколько тайников сделала белка?","Двадцать."],["Сколько тайников она нашла зимой?","Пятнадцать."],["Что выросло на забытых местах весной?","Пять молодых ореховых деревьев."]]},

{e:"🧤",t:"Варежка на верёвочке",len:"short",x:`У Кати варежки были пришиты к резинке, и она стеснялась: одноклассники говорили, что так делают только малыши.
Однажды на горке Катя сняла варежки и положила рядом. Одна свалилась в сугроб и потерялась.
Дома мама пришила новую пару к резинке, и Катя больше не спорила. К весне она была единственной в классе, кто не потерял ни одной варежки.`,
q:[["Почему Катя стеснялась варежек на резинке?","Одноклассники говорили, что так делают только малыши."],["Что случилось на горке?","Одна варежка свалилась в сугроб и потерялась."],["Чем Катя отличалась к весне?","Она единственная в классе не потеряла ни одной варежки."]]},

{e:"🐌",t:"Улитка на длинной дороге",len:"short",x:`Улитка Соня решила добраться до вершины большого камня. Соседи смеялись: «Ты и до вечера не доползёшь».
Соня не спорила, а просто ползла. Она отдыхала, когда уставала, и снова ползла дальше.
На закате она была на вершине. Оттуда было видно весь луг, и никто из смеявшихся этого не видел.`,
q:[["Куда решила добраться улитка?","До вершины большого камня."],["Что говорили соседи?","Что она не доползёт даже до вечера."],["Что Соня увидела с вершины?","Весь луг."]]},

{e:"🎁",t:"Подарок, который не купишь",len:"short",x:`У Ромы не было денег на подарок маме, и он очень переживал перед праздником.
Он подумал и сделал так: целую неделю мыл посуду, убирал игрушки и не спорил перед сном. Всё это он записал в самодельную открытку как «купоны на помощь».
Мама сказала, что это лучший подарок за много лет, и повесила открытку на холодильник.`,
q:[["Почему Рома переживал?","У него не было денег на подарок маме."],["Что он придумал?","Сделал открытку с «купонами на помощь» — мыл посуду, убирал игрушки."],["Куда мама повесила открытку?","На холодильник."]]},

{e:"🌵",t:"Кактус, который не любил воду",len:"short",x:`На подоконнике стоял кактус Игнат. Девочка Оля жалела его и поливала каждый день, как остальные цветы.
Скоро кактус начал желтеть. Бабушка объяснила: кактусы растут в пустыне и умеют долго жить без воды, а от лишней влаги корни гниют.
Оля стала поливать Игната раз в две недели, и кактус ожил, а потом даже расцвёл розовым цветком.`,
q:[["Как часто Оля сначала поливала кактус?","Каждый день."],["Почему кактусу это вредило?","От лишней влаги у кактусов гниют корни."],["Что случилось с кактусом потом?","Он ожил и расцвёл розовым цветком."]]},

{e:"🐔",t:"Курица, которая считала цыплят",len:"short",x:`У курицы Рябы было десять цыплят. Каждый вечер она пересчитывала их перед сном.
Однажды она насчитала только девять и подняла переполох на весь двор. Все звери бросились искать пропажу.
Десятый цыплёнок нашёлся у неё под крылом — он там уснул первым. Ряба смутилась, но с тех пор считала внимательнее.`,
q:[["Сколько цыплят было у курицы Рябы?","Десять."],["Сколько она насчитала однажды вечером?","Девять."],["Где нашёлся пропавший цыплёнок?","У неё самой под крылом."]]},

{e:"🛷",t:"Санки на двоих",len:"short",x:`У Артёма были новые санки, а у его друга Стаса — никаких. Артём сначала катался один и поглядывал на друга.
Кататься одному оказалось совсем не так весело. Тогда Артём позвал Стаса, и они поехали вдвоём.
Вдвоём санки летели быстрее и падали смешнее. Домой мальчики шли, тащили санки за верёвку по очереди.`,
q:[["У кого были новые санки?","У Артёма."],["Почему кататься одному было невесело?","Не с кем было разделить радость — вдвоём оказалось веселее."],["Как мальчики тащили санки домой?","По очереди."]]},

{e:"🔔",t:"Колокольчик на шее у коровы",len:"short",x:`У коровы Зорьки на шее висел колокольчик. Она считала его лишним украшением и однажды зацепилась им за куст, чтобы снять.
В тот же день Зорька забрела далеко в лес и заблудилась. Пастух искал её до самой ночи и не мог найти по звуку.
Когда корову всё-таки отыскали, колокольчик вернули на место. Теперь Зорька им даже гордится.`,
q:[["Что висело у Зорьки на шее?","Колокольчик."],["Почему пастуху было трудно её найти?","Корова сняла колокольчик, и его не было слышно."],["Как Зорька относится к колокольчику теперь?","Гордится им."]]},

{e:"🖍️",t:"Синий карандаш",len:"short",x:`В коробке жили двенадцать карандашей. Синий был самым коротким, потому что им рисовали небо и море чаще всего.
Он завидовал длинному фиолетовому, которым почти не пользовались. «Ты целый, а я обгрызенный», — говорил синий.
Фиолетовый ответил: «Зато на всех рисунках есть твой след, а моего нигде нет». Синий задумался и перестал грустить.`,
q:[["Почему синий карандаш был самым коротким?","Им чаще всего рисовали небо и море."],["Кому он завидовал?","Длинному фиолетовому карандашу."],["Что ответил фиолетовый?","Что на всех рисунках есть след синего, а его самого нигде нет."]]},

{e:"🚙",t:"Дорога в деревню",len:"short",x:`Семья ехала в деревню к бабушке, и по дороге машина заглохла. До ближайшего села было три километра.
Папа пошёл пешком за помощью, а мама с детьми остались ждать. Чтобы не скучать, они считали проезжающие машины и придумывали им имена.
Через час папа вернулся с трактористом. Дети потом говорили, что этот час был самым весёлым за всю поездку.`,
q:[["Что случилось с машиной?","Она заглохла по дороге."],["Чем занимались мама с детьми, пока ждали?","Считали проезжающие машины и придумывали им имена."],["С кем вернулся папа?","С трактористом."]]},

{e:"🐑",t:"Овечка, которая стриглась первый раз",len:"short",x:`Овечка Кудря очень боялась стрижки. Ей казалось, что без шерсти она станет некрасивой и замёрзнет.
Пастух объяснил: летом в толстой шубе жарко, а к зиме шерсть отрастёт снова, ещё гуще.
После стрижки Кудря почувствовала лёгкость и весь день бегала по лугу быстрее всех.`,
q:[["Чего боялась овечка Кудря?","Стрижки — думала, что станет некрасивой и замёрзнет."],["Что объяснил пастух?","Что летом в толстой шубе жарко, а к зиме шерсть отрастёт гуще."],["Как Кудря чувствовала себя после стрижки?","Лёгкой, бегала быстрее всех."]]},

{e:"🕯️",t:"Свечка во время грозы",len:"short",x:`Во время грозы в доме погас свет. Младшая сестра Даша испугалась темноты и заплакала.
Старший брат Ваня нашёл свечку и спички, зажёг фитилёк и поставил свечу на блюдце посреди стола.
Комната стала уютной, а тени на стенах превратились в зверей, которых дети угадывали до самого возвращения света.`,
q:[["Почему в доме погас свет?","Была гроза."],["Что нашёл Ваня?","Свечку и спички."],["Чем дети занимались при свече?","Угадывали зверей в тенях на стенах."]]},

{e:"🐒",t:"Обезьянка и зеркало",len:"short",x:`Обезьянка Чита впервые увидела в зоопарке зеркало и решила, что перед ней другая обезьяна.
Она корчила рожи — та повторяла. Она грозила лапой — та тоже. Чита рассердилась и стукнула по стеклу, а лапе стало больно.
Смотритель объяснил жестами, что это её отражение. Чита долго рассматривала себя и в конце концов подмигнула.`,
q:[["За кого обезьянка приняла отражение?","За другую обезьяну."],["Что случилось, когда она стукнула по стеклу?","Ей стало больно лапе."],["Что Чита сделала в конце?","Долго рассматривала себя и подмигнула."]]},

{e:"🌾",t:"Два колоска",len:"short",x:`На поле росли два колоска. Один был полным и тяжёлым, поэтому клонился к земле. Второй был пустым и стоял прямо, гордо глядя вверх.
Пустой смеялся: «Смотри, как ты согнулся!» Полный молчал.
Когда пришли жнецы, они собрали тяжёлые колосья в снопы, а пустой оставили в поле. Гордиться, оказывается, стоит не осанкой, а тем, что внутри.`,
q:[["Почему один колосок клонился к земле?","Он был полным и тяжёлым."],["Почему второй стоял прямо?","Он был пустым."],["Какие колосья собрали жнецы?","Тяжёлые, полные."]]},

{e:"🏔️",t:"Мальчик и высокая гора",len:"short",x:`Никита с папой пошли в поход к вершине горы. С самого низа гора казалась такой высокой, что мальчик хотел повернуть назад.
Папа сказал: «Не смотри на вершину. Смотри на следующие десять шагов».
Никита считал шаги: десять, ещё десять, ещё. К обеду они сидели на вершине и пили чай из термоса.`,
q:[["Почему Никита хотел повернуть назад?","Гора казалась ему слишком высокой."],["Какой совет дал папа?","Не смотреть на вершину, а идти по десять шагов."],["Чем закончился поход?","К обеду они были на вершине и пили чай."]]},

{e:"🦢",t:"Гадкий утёнок наоборот",len:"short",x:`На пруду жил лебедёнок, который считал себя утёнком, потому что вырос среди утят. Он думал, что просто очень нескладный.
Утята не обижали его, но и не понимали, почему он такой большой и не умеет крякать.
Осенью над прудом пролетела стая лебедей, и лебедёнок вдруг понял, кто он. Он попрощался с утятами и полетел, но каждую весну возвращался на этот пруд.`,
q:[["Кем считал себя лебедёнок?","Нескладным утёнком."],["Когда он понял, кто он на самом деле?","Осенью, когда над прудом пролетела стая лебедей."],["Что он делал каждую весну?","Возвращался на этот пруд."]]},

{e:"🍋",t:"Лимонад для соседей",len:"short",x:`Летом Полина решила устроить во дворе лимонадный столик. Она выжала лимоны, добавила воды и мёда, но забыла попробовать сам напиток.
Первый покупатель, дядя Женя, сделал глоток и сморщился: лимонад оказался слишком кислым.
Полина не расстроилась, добавила ещё мёда и вынесла дяде Жене новый стакан бесплатно. К вечеру у столика была очередь.`,
q:[["Что Полина устроила во дворе?","Лимонадный столик."],["Что она забыла сделать?","Попробовать лимонад перед продажей."],["Как она исправила ошибку?","Добавила мёда и вынесла новый стакан бесплатно."]]},

{e:"🐞",t:"Божья коровка и семь точек",len:"short",x:`Божья коровка Точка очень стеснялась своих семи чёрных пятнышек и мечтала быть просто красной.
Она попробовала спрятать точки под лист, но так пришлось сидеть на месте весь день.
Птица, пролетавшая мимо, объяснила: «Твои точки — знак, что тебя нельзя есть. Они тебя защищают». Точка вылезла на солнце и больше не пряталась.`,
q:[["Чего стеснялась божья коровка?","Своих семи чёрных пятнышек."],["Зачем ей нужны точки?","Они предупреждают птиц, что её нельзя есть, и защищают её."],["Что Точка сделала после разговора с птицей?","Вылезла на солнце и перестала прятаться."]]},

{e:"🎪",t:"Цирк приехал в город",len:"short",x:`В маленький город приехал цирк, и все дети мечтали попасть на представление. У Феди денег на билет не было.
Он пришёл к шатру пораньше и предложил помочь: носил вёдра с водой для пони и подметал дорожки.
Директор цирка дал ему билет в первый ряд. Федя досмотрел представление до конца и потом целый год рассказывал о нём.`,
q:[["Почему Федя не мог купить билет?","У него не было денег."],["Как он помогал в цирке?","Носил вёдра с водой для пони и подметал дорожки."],["Что дал ему директор?","Билет в первый ряд."]]},

{e:"🥚",t:"Яйцо в кармане",len:"short",x:`Дима нашёл в сарае куриное яйцо и положил его в карман, чтобы отнести маме. По дороге он встретил друзей и побежал играть в догонялки.
Через минуту в кармане стало мокро и липко. Яйцо разбилось.
Мама помогла отстирать штаны и сказала: «Хрупкое нельзя носить бегом». Второе яйцо Дима нёс в ладонях и очень медленно.`,
q:[["Что Дима нашёл в сарае?","Куриное яйцо."],["Почему яйцо разбилось?","Он побежал играть в догонялки с яйцом в кармане."],["Как он нёс второе яйцо?","В ладонях и очень медленно."]]},

{e:"🌱",t:"Росток в трещине асфальта",len:"short",x:`Посреди двора, в узкой трещине асфальта, пробился зелёный росток. Он был совсем один среди серого камня.
Мальчишки хотели его затоптать, но дворник дядя Коля обвёл трещину белой краской, чтобы все видели.
К августу росток превратился в маленькое деревце. Его пересадили в землю у подъезда, где оно растёт до сих пор.`,
q:[["Где пробился росток?","В узкой трещине асфальта посреди двора."],["Что сделал дворник дядя Коля?","Обвёл трещину белой краской, чтобы росток заметили."],["Куда деревце пересадили?","В землю у подъезда."]]},

{e:"🐨",t:"Коала, которая много спала",len:"short",x:`Коала Буся спала по двадцать часов в сутки, и другие звери считали её ленивой.
Однажды кенгуру спросил, почему она столько спит. Буся объяснила: её еда — жёсткие листья эвкалипта, они дают очень мало сил, поэтому силы нужно беречь.
Кенгуру попробовал такой лист, поморщился и больше Бусю не дразнил.`,
q:[["Сколько часов в сутки спала коала?","Двадцать."],["Почему коалы так много спят?","Их еда — листья эвкалипта — даёт мало сил, и силы нужно беречь."],["Что сделал кенгуру после разговора?","Попробовал лист и перестал дразнить Бусю."]]},

{e:"⏰",t:"Будильник, который никто не слушал",len:"short",x:`Каждое утро будильник честно звонил ровно в семь. Но Женя научился нажимать кнопку, не открывая глаз, и спал дальше.
Однажды он проспал контрольную по математике и получил двойку. Обидно было до слёз, потому что задачи он знал.
Женя переставил будильник на полку в другом конце комнаты. Теперь, чтобы его выключить, приходилось встать.`,
q:[["Во сколько звонил будильник?","Ровно в семь."],["Что случилось из-за того, что Женя проспал?","Он пропустил контрольную по математике и получил двойку."],["Как он решил проблему?","Переставил будильник в другой конец комнаты."]]},

{e:"🦅",t:"Орлёнок на краю гнезда",len:"short",x:`Орлиное гнездо стояло высоко на скале. Орлёнок Рэй подошёл к краю и посмотрел вниз: до земли было очень далеко.
Мама-орлица не толкала его. Она просто перелетела на соседний уступ и позвала.
Рэй расправил крылья, шагнул — и воздух подхватил его. Первый полёт длился всего десять секунд, но это был полёт.`,
q:[["Где стояло орлиное гнездо?","Высоко на скале."],["Что сделала мама-орлица?","Перелетела на соседний уступ и позвала орлёнка."],["Сколько длился первый полёт Рэя?","Десять секунд."]]},

{e:"🧵",t:"Дырка на кармане",len:"short",x:`У Насти порвался карман на любимой куртке, и она стала терять всё, что туда клала: то ключи, то монетку.
Бабушка предложила зашить, но Настя всё откладывала. Потом из кармана выпал подарок подруги — маленький брелок-звёздочка.
Настя искала его весь вечер и нашла в снегу у подъезда. В тот же день она села и зашила карман сама, с бабушкиной помощью.`,
q:[["Что случилось с курткой Насти?","Порвался карман."],["Что она потеряла из кармана?","Ключи, монетку и брелок-звёздочку от подруги."],["Что Настя сделала в тот же день?","Зашила карман сама, с помощью бабушки."]]},

{e:"🐊",t:"Крокодил, который чистил зубы",len:"short",x:`У крокодила Гены болели зубы, и он не знал, что делать: щётка для его пасти была слишком маленькой.
Птичка-зубочистка предложила помощь: она садилась крокодилу прямо в пасть и выклёвывала остатки еды между зубами.
Гена перестал бояться и открывал пасть каждое утро. Зубы у него больше не болели, а птичка была сыта. Так они и подружились.`,
q:[["Что болело у крокодила Гены?","Зубы."],["Кто ему помог?","Птичка-зубочистка."],["Что получала птичка взамен?","Она была сыта — ела остатки еды между зубами крокодила."]]},

{e:"🎒",t:"Тяжёлый рюкзак",len:"short",x:`Артём складывал в рюкзак все учебники сразу, даже те, что не нужны в этот день. Рюкзак весил как маленькая собака.
К концу недели у мальчика заболела спина. Мама показала ему расписание и предложила собирать портфель с вечера, по урокам.
Рюкзак стал вдвое легче, а времени утром — вдвое больше.`,
q:[["Почему рюкзак Артёма был тяжёлым?","Он клал туда все учебники сразу."],["Что заболело у мальчика?","Спина."],["Что посоветовала мама?","Собирать портфель с вечера по расписанию."]]},

{e:"🍂",t:"Последний лист на клёне",len:"short",x:`Осенью с клёна облетели все листья, кроме одного. Он держался за ветку изо всех сил и не хотел падать.
Ветер дул, дождь лил, а лист висел. Он думал, что если упадёт, то всё закончится.
Когда он наконец опустился на землю, то укрыл собой маленький жёлудь. Весной из этого жёлудя вылез росток. Лист не закончился — он просто стал землёй.`,
q:[["Сколько листьев осталось на клёне?","Один."],["Что лист укрыл собой, когда упал?","Маленький жёлудь."],["Что случилось весной?","Из жёлудя вылез росток."]]},

{e:"🎤",t:"Стихотворение наизусть",len:"short",x:`Ксюше задали выучить стихотворение и рассказать перед классом. Дома у зеркала получалось отлично, а у доски она забыла первую строчку.
В классе стало тихо. Учительница негромко подсказала первое слово — и стихотворение полилось само.
После урока Ксюша поняла: страшно только первые пять секунд.`,
q:[["Что задали Ксюше?","Выучить стихотворение и рассказать перед классом."],["Что случилось у доски?","Она забыла первую строчку."],["Кто помог ей вспомнить?","Учительница подсказала первое слово."]]},

{e:"🚀",t:"Ракета из картона",len:"short",x:`Братья Слава и Женя строили ракету из коробок целую неделю. Они вырезали иллюминаторы и нарисовали пульт управления.
Соседский мальчик сказал: «Она всё равно не полетит». Братья согласились: конечно, не полетит.
Но за неделю они «слетали» на Луну, на Марс и обратно, и по дороге придумали три новых игры.`,
q:[["Из чего братья строили ракету?","Из картонных коробок."],["Что сказал соседский мальчик?","Что ракета всё равно не полетит."],["Куда братья «слетали» за неделю?","На Луну, на Марс и обратно."]]},

{e:"🥁",t:"Барабан на весь дом",len:"short",x:`Тимофею подарили барабан, и он стучал по нему с утра до вечера. Соседи снизу стали стучать по батарее в ответ.
Папа не отобрал барабан, а положил на него плотное одеяло и показал, как играть тише, но ритмичнее.
Через месяц Тимофей играл так, что соседка снизу постучала снова — но уже чтобы попросить сыграть ещё раз.`,
q:[["Что подарили Тимофею?","Барабан."],["Почему соседи стучали по батарее?","Барабан был слишком громким."],["Что сделал папа?","Положил на барабан одеяло и показал, как играть тише, но ритмичнее."]]},

{e:"🐿️",t:"Бурундук и запасливый сосед",len:"short",x:`Бурундук Чип набил щёки орехами так, что не мог закрыть рот, и всё равно тянулся за новым.
Сосед-бурундук предложил: «Отнеси эти, потом вернёшься». Чип отмахнулся и попробовал взять ещё один орех — все запасы высыпались на землю.
Пока он собирал их обратно, сосед успел сделать три ходки. Чип признал, что сосед был прав.`,
q:[["Что случилось, когда Чип попробовал взять ещё один орех?","Все орехи высыпались у него изо рта на землю."],["Что предлагал сосед?","Отнести орехи домой и вернуться за новыми."],["Сколько ходок успел сделать сосед?","Три."]]},

{e:"🌡️",t:"Термометр за окном",len:"short",x:`Каждое утро Соня смотрела на термометр за окном, чтобы понять, как одеться. Однажды она посмотрела и увидела «+15».
Соня надела лёгкую кофту и вышла — на улице оказалось холодно. Оказалось, термометр висел на солнечной стороне и нагрелся от лучей.
Папа перевесил его в тень. С тех пор термометр показывал правду.`,
q:[["Зачем Соня смотрела на термометр?","Чтобы понять, как одеться."],["Почему термометр показывал неправильно?","Он висел на солнце и нагревался от лучей."],["Что сделал папа?","Перевесил термометр в тень."]]},

{e:"🎠",t:"Карусель и лошадка с трещиной",len:"short",x:`На старой карусели была лошадка с трещиной на боку, и дети всегда выбирали другие. Она стояла и ждала своей очереди годами.
Однажды на карусель пришла девочка Лена и села именно на неё. «Она особенная, у неё есть история», — сказала Лена.
С тех пор к треснувшей лошадке выстраивалась очередь: другие дети тоже захотели ту, у которой есть история.`,
q:[["Почему дети не выбирали эту лошадку?","У неё была трещина на боку."],["Что сказала Лена?","Что лошадка особенная, у неё есть история."],["Что случилось потом?","К этой лошадке стала выстраиваться очередь."]]},

{e:"📮",t:"Письмо, которое шло месяц",len:"short",x:`Егор написал письмо двоюродному брату в другой город и отнёс его на почту. Он ждал ответа каждый день и уже решил, что письмо потерялось.
Через месяц пришёл конверт с рисунком на обороте. Брат писал, что тоже ждал и что теперь они будут переписываться.
Егор хранит все эти письма в жестяной коробке из-под печенья.`,
q:[["Кому Егор написал письмо?","Двоюродному брату в другой город."],["Сколько времени он ждал ответ?","Месяц."],["Где Егор хранит письма?","В жестяной коробке из-под печенья."]]},

{e:"🐬",t:"Дельфин, который вернулся",len:"short",x:`Рыбаки нашли на мелководье молодого дельфина, запутавшегося в сетях. Они осторожно разрезали сеть и вывели его в глубокую воду.
Дельфин уплыл, и все решили, что больше его не увидят.
Но каждое лето он возвращался к этой бухте и плавал рядом с лодками. Рыбаки узнавали его по светлому пятнышку на плавнике.`,
q:[["Что случилось с молодым дельфином?","Он запутался в сетях на мелководье."],["Как рыбаки ему помогли?","Осторожно разрезали сеть и вывели его в глубокую воду."],["Как рыбаки узнавали дельфина потом?","По светлому пятнышку на плавнике."]]},

{e:"🧊",t:"Ледяная горка во дворе",len:"short",x:`Мальчишки залили во дворе горку, но она получилась кривой: одна сторона выше другой, и санки уезжали в кусты.
Самый старший, Костя, предложил не переделывать всё, а просто подлить воды на низкую сторону.
Утром горка была ровной, и кататься стало можно даже малышам.`,
q:[["Почему санки уезжали в кусты?","Горка получилась кривой — одна сторона выше другой."],["Что предложил Костя?","Подлить воды на низкую сторону."],["Какой стала горка утром?","Ровной, кататься могли даже малыши."]]},

{e:"🌼",t:"Ромашка и гадание",len:"short",x:`На лугу росла ромашка Белка. Она слышала, что люди отрывают у ромашек лепестки и загадывают желания, и очень этого боялась.
Однажды к ней подошла девочка. Белка зажмурилась. Но девочка не стала рвать лепестки — она просто понюхала цветок и сказала: «Какая красивая».
Белка выпрямилась и цвела потом до самой осени.`,
q:[["Чего боялась ромашка Белка?","Что ей оторвут лепестки."],["Что сделала девочка?","Просто понюхала цветок и похвалила его."],["До какого времени цвела Белка?","До самой осени."]]},

{e:"🦌",t:"Оленёнок и река",len:"short",x:`Стадо оленей переходило реку вброд. Оленёнок Мика встал у воды и не решался ступить: течение было быстрым.
Старый олень подошёл и встал выше по течению, загородив собой поток. За его спиной вода стала спокойной.
Мика перешёл реку по этой тихой полоске и даже не намочил спину.`,
q:[["Почему оленёнок не решался войти в реку?","Течение было слишком быстрым."],["Что сделал старый олень?","Встал выше по течению и загородил собой поток."],["Как Мика перешёл реку?","По спокойной полоске воды за спиной старого оленя."]]},

{e:"🍞",t:"Хлеб, который зачерствел",len:"short",x:`У Кости на столе остался вчерашний батон, и он хотел выбросить его: хлеб стал твёрдым.
Бабушка забрала батон, нарезала кубиками, подсушила в духовке — получились сухарики. Часть она замочила в молоке и сделала пудинг.
Костя съел всё до крошки и удивился, что «испорченный» хлеб оказался вкуснее свежего.`,
q:[["Что Костя хотел сделать с чёрствым батоном?","Выбросить его."],["Что бабушка приготовила из хлеба?","Сухарики и пудинг с молоком."],["Что удивило Костю?","Что чёрствый хлеб оказался вкуснее свежего."]]},

{e:"🐆",t:"Гепард и долгая охота",len:"short",x:`Гепард Спарк — самый быстрый зверь на свете, но бежать быстро он может только полминуты.
Молодой гепард гнался за антилопой слишком долго, выдохся и остался без обеда.
Старший научил его подкрадываться поближе перед рывком. С тех пор Спарк тратил силы не на долгую погоню, а на короткий точный бросок.`,
q:[["Сколько времени гепард может бежать быстро?","Примерно полминуты."],["Почему молодой гепард остался без обеда?","Он гнался слишком долго и выдохся."],["Чему его научил старший?","Подкрадываться поближе перед рывком."]]},

{e:"🎹",t:"Пианино у бабушки",len:"short",x:`У бабушки в комнате стояло пианино, на котором никто не играл. Крышка была закрыта, а сверху лежали салфетки и фотографии.
Внучка Вера открыла крышку и нажала одну клавишу. Звук был расстроенный, но живой.
Бабушка вызвала настройщика, и через неделю пианино зазвучало как новое. Теперь на нём играют каждый вечер.`,
q:[["Что стояло у бабушки в комнате?","Пианино, на котором никто не играл."],["Что лежало на крышке?","Салфетки и фотографии."],["Кто починил звук?","Настройщик, которого вызвала бабушка."]]},

{e:"🐍",t:"Уж, которого приняли за гадюку",len:"short",x:`У пруда жил безобидный уж Гоша. Люди его боялись и разбегались, потому что путали с гадюкой.
Однажды мальчик-натуралист остановился и объяснил друзьям: у ужа на голове два жёлтых пятнышка, будто ушки, а у гадюки их нет.
С тех пор дети перестали кричать при виде Гоши, а он перестал прятаться.`,
q:[["Почему люди боялись ужа Гошу?","Путали его с ядовитой гадюкой."],["Как отличить ужа от гадюки?","У ужа на голове два жёлтых пятнышка."],["Что изменилось после объяснения?","Дети перестали кричать, а уж перестал прятаться."]]},

{e:"🎿",t:"Первые лыжи",len:"short",x:`Марк встал на лыжи впервые и сразу поехал с горки. Он упал, потерял палку и набрал полный воротник снега.
Тренер сказал: «Сначала научись стоять и ходить по ровному, потом поедешь с горы».
Три дня Марк ходил по лыжне вдоль поля. На четвёртый он съехал с той же горки — и не упал.`,
q:[["Что случилось, когда Марк сразу поехал с горки?","Он упал, потерял палку и набрал снега за воротник."],["Что посоветовал тренер?","Сначала научиться ходить по ровному."],["Что произошло на четвёртый день?","Марк съехал с горки и не упал."]]},

{e:"🪁",t:"Воздушный змей и длинная нить",len:"short",x:`Ваня запускал воздушного змея и хотел, чтобы тот взлетел как можно выше. Он отпускал нить всё дальше и дальше.
Когда нить закончилась, мальчик подумал, что она мешает змею, и отпустил её совсем.
Змей качнулся и сразу упал в траву. Оказалось, именно натянутая нить держала его в небе.`,
q:[["Чего хотел Ваня?","Чтобы змей взлетел как можно выше."],["Что он сделал, когда нить закончилась?","Отпустил её совсем."],["Что случилось со змеем?","Он сразу упал — нить держала его в небе."]]},

{e:"🐮",t:"Молоко для всей семьи",len:"short",x:`Утром бабушка доила корову Милку, и внук Саша впервые пошёл смотреть. Он думал, что молоко просто наливают из крана.
Саша увидел, сколько это работы: подготовить, подоить, процедить, вымыть посуду. На всё ушло больше часа.
За завтраком он выпил свою кружку до дна и впервые сказал корове «спасибо».`,
q:[["Как звали корову?","Милка."],["Что Саша думал про молоко раньше?","Что его просто наливают из крана."],["Сколько времени заняла вся работа?","Больше часа."]]},

{e:"🧹",t:"Уборка за пять минут",len:"short",x:`Комната у Кати была завалена так, что не видно пола, и убираться совсем не хотелось.
Мама предложила игру: убирать не всё сразу, а по пять минут с таймером. Как только звенит — можно останавливаться.
Катя включила таймер и увлеклась: за первые пять минут она собрала все игрушки, а потом убрала комнату до конца, потому что стало интересно.`,
q:[["Почему Катя не хотела убираться?","В комнате был такой беспорядок, что не видно пола."],["Какую игру предложила мама?","Убирать по пять минут с таймером."],["Чем всё закончилось?","Катя увлеклась и убрала комнату до конца."]]},

{e:"🦇",t:"Летучая мышь и темнота",len:"short",x:`Летучая мышь Ная летала ночью и ни разу ни во что не врезалась, хотя почти ничего не видела.
Сова спросила, как ей это удаётся. Ная объяснила: она пищит, звук отражается от предметов и возвращается, и по эху она понимает, где стена, а где свободно.
Сова признала, что это не хуже, чем острое зрение.`,
q:[["Как летучая мышь находит дорогу в темноте?","Она пищит и слушает эхо, которое отражается от предметов."],["Кто спросил Наю про это?","Сова."],["Что признала сова?","Что это не хуже острого зрения."]]},

{e:"🪆",t:"Матрёшка, в которой пусто",len:"short",x:`Самая маленькая матрёшка расстроилась: внутри всех сестёр кто-то есть, а внутри неё — пустота.
Старшая матрёшка сказала: «Ты не пустая. Ты — та, ради кого нас всех открывают».
Маленькая улыбнулась. С тех пор она сидела в самой серединке с гордостью.`,
q:[["Почему маленькая матрёшка расстроилась?","Внутри неё никого не было."],["Что ответила старшая матрёшка?","Что именно ради маленькой открывают всех остальных."],["Как маленькая сидела в серединке потом?","С гордостью."]]},

{e:"🌬️",t:"Ветер и упрямый плащ",len:"short",x:`Ветер поспорил с солнцем, кто быстрее снимет с путника плащ. Ветер дул изо всех сил, но путник только сильнее запахивался.
Тогда вышло солнце и стало тихонько пригревать. Путнику стало жарко, и он снял плащ сам.
Ветер признал: иногда добром получается быстрее, чем силой.`,
q:[["О чём поспорили ветер и солнце?","Кто быстрее снимет с путника плащ."],["Что делал путник, когда дул ветер?","Ещё сильнее запахивал плащ."],["Как солнце победило?","Пригрело, путнику стало жарко, и он снял плащ сам."]]},

{e:"🧭",t:"Компас в лесу",len:"short",x:`Дедушка дал Артуру компас и научил определять стороны света: красная стрелка всегда показывает на север.
В лесу они специально свернули с тропинки, и Артур сам вывел их обратно к дороге, глядя на стрелку.
Дедушка сказал: «Главное правило леса — не паниковать и знать, куда ты шёл вначале».`,
q:[["Что показывает красная стрелка компаса?","Север."],["Кто вывел их обратно к дороге?","Артур, глядя на компас."],["Какое главное правило назвал дедушка?","Не паниковать и помнить, куда ты шёл вначале."]]},

{e:"🍪",t:"Последнее печенье",len:"short",x:`На тарелке осталось одно печенье, а в комнате были Тимур и его младшая сестра Аля.
Тимур очень хотел печенье, но разломил его пополам. Половинки получились неровные, и большую он отдал сестре.
Аля откусила кусочек, подумала — и отдала половину своей части обратно брату.`,
q:[["Сколько печенья осталось на тарелке?","Одно."],["Что сделал Тимур?","Разломил печенье пополам и отдал сестре большую половину."],["Как поступила Аля?","Отдала брату половину своего куска."]]},

{e:"🕸️",t:"Паук, который начал заново",len:"short",x:`Паук Плёт всю ночь плёл паутину между веток. Утром пришёл дождь и порвал её в клочья.
Плёт посидел, посмотрел на обрывки — и начал плести снова, только выбрал место под широким листом.
Новая паутина простояла всё лето.`,
q:[["Что случилось с первой паутиной?","Её порвал дождь."],["Что сделал паук после этого?","Начал плести заново, но под широким листом."],["Сколько простояла новая паутина?","Всё лето."]]},

{e:"🪺",t:"Гнездо на балконе",len:"short",x:`Весной на балконе у Дарьи голуби свили гнездо. Мама хотела его убрать: было грязно и шумно.
Дарья попросила подождать, пока не вылупятся птенцы. Семья два месяца выходила на балкон осторожно и не шумела.
Когда птенцы улетели, гнездо убрали. А следующей весной голуби вернулись на то же место.`,
q:[["Кто свил гнездо на балконе?","Голуби."],["О чём попросила Дарья?","Подождать, пока вылупятся птенцы."],["Что случилось следующей весной?","Голуби вернулись на то же место."]]},

{e:"🐹",t:"Хомяк на колесе",len:"short",x:`Хомяк Пуфик бегал в колесе часами и очень гордился, что пробежал «целый километр».
Морская свинка спросила: «А куда ты прибежал?» Пуфик задумался: он был на том же месте.
С тех пор он бегал в колесе для здоровья, а исследовать клетку и коридор ходил уже пешком.`,
q:[["Чем гордился хомяк Пуфик?","Что пробежал в колесе целый километр."],["Какой вопрос задала морская свинка?","Куда он прибежал."],["Как Пуфик изменил свои привычки?","Бегал в колесе для здоровья, а исследовать ходил пешком."]]},

{e:"🌟",t:"Ночь перед первым сентября",len:"short",x:`Никита не мог уснуть перед первым сентября: он думал о новой учительнице, о новых предметах и о том, найдёт ли он свой класс.
Мама села рядом и сказала: «Ты уже умеешь читать, считать, дружить и спрашивать, если непонятно. Этого достаточно на первый день».
Утром Никита нашёл свой класс сам, а к обеду у него было двое новых друзей.`,
q:[["Почему Никита не мог уснуть?","Он волновался перед первым сентября."],["Что сказала мама?","Что он уже умеет читать, считать, дружить и спрашивать — этого достаточно."],["Что случилось к обеду первого дня?","У него появилось двое новых друзей."]]},

{e:"🦔",t:"Ёжик, который не любил зиму",x:`Ёжик Кузя каждую осень грустил: скоро придётся спать всю зиму и пропустить снег, санки и ёлку.
Мама-ежиха предложила: «Давай перед сном ты нарисуешь всё, что хочешь увидеть зимой». Кузя нарисовал снеговика, коньки и подарки под ёлкой.
Рисунок он спрятал под листья у норки. Проснувшись весной, Кузя нашёл свой рисунок — и понял, что можно мечтать о зиме, даже проспав её целиком.`,
q:[["Почему ёжик Кузя грустил каждую осень?","Потому что зимой он должен был спать и пропускал снег и праздники."],["Что предложила мама-ежиха?","Нарисовать всё, что он хочет увидеть зимой."],["Что Кузя сделал с рисунком?","Спрятал его под листья у норки."]],len:"short"},

{e:"🐇",t:"Заяц, который считал шаги",x:`Зайчонок Бим боялся заблудиться в лесу и поэтому решил считать каждый свой шаг от дома.
На сотом шаге он встретил ежа, на двухсотом — белку, а на трёхсотом понял, что забыл, зачем считал, и просто заигрался с друзьями.
Домой он вернулся по своим же следам на снегу, а не по счёту шагов. Бим понял: иногда важнее не считать, а просто внимательно смотреть по сторонам.`,
q:[["Что делал зайчонок Бим, чтобы не заблудиться?","Считал каждый свой шаг от дома."],["Кого он встретил по дороге?","Ежа и белку."],["Как Бим в итоге нашёл дорогу домой?","По своим следам на снегу."]],len:"short"},

{e:"🐢",t:"Черепаха-путешественница",x:`Черепаха Тортилла всю жизнь мечтала увидеть море, но боялась, что путь будет слишком долгим.
Друзья предложили нести её по очереди, но Тортилла отказалась: «Я хочу дойти сама, даже если это займёт год».
Она шла медленно, но каждый день понемногу. Через много месяцев Тортилла увидела море своими глазами — и была уверена, что это было лучше любого подвоза.`,
q:[["О чём мечтала черепаха Тортилла?","Увидеть море."],["Что предложили ей друзья?","Нести её по очереди."],["Почему она отказалась?","Хотела дойти сама, даже если это займёт много времени."]],len:"short"},

{e:"🐦",t:"Скворец, который не хотел улетать",x:`Осенью все скворцы готовились лететь на юг, а скворец Фомка прятался в дупле: ему не хотелось покидать родной сад.
Старый скворец объяснил: «Мы улетаем не навсегда — весной вернёмся в этот же сад». Фомка выглянул и увидел, что все птицы летят вместе, дружной стаей.
Он полетел с остальными и всю зиму вспоминал сад. А весной был первым, кто вернулся к своему дуплу.`,
q:[["Почему скворец Фомка прятался в дупле?","Не хотел покидать родной сад."],["Что объяснил старый скворец?","Что они улетают не навсегда и весной вернутся."],["Кто первым вернулся к дуплу весной?","Фомка."]],len:"short"},

{e:"🐌",t:"Улитка и дождевая капля",x:`После дождя улитка Соня выползла на лист и увидела огромную каплю воды, дрожащую на самом краешке.
Соня боялась, что капля упадёт на неё, и долго обходила лист стороной. Но капля просто скатилась вниз и упала в траву, никого не задев.
Соня поняла, что боялась зря, и с тех пор смело выползала после каждого дождя, разглядывая капли вблизи.`,
q:[["Что увидела улитка Соня после дождя?","Огромную каплю воды на краешке листа."],["Чего боялась Соня?","Что капля упадёт на неё."],["Что случилось с каплей на самом деле?","Она скатилась вниз и упала в траву, никого не задев."]],len:"short"},

{e:"🐿️",t:"Белка и зимние запасы",x:`Белка Стрелка спрятала орехи в дупле, под корнями и в старом гнезде — сразу в трёх местах, чтобы точно не остаться голодной.
Зимой она забыла, где именно спрятала часть запасов, и долго искала по всему лесу. Нашла всё, но потратила на поиски целый день.
На следующую осень Стрелка завела блокнотик из берёсты и рисовала на нём, где что спрятала — так поиски стали намного быстрее.`,
q:[["Сколько тайников сделала белка Стрелка?","Три."],["Что случилось зимой?","Она забыла, где спрятала часть запасов, и долго искала."],["Что Стрелка придумала на следующую осень?","Завела блокнотик из берёсты и записывала, где что спрятала."]],len:"short"},

{e:"🦆",t:"Утка, которая учила утят плавать",x:`Утка-мама впервые повела утят на пруд. Все смело поплыли следом, кроме одного утёнка, который остался на берегу.
Мама не стала ругать его, а просто плавала рядом кругами, показывая, как это легко и весело.
Через несколько минут утёнок сам зашёл в воду — и оказалось, что плавать он умел с самого начала, просто немного стеснялся.`,
q:[["Что случилось, когда утка повела утят на пруд?","Один утёнок остался на берегу и не поплыл сразу."],["Что сделала мама-утка?","Плавала рядом кругами, показывая, как это легко."],["Чем закончилась история?","Утёнок сам зашёл в воду и поплыл."]],len:"short"},

{e:"🐹",t:"Хомяк и потерявшаяся щёчка орехов",x:`Хомяк Пушок набил защёчные мешки орехами так плотно, что не мог их разжать, когда добрался домой.
Он тряс головой, стучал лапками, но орехи не высыпались. На помощь пришла сестра Пушка и легонько нажала ему на щёки — орехи посыпались горкой.
Пушок посмеялся над собой и в следующий раз брал орехов чуть меньше, чтобы легче было донести.`,
q:[["Что случилось с защёчными мешками хомяка?","Он набил их так плотно, что не мог разжать."],["Кто помог Пушку?","Его сестра."],["Что Пушок сделал в следующий раз?","Брал орехов чуть меньше."]],len:"short"},

{e:"🐝",t:"Пчела-разведчица",x:`Пчела Дина первой находила цветочные поляны и возвращалась в улей, чтобы станцевать особый танец и показать дорогу остальным пчёлам.
Однажды Дина нашла огромное поле клевера, но заблудилась на обратном пути и весь день летала не туда.
К вечеру она всё же вспомнила дорогу по солнцу и вернулась. Танец получился таким радостным, что весь улей в тот же вечер отправился за нектаром.`,
q:[["Чем занималась пчела Дина в улье?","Первой находила поляны и показывала дорогу танцем."],["Что случилось на обратном пути?","Она заблудилась и весь день летала не туда."],["Как Дина нашла дорогу обратно?","Вспомнила её по солнцу."]],len:"short"},

{e:"🦉",t:"Совёнок и лунная дорожка",x:`Совёнок Тихон впервые летел ночью один и увидел на реке яркую серебристую дорожку от луны.
Ему захотелось долететь до конца этой дорожки, и он летел, летел — а она словно убегала всё дальше.
Мудрая сова объяснила: «Лунная дорожка всегда бежит вместе с тобой, до неё нельзя долететь — ею можно только любоваться». Тихон перестал гнаться и просто наслаждался полётом.`,
q:[["Что увидел совёнок Тихон над рекой?","Серебристую лунную дорожку."],["Что он пытался сделать?","Долететь до конца дорожки."],["Что объяснила мудрая сова?","Что до лунной дорожки нельзя долететь, ею можно только любоваться."]],len:"short"},

{e:"🐐",t:"Козлёнок, который бодался со всеми",x:`Маленький козлёнок Бяша обожал бодаться и делал это со всеми подряд — с забором, с ведром и даже с собственной тенью.
Однажды он попробовал забодать пчелиный улей и тут же об этом пожалел: пчёлы совсем не оценили шутку.
После этого случая Бяша стал бодаться только с мягким мячом, который специально для него принёс хозяин.`,
q:[["С чем обожал бодаться козлёнок Бяша?","С забором, ведром и даже своей тенью."],["Что случилось, когда он забодал улей?","Пчёлы разозлились, и ему пришлось убегать."],["С чем Бяша стал бодаться после этого?","С мягким мячом."]],len:"short"},

{e:"🐷",t:"Поросёнок и лужа",x:`Поросёнок Хрюша обожал валяться в грязной луже после дождя, а мама постоянно его за это отмывала.
Однажды Хрюша спросил, зачем вообще мыться, если завтра снова будет грязным. Мама объяснила: чистая кожа не так сильно чешется и меньше боится жары.
Хрюша не перестал любить лужи, но стал охотнее мыться после купания — оказалось, что и чистым быть тоже приятно.`,
q:[["Что обожал делать поросёнок Хрюша?","Валяться в грязной луже."],["Какой вопрос он задал маме?","Зачем вообще мыться, если завтра снова будет грязным."],["Что объяснила мама?","Что чистая кожа меньше чешется и меньше боится жары."]],len:"short"},

{e:"🐔",t:"Петух, который проспал рассвет",x:`Петух Кузьма каждое утро будил весь двор своим криком, но однажды проспал — слишком поздно лёг накануне.
Двор проснулся сам, без будильника, и все справились без него. Кузьма расстроился, решив, что он никому не нужен.
Куры объяснили: они рады слышать его крик не потому что не могут проснуться сами, а потому что с ним утро становится веселее.`,
q:[["Что случилось с петухом Кузьмой однажды утром?","Он проспал и не разбудил двор криком."],["Как проснулся двор в тот день?","Сам, без будильника."],["Что объяснили куры Кузьме?","Что с его криком утро становится веселее, а не что без него никак не обойтись."]],len:"short"},

{e:"🐈",t:"Кошка и клубок ниток",x:`Кошка Мурка нашла в корзинке для рукоделия клубок ниток и решила, что это отличная новая игрушка.
Она играла с клубком целый час, а когда наигралась, обнаружила, что размотала все нитки по всей комнате и запуталась сама.
Хозяйка не рассердилась, а посмеялась и вместе с Муркой распутывала нитки весь вечер — так они neожиданно провели время вместе.`,
q:[["Что нашла кошка Мурка в корзинке?","Клубок ниток."],["Что случилось после игры?","Нитки размотались по всей комнате, и Мурка запуталась."],["Как отреагировала хозяйка?","Не рассердилась, а вместе распутывала нитки."]],len:"short"},

{e:"🦢",t:"Лебедь и отражение в озере",x:`Молодой лебедь долго смотрел на своё отражение в тихом озере и вздыхал: ему казалось, что шея слишком длинная, а перья недостаточно белые.
Мимо проплывала утка и сказала: «А мне бы твою шею — с ней так удобно доставать водоросли со дна». Лебедь удивился: он никогда не думал об этом с такой стороны.
С тех пор он смотрелся в воду не для того, чтобы искать недостатки, а чтобы просто полюбоваться собой.`,
q:[["Чем был недоволен молодой лебедь?","Ему казалось, что шея слишком длинная, а перья недостаточно белые."],["Что сказала ему утка?","Что хотела бы такую же длинную шею, чтобы доставать водоросли."],["Как изменилось отношение лебедя к своему отражению?","Он стал смотреться в воду, чтобы полюбоваться собой, а не искать недостатки."]],len:"short"},

{e:"🐖",t:"Пятачок и первый снег во дворе",x:`Поросёнок Пятачок впервые в жизни увидел, как во дворе фермы выпал снег, и не понял, что это такое — холодное, белое и тающее в копытцах.
Он попробовал снег на вкус, покатался в сугробе и даже слепил кривой снежок, который тут же развалился.
К вечеру Пятачок так замёрз, что попросился в тёплый хлев, но пообещал себе завтра обязательно выйти играть в снег снова.`,
q:[["Что впервые увидел Пятачок?","Снег."],["Что он попробовал сделать со снегом?","Попробовал его на вкус, покатался в сугробе и слепил снежок."],["Что Пятачок сделал вечером?","Попросился в тёплый хлев погреться."]],len:"short"},

{e:"🐎",t:"Жеребёнок и первая узда",x:`Когда на жеребёнка Ветра впервые надели уздечку, он испугался и попытался её сбросить, тряся головой.
Хозяин не стал заставлять его силой, а просто держал уздечку в руках несколько дней, давая Ветру привыкнуть к её виду и запаху.
Через неделю жеребёнок сам подошёл и позволил надеть уздечку — оказалось, что не спешить было самым правильным решением.`,
q:[["Что испугало жеребёнка Ветра?","Уздечка, которую впервые на него надели."],["Что сделал хозяин вместо того, чтобы заставлять силой?","Просто держал уздечку в руках несколько дней, давая привыкнуть."],["Чем закончилась история?","Через неделю жеребёнок сам подошёл и позволил надеть уздечку."]],len:"short"},

{e:"🐑",t:"Овечка, потерявшая стадо",x:`Овечка Пуша отстала от стада, увлёкшись вкусной травой у ручья, и, подняв голову, никого не увидела рядом.
Она заблеяла громко и жалобно, как учила мама: «Потерялся — не беги, а зови». Пастуший пёс услышал блеяние и быстро нашёл Пушу.
С тех пор Пуша всегда держалась поближе к стаду, но травку у ручья вспоминала с удовольствием.`,
q:[["Почему овечка Пуша отстала от стада?","Увлеклась вкусной травой у ручья."],["Что она сделала, поняв, что потерялась?","Громко и жалобно заблеяла, как учила мама."],["Кто нашёл Пушу?","Пастуший пёс."]],len:"short"},

{e:"🦅",t:"Орёл и маленькая пичужка",x:`Огромный орёл кружил высоко над горами и однажды заметил маленькую пичужку, которая никак не могла взлететь на невысокую скалу.
Орёл хотел просто отнести её наверх в клюве, но передумал и вместо этого стал показывать, как правильно расправлять крылья и ловить поток ветра.
Пичужка поднялась сама, хоть и не так высоко, как орёл, — и была этому рада гораздо больше, чем если бы её просто отнесли.`,
q:[["Кого заметил орёл над горами?","Маленькую пичужку, которая не могла взлететь на скалу."],["Что орёл сначала хотел сделать?","Отнести её наверх в клюве."],["Что он сделал вместо этого?","Показал, как расправлять крылья и ловить поток ветра."]],len:"short"},

{e:"🐁",t:"Мышонок и большая тень",x:`Мышонок Тишка увидел на стене огромную страшную тень и с писком спрятался под шкаф, решив, что в доме завёлся великан.
Он просидел там до вечера, пока не набрался смелости выглянуть — и увидел, что тень отбрасывала обычная настольная лампа и стоящая рядом чашка.
Тишка посмеялся над собой и с тех пор перед тем, как пугаться, всегда проверял, что на самом деле отбрасывает тень.`,
q:[["Что напугало мышонка Тишку?","Огромная тень на стене."],["Где он прятался?","Под шкафом."],["Что на самом деле отбрасывало тень?","Настольная лампа и чашка рядом с ней."]],len:"short"},

{e:"🐊",t:"Крокодильчик, который боялся воды",x:`Маленький крокодильчик Гоша, как ни странно, боялся заходить в реку — вода казалась ему слишком холодной и тёмной.
Мама-крокодилиха не заставляла его, а просто каждый день заходила в воду сама и звала его поплавать рядом с берегом, на мелководье.
Через неделю Гоша сам вошёл в воду по колено, а ещё через месяц плавал не хуже других крокодилят в самой середине реки.`,
q:[["Чего боялся крокодильчик Гоша?","Заходить в реку."],["Что делала мама-крокодилиха?","Каждый день заходила в воду сама и звала его на мелководье."],["Чем закончилась история?","Через месяц Гоша плавал не хуже других крокодилят."]],len:"short"},

{e:"🦩",t:"Фламинго, который стоял на двух ногах",x:`Молодой фламинго Роза никак не могла научиться стоять на одной ноге, как все взрослые фламинго в стае, и очень из-за этого расстраивалась.
Старая фламинго объяснила: «Не всем нужно стоять одинаково — главное, чтобы тебе самой было удобно и не холодно». Роза попробовала снова, но уже без напряжения, просто ради интереса.
Через какое-то время у неё само собой получилось постоять на одной ноге целую минуту — просто потому, что она перестала стараться специально.`,
q:[["Чему не могла научиться молодая фламинго Роза?","Стоять на одной ноге, как взрослые фламинго."],["Что объяснила старая фламинго?","Что не всем нужно стоять одинаково, главное — чтобы было удобно."],["Как в итоге получилось у Розы?","Получилось само собой, когда она перестала стараться специально."]],len:"short"},

{e:"🐡",t:"Рыба-шар и её колючки",x:`Рыбка Пуфи умела раздуваться в колючий шар при малейшей опасности, но делала это так часто, что другие рыбы стали её избегать.
Мудрый осьминог заметил: «Колючки нужны против настоящей опасности, а не против каждой тени». Пуфи задумалась и решила проверять, действительно ли опасность рядом, прежде чем раздуваться.
Скоро она подружилась со многими рыбками — оказалось, что без постоянных колючек с ней намного приятнее общаться.`,
q:[["Что умела делать рыбка Пуфи?","Раздуваться в колючий шар при опасности."],["Почему другие рыбы стали её избегать?","Она делала это слишком часто, даже без настоящей опасности."],["Что посоветовал мудрый осьминог?","Проверять, действительно ли опасность рядом, прежде чем раздуваться."]],len:"short"},

{e:"🦫",t:"Бобрёнок и сломанная плотина",x:`Ночью сильный ливень размыл часть плотины, которую всей семьёй строили бобры, и утром бобрёнок Тим увидел дыру, через которую утекала вся вода.
Он испугался и хотел позвать на помощь всю семью сразу, но решил сначала попробовать заткнуть дыру одной толстой веткой сам.
Ветка помогла продержаться, пока не подоспели остальные бобры с материалом для ремонта. Тим гордился, что не растерялся и хоть немного, но помог первым.`,
q:[["Что случилось с плотиной ночью?","Сильный ливень размыл часть плотины."],["Что сначала попробовал сделать Тим?","Заткнуть дыру одной толстой веткой сам."],["Чем гордился Тим в конце?","Тем, что не растерялся и помог первым."]],len:"short"},

{e:"🐫",t:"Верблюжонок и первая пустыня",x:`Верблюжонок Кеша впервые пересекал настоящую пустыню вместе с караваном и удивлялся, почему все идут медленно и размеренно, а не бегут.
Мама объяснила: в пустыне важно беречь силы, ведь воды и тени здесь не найти на каждом шагу. Кеша попробовал бежать вперёд — и быстро устал.
После этого он пошёл в общем неторопливом темпе и с удивлением заметил, что именно так они добрались до оазиса быстрее всех, без остановок на отдых.`,
q:[["Что удивляло верблюжонка Кешу в пустыне?","Почему все идут медленно, а не бегут."],["Что объяснила мама?","Что в пустыне важно беречь силы."],["Что случилось, когда Кеша попробовал бежать?","Он быстро устал."]],len:"short"},

{e:"🦥",t:"Ленивец, который никуда не спешил",x:`Ленивец Слоу свисал с ветки и медленно жевал листок, пока все остальные звери суетились вокруг в поисках еды.
Обезьянка спросила: «Тебе не скучно так медленно жить?» Слоу ответил, что он просто успевает заметить закат, форму облаков и песню каждой птицы — а те, кто спешат, это часто пропускают.
Обезьянка задумалась и в тот вечер впервые за долгое время просто села рядом и посмотрела на закат вместе со Слоу.`,
q:[["Что делал ленивец Слоу на ветке?","Медленно жевал листок."],["Что спросила у него обезьянка?","Не скучно ли ему так медленно жить."],["Что ответил Слоу?","Что он успевает заметить закат, облака и песни птиц."]],len:"short"},

{e:"🦦",t:"Выдра и скользкий камень",x:`Выдрёнок Плюх обожал кататься с горки прямо в реку, но однажды поскользнулся на мокром камне ещё до того, как добрался до воды.
Он ушибся и сначала решил больше никогда не кататься. Но папа-выдра показал, что нужно просто выбирать не мокрые, а сухие камни для разбега.
На следующий день Плюх снова катался с горки — теперь уже безопасно и ещё веселее прежнего.`,
q:[["Что обожал делать выдрёнок Плюх?","Кататься с горки прямо в реку."],["Что случилось однажды?","Он поскользнулся на мокром камне и ушибся."],["Что показал папа-выдра?","Выбирать сухие камни для разбега."]],len:"short"},

{e:"🐍",t:"Змейка, которая сбрасывала кожу",x:`Молодая змейка Ася впервые почувствовала, что старая кожа стала ей тесной, и очень испугалась, не понимая, что происходит.
Мудрый уж успокоил её: все змеи время от времени сбрасывают старую кожу, потому что растут, и под ней всегда есть новая, свежая.
Ася нашла шершавый камень, потёрлась об него — и старая кожа сползла целиком. Новая кожа блестела на солнце ярче прежней.`,
q:[["Что почувствовала молодая змейка Ася?","Что старая кожа стала ей тесной."],["Что объяснил мудрый уж?","Что все змеи время от времени сбрасывают старую кожу, потому что растут."],["Как Ася избавилась от старой кожи?","Потёрлась о шершавый камень."]],len:"short"},

{e:"🦜",t:"Попугай, который повторял чужие слова",x:`Попугай Кеша умел повторять любые слова, но однажды случайно повторил грубое слово, которое услышал на улице, и хозяйка расстроилась.
Кеша не понимал, что сделал не так — ведь он просто повторил звук. Хозяйка терпеливо объяснила: слова бывают добрыми и обидными, и повторять стоит только добрые.
С тех пор Кеша стал внимательнее прислушиваться и радовал всех гостей только вежливыми фразами: «Привет!», «Спасибо!» и «Хорошего дня!»`,
q:[["Что случайно повторил попугай Кеша?","Грубое слово, услышанное на улице."],["Как отреагировала хозяйка?","Расстроилась и объяснила разницу между добрыми и обидными словами."],["Каким фразам Кеша радовал гостей потом?","«Привет!», «Спасибо!» и «Хорошего дня!»"]],len:"short"},

{e:"🐬",t:"Дельфинёнок и эхолокация",x:`Маленький дельфинёнок Спрайт никак не мог понять, как его мама находит рыбу в мутной воде, ведь глазами там почти ничего не видно.
Мама объяснила: она издаёт особые щелчки, а звук отражается от рыбы и возвращается обратно — так она «видит» ушами.
Спрайт долго тренировался щёлкать и слушать эхо, и через месяц уже сам находил маленьких рыбок даже с закрытыми глазами.`,
q:[["Что не мог понять дельфинёнок Спрайт?","Как мама находит рыбу в мутной воде."],["Как мама-дельфин находит рыбу?","Издаёт щелчки и слушает эхо, отражённое от рыбы."],["Чему научился Спрайт через месяц?","Находить рыбок с закрытыми глазами, используя эхо."]],len:"short"},

{e:"🐺",t:"Волчонок и первая охота",x:`Волчонок Север впервые пошёл на настоящую охоту вместе со стаей, но так волновался, что спугнул зайца раньше времени громким рычанием.
Вожак стаи не рассердился, а спокойно объяснил: на охоте важна тишина и терпение, а рычать можно уже после, когда добыча поймана.
На следующей охоте Север сдержался, промолчал всю дорогу — и именно он первым заметил след, который привёл стаю к добыче.`,
q:[["Что случилось на первой охоте волчонка Севера?","Он спугнул зайца громким рычанием."],["Что объяснил вожак стаи?","Что на охоте важны тишина и терпение."],["Что произошло на следующей охоте?","Север первым заметил след, который привёл стаю к добыче."]],len:"short"},

{e:"🦔",t:"Ёж и яблоко на спине",x:`Ёжик Колючка нашёл в саду упавшее яблоко и решил перекатиться на него спиной, чтобы наколоть на иголки и унести домой, как делают взрослые ежи.
С первого раза не получилось — яблоко всё время соскальзывало. Колючка попробовал ещё раз, потом ещё, и на пятый раз яблоко наконец удержалось на спине.
Домой он шёл гордый и уставший, а мама встретила его словами: «Ты справился сам — это гораздо ценнее, чем если бы я тебе сразу помогла».`,
q:[["Что нашёл ёжик Колючка в саду?","Упавшее яблоко."],["Что он пытался с ним сделать?","Наколоть на иголки на спине и унести домой."],["Со скольки попытки у него получилось?","С пятой."]],len:"short"},

{e:"🐄",t:"Телёнок, который боялся грозы",x:`Маленький телёнок Рыжик очень боялся грома и во время грозы прятался за самую большую корову в стаде.
Однажды гроза застала его на дальнем пастбище одного, без стада. Рыжик вспомнил, что говорила мама: «Гром — это просто громкий звук, он не может тебя тронуть».
Он лёг под дерево, зажмурился и переждал грозу сам, а когда она закончилась, почувствовал, что стал немного смелее прежнего.`,
q:[["Чего боялся телёнок Рыжик?","Грома во время грозы."],["Где обычно прятался Рыжик?","За самой большой коровой в стаде."],["Что он вспомнил, оказавшись один во время грозы?","Слова мамы, что гром — это просто громкий звук."]],len:"short"},

{e:"🐭",t:"Мышка-модница",x:`Мышка Крутышка обожала наряжаться в кусочки ткани и ленточки, которые находила по всему дому, и очень гордилась своими нарядами.
Другие мыши посмеивались: «Зачем тебе это, ты же всё равно живёшь в норке?» Крутышка не обижалась и продолжала наряжаться — ей просто было весело.
Однажды на мышином празднике именно её наряды понравились всем больше остальных, и с тех пор Крутышку стали звать главной по украшению норок.`,
q:[["Что обожала делать мышка Крутышка?","Наряжаться в кусочки ткани и ленточки."],["Как реагировали на это другие мыши?","Посмеивались и спрашивали, зачем ей это."],["Чем закончилась история?","На празднике её наряды понравились всем больше остальных."]],len:"short"},

{e:"🦋",t:"Мотылёк и уличный фонарь",x:`Мотылёк Огонёк каждую ночь летел прямо к яркому уличному фонарю, хотя старшие мотыльки предупреждали, что это опасно.
Однажды он подлетел слишком близко и опалил себе краешек крыла. Пришлось несколько дней отсиживаться под листом, пока крыло не зажило.
После этого случая Огонёк стал летать вокруг фонаря на безопасном расстоянии — света было видно так же хорошо, а опасности намного меньше.`,
q:[["Куда каждую ночь летел мотылёк Огонёк?","К яркому уличному фонарю."],["Что случилось однажды?","Он подлетел слишком близко и опалил крыло."],["Как Огонёк стал летать после этого?","На безопасном расстоянии от фонаря."]],len:"short"},

{e:"🐨",t:"Коала и новый эвкалипт",x:`Коала Куки всю жизнь ела листья только с одного знакомого дерева и наотрез отказывалась пробовать соседнее — оно казалось ей чужим и странным.
Когда листья на привычном дереве закончились, Куки долго голодала, прежде чем решилась попробовать соседний эвкалипт.
Оказалось, что листья там ничуть не хуже, а дерево даже выше и уютнее. С тех пор Куки не боялась пробовать новое, если старое вдруг заканчивалось.`,
q:[["С какого дерева обычно ела коала Куки?","С одного знакомого дерева."],["Что случилось, когда листья на нём закончились?","Куки долго голодала, прежде чем попробовать соседнее дерево."],["Каким оказалось соседнее дерево?","Ничуть не хуже, а даже выше и уютнее."]],len:"short"},

{e:"🐗",t:"Кабанчик и грязевая ванна",x:`Кабанчик Хрюн обожал валяться в тёплой грязи после жаркого дня — так он охлаждался и защищался от насекомых.
Однажды более взрослый кабан объяснил ему, зачем на самом деле нужна грязевая ванна: она защищает кожу от солнечных ожогов и укусов.
Хрюн стал относиться к купанию в грязи не просто как к развлечению, а как к важному и полезному делу — и стал делать это ещё охотнее.`,
q:[["Что обожал делать кабанчик Хрюн?","Валяться в тёплой грязи после жаркого дня."],["Зачем на самом деле нужна грязевая ванна кабанам?","Защищает кожу от ожогов и укусов насекомых."],["Как изменилось отношение Хрюна к купанию в грязи?","Он стал относиться к этому как к важному и полезному делу."]],len:"short"},

{e:"🐦‍⬛",t:"Ворона и блестящая пуговица",x:`Ворона Клара обожала собирать всё блестящее и однажды нашла на дороге яркую серебристую пуговицу.
Она унесла находку в гнездо и очень ею гордилась, показывая всем соседним воронам. Но однажды прилетел мальчик и грустно искал что-то на той же дороге — оказалось, он потерял пуговицу от любимой куртки.
Клара, к своему удивлению, вернула находку мальчику, положив её на подоконник. Взамен он оставил для неё кусочек хлеба — и с тех пор они стали добрыми знакомыми.`,
q:[["Что обожала собирать ворона Клара?","Всё блестящее."],["Что она нашла на дороге?","Яркую серебристую пуговицу."],["Чем закончилась история?","Клара вернула пуговицу мальчику, а он оставил ей хлеб — они стали знакомыми."]],len:"short"},

{e:"🦭",t:"Тюленёнок на льдине",x:`Маленький тюленёнок Плюша впервые остался на льдине один, пока мама уплыла за рыбой, и очень испугался холодного ветра и тишины.
Он вспомнил, что мама говорила: «Даже если страшно, лежи спокойно — толстый слой жира греет тебя лучше любой шубы».
Плюша свернулся клубочком и стал ждать. Совсем скоро мама вернулась с рыбой, а тюленёнок понял, что справился с одиночеством сам.`,
q:[["Что случилось с тюленёнком Плюшей?","Он остался один на льдине, пока мама уплыла за рыбой."],["Что он вспомнил, испугавшись?","Слова мамы, что толстый слой жира греет лучше шубы."],["Чем закончилась история?","Мама вернулась, а Плюша понял, что справился сам."]],len:"short"},

{e:"🐊",t:"Крокодил и цапля-помощница",x:`У старого крокодила Грома болел зуб, застрявший в нём кусочек рыбьей кости, но сам он достать его никак не мог.
Мимо пролетала цапля, и Гром, немного стесняясь, попросил о помощи. Цапля аккуратно залезла клювом ему в пасть и вытащила косточку.
С тех пор они подружились: цапля часто садилась Грому на спину отдохнуть, а он никогда её не трогал, хоть и мог бы легко поймать.`,
q:[["Что случилось с зубом крокодила Грома?","В нём застрял кусочек рыбьей кости."],["Кто ему помог?","Цапля."],["Что происходило после этого случая?","Цапля часто садилась Грому на спину отдохнуть, а он её не трогал."]],len:"short"},

{e:"🦎",t:"Ящерка и оторванный хвост",x:`Маленькая ящерка Зося убегала от птицы и в последний момент оторвала себе хвост — так спаслись многие ящерицы до неё.
Сначала Зося очень расстроилась, что осталась без хвоста, и стеснялась показываться другим ящеркам.
Но через несколько недель хвост отрос заново — новый, чуть короче прежнего, но такой же ловкий. Зося поняла, что даже большая потеря иногда бывает временной.`,
q:[["Как спаслась ящерка Зося от птицы?","Оторвала себе хвост."],["Что она почувствовала после этого?","Расстроилась и стеснялась показываться другим."],["Что случилось через несколько недель?","Хвост отрос заново, чуть короче прежнего."]],len:"short"},

{e:"🐂",t:"Бык и красная тряпка",x:`Молодой бычок Буян почему-то злился каждый раз, когда видел на ветру красный платок соседского мальчика, и начинал фырчать и бить копытом.
Старый бык объяснил: дело не в цвете, а в том, что резкое движение ткани пугает и раздражает. Спокойный красный цвет сам по себе не значит ничего плохого.
Буян понаблюдал за неподвижным красным одеялом на заборе — и совсем не разозлился. С тех пор он злился только на резкие движения, а не на цвета.`,
q:[["На что злился бычок Буян?","На красный платок, который развевался на ветру."],["Что объяснил старый бык?","Что дело не в цвете, а в резком движении ткани."],["Что понял Буян, наблюдая за неподвижным одеялом?","Что цвет сам по себе ничего плохого не значит."]],len:"short"},

{e:"🐘",t:"Слонёнок и хобот-помощник",x:`Слонёнок Тоша долго не мог понять, зачем ему такой длинный хобот — он всё время путался под ногами и мешал бегать.
Мама-слониха показала: хоботом можно доставать высокие ветки, пить воду, обливаться в жару и даже здороваться с другими слонами.
Тоша попробовал каждое из этих действий — и хобот вдруг перестал казаться лишним. Он оказался самым полезным инструментом на свете.`,
q:[["Что не понимал слонёнок Тоша?","Зачем ему такой длинный хобот."],["Что показала мама-слониха?","Что хоботом можно доставать ветки, пить воду и обливаться."],["Как изменилось отношение Тоши к хоботу?","Он перестал казаться лишним и стал казаться самым полезным."]],len:"short"},

{e:"🦡",t:"Барсук-домосед",x:`Барсук Кузьма обожал свою уютную нору и почти никогда не выходил дальше соседней полянки, хотя лес вокруг был огромным и интересным.
Друг-ёж позвал его на прогулку к дальнему ручью, и Кузьма долго отказывался — а вдруг там неуютно?
В итоге он всё же пошёл и увидел столько нового: рыбок в ручье, необычные цветы, эхо среди скал. Домой он вернулся довольным и решил гулять почаще.`,
q:[["Что обожал барсук Кузьма?","Свою уютную нору."],["Куда его позвал друг-ёж?","К дальнему ручью."],["Что Кузьма решил после прогулки?","Гулять почаще."]],len:"short"},

{e:"🐓",t:"Курица, которая не умела летать высоко",x:`Курица Рябушка завидовала воробьям, которые легко взлетали на самое высокое дерево, а она сама еле перепрыгивала через забор.
Петух объяснил ей: у каждой птицы своё дело — курица хорошо ищет червячков и высиживает яйца, а летать высоко ей вовсе не обязательно.
Рябушка перестала завидовать воробьям и с гордостью вывела в тот год целых восемь пушистых цыплят — то, чего воробьи делать не умели.`,
q:[["Кому завидовала курица Рябушка?","Воробьям, которые легко взлетали высоко."],["Что объяснил ей петух?","Что у каждой птицы своё дело, и летать высоко курице необязательно."],["Чем гордилась Рябушка в конце?","Что вывела восемь пушистых цыплят."]],len:"short"},

{e:"🐕",t:"Щенок, который лаял на всё подряд",x:`Щенок Тузик лаял на любой шорох, любую тень и даже на собственный хвост — соседи начали жаловаться на шум.
Хозяин терпеливо стал показывать Тузику разные звуки и предметы днём, при свете, чтобы щенок понял: большинство из них совсем не страшные.
Через пару недель Тузик стал лаять только на настоящих незнакомцев у калитки, а на листья и тени просто спокойно смотрел.`,
q:[["На что лаял щенок Тузик?","На любой шорох, тень и даже на свой хвост."],["Что стал делать хозяин?","Показывать Тузику разные звуки и предметы днём, при свете."],["На что Тузик стал лаять через пару недель?","Только на настоящих незнакомцев у калитки."]],len:"short"},

{e:"🐁",t:"Мышонок-строитель",x:`Мышонок Пик увидел, как птицы вьют гнёзда, и решил построить себе не обычную норку, а целый мышиный домик из веточек, как у птиц.
Первая попытка развалилась в первую же ночь, вторая — от лёгкого дождя. Пик расстроился, но не сдался и стал изучать, как именно птицы переплетают веточки.
Третий домик получился крепким и простоял всю зиму. Пик гордился, что не сдался после первых неудач.`,
q:[["Что решил построить мышонок Пик?","Домик из веточек, как у птиц."],["Что случилось с первыми двумя попытками?","Они развалились — одна за ночь, другая от дождя."],["Чем закончилась история?","Третий домик получился крепким и простоял всю зиму."]],len:"short"},

{e:"🐇",t:"Кролик и морковная грядка соседа",x:`Кролик Пушистик очень хотел морковку с соседской грядки, но точно знал, что брать чужое без спроса нельзя.
Он набрался смелости и постучался к соседу-ёжику с вопросом, можно ли попробовать хотя бы одну морковку.
Ёжик не только разрешил, но и подарил Пушистику несколько морковок с собой — оказалось, что честно спросить было куда приятнее, чем тайком воровать.`,
q:[["Чего очень хотел кролик Пушистик?","Морковку с соседской грядки."],["Что он сделал вместо того, чтобы взять её тайком?","Постучался к соседу-ёжику и спросил разрешения."],["Чем закончилась история?","Ёжик разрешил и подарил ему несколько морковок."]],len:"short"},

{e:"🗺️",t:"Клад дядюшки Филина",x:`В старом дупле на краю леса жил филин по имени Филимон, известный всем как дядюшка Филин. Он был мудрым, но очень скрытным: никто не знал, что он прячет в самой глубине своего дупла.
Однажды к нему прибежали трое друзей — ёжик Кузя, белка Стрелка и зайчонок Бим. Они услышали от старой вороны, будто у дядюшки Филина спрятан настоящий клад.
«Клад? — удивился филин. — Ну что ж, идёмте, покажу». Друзья, затаив дыхание, полезли за ним в дупло, ожидая увидеть золото или драгоценные камни.
Внутри оказалась вовсе не гора монет. На полках аккуратными рядами стояли банки с сушёными грибами, коробочки с семенами редких растений, свиток с картой всех родников леса и толстая тетрадь, исписанная мелким почерком.
«Это мой клад, — сказал Филимон. — Здесь я записываю всё, что узнал за долгую жизнь: где растёт целебная трава, когда прилетают перелётные птицы, как пережить самую суровую зиму». 
Друзья сначала расстроились — ведь никакого золота не было. Но когда Бим случайно заболел животом, именно баночка с сушёной ромашкой из «клада» дядюшки Филина быстро поставила его на ноги.
С того дня зверята стали часто заглядывать к филину — не за золотом, а за знаниями. И вскоре поняли: то, что помогает выживать и решать настоящие проблемы, порой ценнее любых сокровищ.
Через год у каждого из друзей появилась своя маленькая тетрадка, куда они тоже начали записывать то, что узнавали сами. А дядюшка Филин с гордостью говорил всем, что его клад теперь не единственный в лесу.`,
q:[["Что друзья ожидали найти у дядюшки Филина?","Золото или драгоценные камни."],["Что на самом деле оказалось в дупле филина?","Банки с грибами и семенами, карта родников и тетрадь с записями."],["Что случилось, когда заболел зайчонок Бим?","Баночка с сушёной ромашкой из «клада» помогла ему выздороветь."],["Что сделали друзья через год?","Завели свои тетрадки и тоже начали записывать то, что узнавали."]],len:"long"},

{e:"🌊",t:"Маяк на краю бухты",x:`На самом краю рыбацкой деревни стоял старый маяк, и каждую ночь его свет разрезал темноту, помогая кораблям находить дорогу домой. Хранителем маяка был пожилой человек по имени дед Архип, а его верным помощником — мальчик Тимоша, который прибегал к маяку после школы.
Однажды осенью налетел сильный шторм, и хуже всего было то, что именно в эту ночь сломалась лампа маяка. Дед Архип попытался её починить, но руки уже не слушались его так, как раньше — суставы болели от сырой погоды.
«Тимоша, — сказал дед, — беги в деревню за фонарями, любыми, какие найдёшь. Без света корабли могут разбиться о скалы». Мальчик со всех ног побежал по мокрым камням, стуча в каждую дверь.
Соседи не задавали вопросов — услышав про шторм и маяк, каждый доставал свой керосиновый фонарь и отдавал Тимоше. Скоро у мальчика в руках было уже двенадцать фонарей, а рыбаки помогали нести остальные.
Всей деревней они выстроили фонари в ряд на верхней площадке маяка, там, где раньше светила большая лампа. Свет получился не таким ярким и ровным, но зато его было видно издалека, и он не гас.
В ту ночь в бухту заходил рыболовный баркас капитана Северова, застигнутый штормом в море. Позже он рассказывал, что именно мерцающий ряд огоньков на маяке показал ему, где безопасный вход в бухту, и спас корабль от скал.
Наутро, когда шторм утих, дед Архип обнял Тимошу и сказал: «Ты сегодня сделал то, что не под силу одному старику — собрал целую деревню ради одной цели». С тех пор в деревне завели правило: у каждого дома всегда должен быть готовый фонарь на случай шторма.`,
q:[["Кто были главные герои этой истории?","Дед Архип, хранитель маяка, и мальчик Тимоша, его помощник."],["Что случилось с лампой маяка во время шторма?","Она сломалась, и дед Архип не смог её починить сам."],["Что сделал Тимоша, чтобы помочь?","Обежал деревню и собрал у соседей керосиновые фонари."],["Чем закончилась история?","Свет от собранных фонарей спас корабль капитана Северова от скал."]],len:"long"},

{e:"🎈",t:"Воздушный шар над городом",x:`В маленьком городке жил изобретатель по имени Тео, который много лет мечтал построить настоящий воздушный шар и полететь на нём выше всех городских крыш. Соседи посмеивались над его чертежами, разложенными прямо во дворе, но Тео не сдавался.
Наконец шар был готов: огромный, полосатый, сшитый из старых занавесок и парусины. В корзину под шаром Тео посадил своего любимого кота Барсика — для компании — и, дождавшись безветренного утра, отвязал последнюю верёвку.
Шар медленно поднялся над крышами, и весь город высыпал на улицы посмотреть на это чудо. Дети махали руками, пекарь у своей лавки уронил поднос с булочками от удивления, а почтальон забыл, куда нёс письма.
Но на высоте случилось непредвиденное: неожиданный порыв ветра понёс шар в сторону от города, к тёмному лесу. Тео начал волноваться — топлива для горелки оставалось немного, а карты той стороны леса у него не было.
Барсик, до этого мирно дремавший в корзине, вдруг встревоженно замяукал и стал смотреть в одну сторону. Тео, доверившись коту, направил шар именно туда — и увидел просвет между деревьями, похожий на широкую поляну.
Приземление получилось не самым мягким — корзина протащилась по траве и остановилась у самого края поляны. Тео и Барсик были целы, хотя изрядно перепуганы. К вечеру их нашли жители соседней деревни, услышавшие странный шум с неба.
Историю о полёте на самодельном шаре потом рассказывали в городке ещё много лет. А Тео, вернувшись домой, повесил на стену не чертежи нового шара, а фотографию Барсика — своего верного штурмана, который в трудную минуту не подвёл.`,
q:[["О чём много лет мечтал изобретатель Тео?","Построить воздушный шар и полететь выше городских крыш."],["Кого Тео взял с собой в полёт?","Своего кота Барсика."],["Что пошло не так во время полёта?","Порыв ветра понёс шар в сторону тёмного леса, а топлива было мало."],["Кто помог найти безопасное место для посадки?","Кот Барсик — он смотрел в сторону поляны, и Тео туда направил шар."]],len:"long"},

{e:"🏔️",t:"Тропа к вершине Снежной горы",x:`В горной деревушке каждый год устраивали состязание: кто первым взойдёт на вершину Снежной горы и зажжёт там сигнальный костёр. В этом году впервые решил попробовать силы юный пастух по имени Ерлан, хотя все считали его слишком молодым для такого испытания.
С самого начала подъёма Ерлан отставал от опытных горцев — они шли уверенно, зная тропу наизусть, а он то и дело останавливался свериться с картой. К полудню он оказался совсем один, остальные ушли далеко вперёд.
На середине пути начался снегопад, видимость упала почти до нуля. Ерлан испугался и хотел повернуть назад, но вспомнил слова своего деда: «Если заблудился в снегу — ищи следы других, они всегда приведут к безопасному месту».
Он присел и стал внимательно рассматривать снег вокруг — и правда, заметил едва видимые вмятины от ботинок ушедших вперёд горцев. Медленно, шаг за шагом, Ерлан пошёл по этим следам, стараясь не потерять их из виду.
Снегопад усиливался, и в какой-то момент следы почти исчезли под свежим снегом. Тогда Ерлан достал из сумки маленький компас, подаренный дедом, и стал сверяться с ним, продолжая идти в направлении вершины.
Когда снег наконец стих, Ерлан с удивлением обнаружил, что вершина уже совсем близко — и оказался там даже раньше некоторых опытных горцев, которые пережидали снегопад в укрытии на середине склона.
Зажигая сигнальный костёр на вершине, Ерлан думал не о победе, а о словах деда, которые его спасли. Спустившись, он первым делом подошёл к деду и крепко обнял его за науку.
С тех пор в деревне говорили, что настоящий горец — не тот, кто идёт быстрее всех, а тот, кто умеет не растеряться, когда тропа теряется под снегом.`,
q:[["Какое состязание проходило каждый год в горной деревушке?","Кто первым взойдёт на вершину Снежной горы и зажжёт сигнальный костёр."],["Что случилось с Ерланом на середине пути?","Начался сильный снегопад, и видимость упала почти до нуля."],["Что помогло ему не заблудиться сначала?","Он пошёл по следам ушедших вперёд горцев."],["Что он использовал, когда следы исчезли под снегом?","Компас, подаренный дедом."]],len:"long"},

{e:"🎭",t:"Тайна старого театра",x:`В городе давно закрыли старый театр — говорили, что здание обветшало и опасно для посещения. Но каждую пятницу вечером из-за плотно закрытых ставен доносилась тихая музыка, и жители обходили здание стороной, шёпотом называя его призрачным театром.
Девочка Лиза, которая жила по соседству и обожала истории, решила разгадать эту тайну. Она рассказала о своих планах лучшему другу Ване, и вместе они решили пробраться внутрь через щель в заколоченной боковой двери.
Внутри было пыльно и темно, но откуда-то издалека действительно доносилась музыка — скрипучая, но узнаваемая мелодия старого вальса. Друзья, держась за руки, пошли на звук по скрипучим коридорам.
За кулисами главной сцены они обнаружили пожилую женщину в потрёпанном, но некогда роскошном платье — она сидела за старым граммофоном и медленно кружилась в танце совсем одна на пустой сцене.
Женщина, увидев детей, ничуть не испугалась и не рассердилась. Она представилась: когда-то, много лет назад, она была прима-балериной этого театра, и здесь прошла вся её молодость и слава.
Когда театр закрыли из-за нехватки денег, она не смогла с этим расстаться — стала тайно приходить сюда по пятницам, включать старый граммофон и вспоминать лучшие годы своей жизни, кружась под музыку в пустом зале.
Лиза и Ваня не просто сохранили её секрет — они рассказали о нём в городской газете, но так тепло и уважительно, что жители города вместо того, чтобы возмутиться, собрали деньги на ремонт крыши старого театра.
Через полгода театр снова открылся — и на торжественном вечере именно пожилая балерина, уже совсем не таясь, станцевала свой любимый вальс перед полным залом, а Лиза с Ваней сидели в первом ряду.`,
q:[["Что жители города слышали каждую пятницу из закрытого театра?","Тихую музыку."],["Кого Лиза и Ваня обнаружили в театре?","Пожилую женщину — бывшую прима-балерину театра."],["Почему она тайно приходила туда по пятницам?","Чтобы включить граммофон и вспомнить лучшие годы своей жизни, танцуя."],["Чем закончилась история?","Театр отремонтировали, и балерина станцевала перед полным залом."]],len:"long"},

{e:"🧭",t:"Экспедиция за пропавшим компасом",x:`Клуб юных путешественников готовился к главному походу года — трёхдневной экспедиции к дальнему водопаду. Руководителем похода назначили самого опытного участника клуба, двенадцатилетнего Максима, который отвечал за карту и старинный компас клуба, передававшийся из поколения в поколение.
В первый же вечер похода, разбивая лагерь у реки, ребята обнаружили страшную новость: компас пропал. Максим точно помнил, что клал его в боковой карман рюкзака, но там было пусто.
Ребята обыскали весь лагерь, перетрясли рюкзаки, но компаса нигде не было. Кто-то из младших участников начал паниковать: без компаса, говорили некоторые, дорогу назад к водопаду и обратно к городу найти будет сложно.
Максим, стараясь сохранять спокойствие, предложил план: они пойдут по солнцу и по приметам, которые изучали на занятиях клуба — мох на северной стороне деревьев, направление течения реки, положение солнца в разное время суток.
Весь следующий день группа шла, ориентируясь именно так, и, к удивлению даже самого Максима, они вышли точно к водопаду — ничуть не хуже, чем если бы у них был компас.
На обратном пути, разбирая рюкзаки у водопада, один из младших участников, Петя, смущённо признался: он взял компас поиграть накануне похода и случайно засунул его в свой собственный рюкзак, забыв переложить обратно.
Максим не стал ругать Петю — вместо этого он собрал всех у костра и сказал: «Пропажа компаса оказалась лучшим уроком похода — мы узнали, что умеем находить дорогу и без него, полагаясь на знания и внимательность».
С тех пор в клубе завели традицию: раз в поход специально «терять» компас и проходить часть маршрута только по природным приметам — чтобы каждый новый участник учился доверять не только приборам, но и собственным знаниям.`,
q:[["За что отвечал Максим в этом походе?","За карту и старинный компас клуба."],["Что случилось в первый вечер похода?","Обнаружилось, что компас пропал."],["Как ребята нашли дорогу к водопаду без компаса?","Ориентировались по солнцу, мху на деревьях и течению реки."],["Что выяснилось про компас в конце?","Петя случайно взял его поиграть и забыл переложить обратно в общий рюкзак."]],len:"long"},

{e:"🍂",t:"Осенний сад бабушки Веры",x:`Каждую осень бабушка Вера приглашала внуков помочь собрать урожай в своём большом саду, и в этом году впервые приехали сразу трое — Аля, Гриша и их двоюродный брат Тимофей, который никогда раньше не был в деревне.
Тимофей, выросший в большом городе, поначалу смотрел на сад с недоверием — он привык к магазинным яблокам ровной формы и не понимал, зачем возиться в земле, если можно всё купить.
Бабушка Вера не стала спорить, а просто дала ему в руки корзину и повела к старой яблоне, которую сама посадила ещё девочкой, вместе со своим отцом.
«Эта яблоня старше меня на два года, — сказала бабушка. — Я собирала с неё яблоки, когда была такой же, как ты, потом собирала твоя мама, теперь твоя очередь». Тимофей впервые задумался, что у еды из магазина такой истории нет.
Втроём с Алей и Гришей они собирали яблоки весь день: забирались по лестнице, аккуратно снимали плоды, чтобы не помять, складывали в большие плетёные корзины. Тимофей неожиданно для себя увлёкся и даже придумал соревнование — кто найдёт самое большое яблоко.
Вечером бабушка испекла из части урожая большой яблочный пирог, а остальные яблоки они вместе перебрали и разложили по деревянным ящикам для хранения на зиму — так, как учила бабушка, чтобы яблоки не портились.
За ужином, уплетая тёплый пирог, Тимофей признался, что этот вкус ни капли не похож на магазинный — не потому, что яблоки были особенными, а потому что он сам их собирал, своими руками, зная историю дерева.
Уезжая обратно в город, Тимофей увёз с собой не только банку варенья из бабушкиного сада, но и решение: в следующем году он приедет снова, и, может быть, посадит рядом со старой яблоней свою собственную.`,
q:[["Кто впервые приехал в деревню в этом году?","Тимофей, двоюродный брат Али и Гриши."],["Почему Тимофей поначалу с недоверием смотрел на сад?","Он привык к магазинным яблокам и не понимал, зачем возиться в земле."],["Что рассказала бабушка про старую яблоню?","Что она посадила её ещё девочкой вместе со своим отцом."],["Что решил Тимофей, уезжая домой?","Приехать снова в следующем году и, возможно, посадить свою яблоню."]],len:"long"},

{e:"🚂",t:"Последний рейс паровоза Громыхало",x:`Старый паровоз по имени Громыхало много лет возил пассажиров между двумя маленькими городками, но с появлением новых быстрых поездов его собирались отправить на списание — то есть навсегда поставить в депо и больше не выпускать на пути.
Машинист Громыхало, дядя Стёпа, проработавший с этим паровозом всю жизнь, очень грустил из-за такого решения. В депо готовили торжественную церемонию последнего рейса, чтобы попрощаться с паровозом достойно.
В день последнего рейса на вокзал пришло гораздо больше людей, чем ожидали организаторы: жители обоих городков, для которых паровоз десятилетиями был не просто транспортом, а символом связи между их домами.
Среди пассажиров оказалась пожилая женщина, которая когда-то, много лет назад, именно на этом паровозе познакомилась со своим будущим мужем. Пришёл и мужчина, вспомнивший, как ребёнком впервые ехал на этом паровозе к бабушке в гости.
Дядя Стёпа, узнав об этих историях, предложил начальнику депо необычную идею: не списывать паровоз полностью, а превратить его в музей на колёсах, который раз в месяц будет выезжать на короткие праздничные рейсы для горожан.
Идею одобрили. В последний рейс Громыхало отправился не с грустным прощальным гудком, а с весёлым, праздничным — ведь это было не прощание, а начало нового пути.
С тех пор раз в месяц, в первую субботу, старый паровоз выходит на рельсы, и горожане приходят прокатиться, послушать его знакомый гудок и рассказать своим детям истории о том, как Громыхало когда-то возил их бабушек и дедушек.
Дядя Стёпа по-прежнему работает машинистом, только теперь у него появилась новая должность — хранитель истории паровоза, и он с удовольствием рассказывает каждому новому пассажиру, сколько всего повидал старый Громыхало за свою долгую жизнь.`,
q:[["Что собирались сделать со старым паровозом Громыхало?","Списать и поставить в депо навсегда."],["Кто такой дядя Стёпа?","Машинист, проработавший с этим паровозом всю жизнь."],["Какую идею он предложил вместо списания?","Превратить паровоз в музей на колёсах для праздничных рейсов."],["Чем закончилась история?","Паровоз стал раз в месяц выезжать на праздничные рейсы, а дядя Стёпа — рассказывать его историю."]],len:"long"},

{e:"🐧",t:"Пингвинёнок, который потерялся в тумане",x:`На антарктическом берегу жила большая колония пингвинов, и каждый день взрослые пингвины уходили в море за рыбой, оставляя малышей в общей группе под присмотром нескольких нянек.
Пингвинёнок Кокос был очень любопытным и однажды, увидев вдалеке что-то блестящее на льду, тихонько отошёл от группы, чтобы рассмотреть находку поближе.
Пока он разглядывал обычный кусок льда, показавшийся ему сокровищем, налетел густой туман — такой плотный, что Кокос совсем перестал видеть, куда идти обратно.
Он звал маму, но голос тонул в тумане, и никто не откликался. Кокос очень испугался и сначала начал бегать в разные стороны, что только сильнее его запутало.
Тут он вспомнил, чему учила его няня: если потерялся, нужно остановиться, прислушаться и идти на звук прибоя — ведь колония всегда селится недалеко от воды, и шум волн слышен издалека даже в тумане.
Кокос замер, затаил дыхание и действительно различил вдалеке ровный гул волн. Он медленно, шаг за шагом, пошёл на этот звук, останавливаясь и снова прислушиваясь, чтобы не сбиться с пути.
Через какое-то время туман поредел, и Кокос увидел знакомые очертания скал у колонии, а вскоре различил и голос своей мамы, которая уже вернулась с рыбалки и с тревогой искала его среди других малышей.
Мама крепко прижала Кокоса и сказала: «Самое важное — не паниковать, а вспомнить, чему тебя учили». С тех пор Кокос всегда держался рядом с группой, но урок про звук прибоя запомнил на всю жизнь и позже сам рассказывал его младшим пингвинятам.`,
q:[["Почему пингвинёнок Кокос отошёл от группы?","Увидел вдалеке что-то блестящее на льду и решил рассмотреть."],["Что случилось, пока он разглядывал находку?","Налетел густой туман, и он перестал видеть дорогу назад."],["Что помогло Кокосу найти дорогу к колонии?","Он пошёл на звук прибоя, который слышен издалека даже в тумане."],["Что сказала ему мама в конце?","Что самое важное — не паниковать, а вспомнить, чему учили."]],len:"long"},

{e:"🎻",t:"Скрипач с чердака",x:`В доме номер семь на тихой улице жил мальчик по имени Данила, который каждый вечер слышал сквозь потолок тихую и немного печальную скрипичную музыку, доносящуюся будто бы с чердака.
Родители говорили, что на чердаке никто не живёт, кроме старых вещей и пыли, но музыка звучала так ясно, что Данила решил разобраться сам, пока родители были на работе.
Поднявшись по скрипучей лестнице, он обнаружил, что чердак действительно завален коробками, но в самом углу, у маленького окна, сидел пожилой мужчина со скрипкой — сосед из квартиры этажом выше, которого все звали просто дедом Виктором.
Дед Виктор объяснил, что раньше был настоящим скрипачом в городском оркестре, но после того как его жена умерла несколько лет назад, он не мог заставить себя играть дома — слишком много воспоминаний было связано с их общей квартирой.
Чердак стал для него единственным местом, где получалось снова взять в руки скрипку — здесь было тихо, спокойно, и никто не напоминал так остро о прошлом.
Данила, вместо того чтобы просто уйти, тихо сел рядом и попросил научить его хотя бы паре нот. Дед Виктор удивился такой просьбе, но согласился — и с того дня мальчик стал приходить на чердак каждый вечер после уроков.
Через несколько месяцев Данила уже мог сыграть простую мелодию, а дед Виктор, к своему удивлению, снова начал улыбаться и даже согласился сыграть на школьном концерте вместе со своим юным учеником.
На концерте, когда зазвучала их дуэтная мелодия, дед Виктор впервые за долгое время играл не с грустью, а с настоящей радостью — рядом с ним снова был кто-то, кому была так же дорога музыка.`,
q:[["Что слышал Данила каждый вечер сквозь потолок?","Тихую и печальную скрипичную музыку."],["Кого он нашёл на чердаке?","Пожилого соседа, деда Виктора, со скрипкой."],["Почему дед Виктор играл именно на чердаке, а не дома?","Дома было слишком много воспоминаний о жене после её смерти."],["Чем закончилась история?","Данила научился играть, и они вместе выступили на школьном концерте."]],len:"long"},

{e:"🌵",t:"Оазис старого каравана",x:`Много лет назад в пустыне проходил торговый путь, по которому шли караваны верблюдов, и посреди пути был единственный оазис — маленький источник воды среди пальм, спасавший путников от жажды.
Хранителем оазиса была семья, жившая там уже много поколений, и главным в семье теперь был юноша по имени Юсуф, который недавно принял это дело от своего отца.
Однажды случилась долгая засуха, и источник начал мелеть день за днём. Юсуф с тревогой наблюдал, как уровень воды падает, понимая, что если источник высохнет полностью, ближайшие караваны могут не пережить переход через пустыню.
Он вспомнил старые рассказы деда о том, что глубоко под оазисом должна быть подземная река, питающая источник, но её русло могло сместиться со временем из-за движения песков.
Юсуф вместе с двумя помощниками начал копать новый колодец в стороне от старого, ориентируясь по едва заметным признакам: более зелёной траве в одном месте и особому холодку, который иногда ощущался под ногами.
Работа была тяжёлой и долгой — три недели они копали под палящим солнцем, и уже начинали сомневаться в успехе, когда наконец лопата наткнулась на влажный песок, а затем показалась вода.
Новый колодец оказался даже полноводнее старого — видимо, подземная река действительно сместилась, как предполагал дед. Юсуф аккуратно обложил колодец камнями и посадил рядом молодые пальмы.
Когда следующий караван подошёл к оазису, измученные жаждой путники не поверили своим глазам, увидев чистую прохладную воду там, где ожидали найти высохшую землю. С тех пор оазис Юсуфа стал известен по всему торговому пути как самое надёжное место для отдыха.`,
q:[["Кто такой Юсуф в этой истории?","Юноша, хранитель оазиса, принявший дело от отца."],["Что случилось с источником воды во время засухи?","Он начал мелеть день за днём и мог высохнуть полностью."],["Что вспомнил Юсуф про подземную реку?","Рассказы деда о том, что она питает источник, но могла сместиться."],["Чем закончились поиски воды?","Через три недели они нашли новый, даже более полноводный источник."]],len:"long"},

{e:"🎨",t:"Художница без красок",x:`В маленьком городке жила девочка по имени Соня, которая больше всего на свете любила рисовать, но её семья была небогатой, и денег на настоящие краски почти никогда не хватало.
Соня рисовала чем придётся: угольком из костра, соком ягод, разведённой в воде глиной разных оттенков — и каждый раз огорчалась, что цвета получались тусклыми и быстро выцветали.
Однажды в город приехала передвижная выставка известного художника, и Соня, скопив мелочь с обедов, купила самый дешёвый билет, чтобы хоть одним глазком увидеть настоящие картины и, может быть, разузнать секрет ярких красок.
На выставке она разговорилась со смотрительницей — пожилой женщиной, которая, выслушав историю девочки, отвела её в маленькую комнату за залом, где хранились использованные, но ещё не до конца высохшие тюбики красок, которые художник обычно выбрасывал.
Смотрительница предложила Соне брать эти остатки — их всё равно собирались выкинуть, а для девочки, умеющей экономно выдавливать последние капли, их могло хватить надолго.
Соня стала приходить туда каждую неделю, и постепенно у неё собралась целая небольшая коллекция настоящих красок — не новых, но самых настоящих, ярких и стойких.
Она начала рисовать с ещё большим увлечением, и через год одна из её картин — портрет той самой доброй смотрительницы — попала на местную выставку детского творчества и заняла первое место.
Получая награду, Соня рассказала всю историю про остатки красок, и с того дня многие художники города стали специально откладывать использованные тюбики для юных художников, у которых, как и у неё когда-то, не было денег на новые.`,
q:[["Чем рисовала Соня, когда не было денег на краски?","Угольком, соком ягод и разведённой глиной."],["Кто помог Соне на выставке художника?","Пожилая смотрительница зала."],["Что смотрительница предложила Соне?","Брать остатки красок в тюбиках, которые всё равно выбрасывали."],["Чем закончилась история?","Картина Сони заняла первое место, и художники города стали помогать юным художникам красками."]],len:"long"},

{e:"🏰",t:"Хранитель старого замка",x:`На вершине холма стоял старинный замок, который давно превратили в музей, и каждый день туда приходили туристы посмотреть на рыцарские доспехи, старинную мебель и высокие каменные башни.
Хранителем замка много лет работал пожилой мужчина по имени господин Альберт, который знал о замке буквально всё — каждый потайной ход, каждую историю, связанную со старинными вещами.
Однажды в музей на экскурсию пришёл школьный класс, и среди детей был мальчик Костя, который совсем не интересовался историей и откровенно скучал, разглядывая свой телефон вместо экспонатов.
Господин Альберт заметил скучающего мальчика и, отделившись от общей группы, подошёл к нему с неожиданным предложением: «Хочешь узнать настоящий секрет замка, которого нет в учебниках?»
Костя удивился и согласился. Хранитель отвёл его к незаметной каменной панели у камина, слегка нажал в определённом месте — и панель со скрипом отъехала в сторону, открывая узкий потайной проход.
Оказалось, что в средние века этим ходом пользовались, чтобы незаметно предупредить защитников замка о приближении врагов, и по легенде именно этот проход однажды спас всех жителей замка от внезапного нападения.
Костя, забыв про телефон, засыпал хранителя вопросами: кто построил ход, сколько раз им пользовались, что было бы, если бы враги его нашли. Господин Альберт с удовольствием отвечал на каждый вопрос.
После экскурсии Костя первым подбежал к учительнице и попросил разрешения прийти в замок ещё раз в выходные — уже не по школьному заданию, а просто потому, что ему стало по-настоящему интересно. С тех пор он приходил в замок почти каждую субботу, а через несколько лет сам стал водить экскурсии для младших школьников.`,
q:[["Кем был господин Альберт в этой истории?","Хранителем старинного замка-музея."],["Каким сначала показал себя мальчик Костя на экскурсии?","Скучающим, разглядывающим телефон вместо экспонатов."],["Что показал ему хранитель замка?","Потайной ход у камина, которым пользовались в средние века."],["Чем закончилась история?","Костя увлёкся историей замка и через несколько лет сам стал водить экскурсии."]],len:"long"},

{e:"🐿️",t:"Бельчонок и жёлудь-путешественник",x:`Бельчонок Орех уронил жёлудь с высокой ветки, и тот покатился по склону холма, а бельчонок бросился следом, боясь потерять находку.
Жёлудь катился всё дальше — через полянку, мимо ручья — а Орех бежал за ним, не замечая, как далеко забрался от дома.
Наконец жёлудь остановился у корней большого дуба. Оглядевшись, Орех понял, что оказался в совсем новой части леса — и, довольный, решил исследовать её, прежде чем вернуться домой с добычей.`,
q:[["Что уронил бельчонок Орех?","Жёлудь."],["Что делал жёлудь, пока катился?","Катился через полянку и мимо ручья."],["Что понял Орех, когда жёлудь остановился?","Что оказался в совсем новой части леса."]],len:"short"},

{e:"🐣",t:"Цыплёнок, который вылупился последним",x:`Из шести яиц в гнезде первым вылупился бойкий цыплёнок Жёлтик, а последним — маленький и тихий Пушок, который появился только через два дня после остальных.
Пушок стеснялся, что он меньше и слабее братьев, и держался в стороне от общих игр.
Но именно Пушок первым заметил во дворе опасность — соседского кота — и громко запищал, предупредив всех. С тех пор братья стали звать его не самым слабым, а самым внимательным цыплёнком в семье.`,
q:[["Каким вылупился цыплёнок Пушок по счёту?","Последним, через два дня после остальных."],["Почему Пушок держался в стороне от игр?","Стеснялся, что он меньше и слабее братьев."],["Чем прославился Пушок в итоге?","Первым заметил опасность и предупредил всех."]],len:"short"},

{e:"🦨",t:"Скунсёнок, который не хотел пахнуть",x:`Скунсёнок Пшик стеснялся своего природного умения — распылять неприятный запах при опасности, и мечтал быть просто милым, как кролики по соседству.
Однажды на скунсиную семью напала лиса, и только запах Пшика заставил хищника с визгом убежать прочь, спасая всех.
После этого случая Пшик перестал стесняться своей особенности — оказалось, то, что казалось ему недостатком, было настоящей суперспособностью, защищающей всю его семью.`,
q:[["Чего стеснялся скунсёнок Пшик?","Своего умения распылять неприятный запах."],["Что случилось однажды с семьёй скунсов?","На них напала лиса."],["Что спасло семью?","Запах Пшика, который отпугнул лису."]],len:"short"},

{e:"🐦",t:"Воробей и первая метель",x:`Молодой воробей Чик впервые увидел настоящую метель и очень испугался — снег закручивался так сильно, что не было видно даже соседнего дерева.
Старая ворона показала ему укромное место под карнизом крыши, где ветер почти не чувствовался, а снег не заносил совсем.
Чик пересидел там всю метель в тепле и безопасности, а утром, когда снег стих, впервые в жизни покатался на кучке пушистого снега, забыв про вчерашний страх.`,
q:[["Что впервые увидел воробей Чик?","Настоящую метель."],["Кто помог ему найти укрытие?","Старая ворона."],["Что Чик сделал утром после метели?","Покатался на кучке пушистого снега."]],len:"short"},

{e:"🐝",t:"Пчёлка, которая боялась цветов с шипами",x:`Пчёлка Жужа собирала нектар со всех цветов подряд, кроме роз — их шипы казались ей слишком опасными.
Другие пчёлы объяснили: шипы растут только на стебле, а не на самом цветке, и если садиться аккуратно прямо на бутон, шипы вообще не страшны.
Жужа осторожно попробовала — и оказалось, что розовый нектар один из самых вкусных в саду. С тех пор она перестала бояться и стала одной из немногих пчёл, которые не пропускали ни одной розы.`,
q:[["Какие цветы избегала пчёлка Жужа?","Розы, из-за шипов."],["Что объяснили ей другие пчёлы?","Что шипы растут на стебле, а не на самом цветке."],["Что Жужа обнаружила, попробовав розы?","Что розовый нектар один из самых вкусных."]],len:"short"},

{e:"🐴",t:"Пони, который не хотел носить попону",x:`Маленький пони Смородинка терпеть не мог носить тёплую попону зимой — она казалась ему тяжёлой и неудобной, и он всё время пытался её сбросить.
Однажды особенно морозной ночью Смородинка сбросил попону во сне и утром проснулся продрогшим и уставшим.
Хозяйка укутала его снова и объяснила: попона — это не наказание, а забота. С тех пор Смородинка сам подставлял спину, когда видел, что хозяйка идёт с попоной.`,
q:[["Что не любил носить пони Смородинка?","Тёплую попону зимой."],["Что случилось однажды морозной ночью?","Он сбросил попону во сне и утром замёрз."],["Как Смородинка стал вести себя после этого?","Сам подставлял спину, когда видел попону."]],len:"short"},

{e:"🐄",t:"Коровка и колокольчик подружки",x:`У коровы Марты был красивый медный колокольчик, а у её подружки Зорьки — простой, без узоров, и Зорька из-за этого немного грустила.
Марта заметила это и предложила меняться колокольчиками по очереди — один день носит одна, другой день другая.
Оказалось, что дело было вовсе не в колокольчике: Зорьке просто нравилось внимание подружки, а обычный колокольчик звучал ничуть не хуже красивого.`,
q:[["Из-за чего грустила корова Зорька?","Её колокольчик был проще, чем у подружки Марты."],["Что предложила Марта?","Меняться колокольчиками по очереди."],["Что поняла Зорька в итоге?","Что дело было не в колокольчике, а во внимании подружки."]],len:"short"},

{e:"🦊",t:"Лисёнок, который хотел быть волком",x:`Лисёнок Рыжик восхищался волками из соседней стаи — они казались ему сильными и смелыми, и он мечтал быть похожим на них, а не на обычную лису.
Он попробовал выть по-волчьи, ходить их широким шагом, но у него получалось смешно и неубедительно.
Старая лиса объяснила: у лис есть своя ловкость и хитрость, которых нет у волков. Рыжик перестал подражать и стал гордиться именно лисьими качествами — быстротой и смекалкой.`,
q:[["Кем восхищался лисёнок Рыжик?","Волками из соседней стаи."],["Что он пытался делать?","Выть по-волчьи и ходить их широким шагом."],["Что объяснила старая лиса?","Что у лис есть своя ловкость и хитрость, которых нет у волков."]],len:"short"},

{e:"🐢",t:"Черепашонок и гонка улиток",x:`Черепашонок Тоша, к своему удивлению, проиграл гонку даже улитке — все смеялись, что черепахи вроде бы должны быть быстрее.
Тоша расстроился, но дедушка-черепах объяснил: улитка скользит по гладкому листу, а черепаха идёт по земле, и сравнивать их скорость на разных поверхностях нечестно.
На следующей гонке по камням Тоша легко обогнал улитку — просто гонки нужно было устраивать на подходящей трассе для каждого.`,
q:[["Кому проиграл гонку черепашонок Тоша?","Улитке."],["Что объяснил ему дедушка-черепах?","Что сравнивать скорость на разных поверхностях нечестно."],["Чем закончилась история?","На гонке по камням Тоша легко обогнал улитку."]],len:"short"},

{e:"🐰",t:"Зайчиха и слишком большая нора",x:`Зайчиха Пуговка выкопала себе огромную нору с несколькими входами, надеясь, что так будет безопаснее от лисы.
Но оказалось, что в такой большой норе легко заблудиться самой, и однажды Пуговка сама не могла найти выход, пока не услышала снаружи голос соседки.
После этого случая Пуговка немного сузила нору, оставив только два хорошо запомненных входа — и стало намного удобнее и спокойнее.`,
q:[["Что выкопала зайчиха Пуговка?","Огромную нору с несколькими входами."],["Какая проблема возникла из-за большой норы?","Она сама заблудилась в ней."],["Что Пуговка сделала после этого случая?","Сузила нору, оставив только два входа."]],len:"short"},

{e:"🐗",t:"Кабан и упрямый пень",x:`Молодой кабан Секач решил во что бы то ни стало вырыть из земли старый трухлявый пень, который мешал ему рыть землю в поисках корешков.
Пень оказался неожиданно крепким — Секач бился с ним весь день, но пень не поддавался ни на сантиметр.
К вечеру на помощь пришли ещё два кабана, и втроём они наконец справились. Секач понял: иногда даже самому сильному нужна помощь друзей.`,
q:[["Что решил вырыть кабан Секач?","Старый трухлявый пень."],["Смог ли он справиться один?","Нет, пень оказался неожиданно крепким."],["Кто помог ему в итоге?","Ещё два кабана."]],len:"short"},

{e:"🦫",t:"Бобриха и новый сосед",x:`Бобриха Липа очень не хотела, чтобы рядом с её плотиной поселилась семья ондатр — боялась, что они будут мешать и портить запруду.
Ондатры оказались тихими и аккуратными соседями, а вскоре ещё и помогли залатать небольшую течь в плотине, которую сама Липа не заметила.
Липа поняла, что судила соседей заранее, даже не познакомившись с ними, и с тех пор они с ондатрами часто вместе чинили плотину.`,
q:[["Кого не хотела видеть соседями бобриха Липа?","Семью ондатр."],["Чем на самом деле оказались ондатры?","Тихими и аккуратными соседями, которые даже помогли с ремонтом."],["Что поняла Липа в итоге?","Что судила соседей заранее, не познакомившись."]],len:"short"},

{e:"🐤",t:"Утёнок и первое перо",x:`У утёнка Кряка выпало первое пушистое перышко, и он испугался, решив, что заболел или что-то с ним не так.
Мама-утка успокоила его: это значит, что скоро на месте пуха вырастут настоящие крепкие перья, с которыми можно будет летать.
Кряк стал с нетерпением ждать, когда же появятся новые перья, и каждое утро проверял себя в отражении пруда.`,
q:[["Что случилось с утёнком Кряком?","У него выпало первое пушистое перышко."],["Чего он испугался?","Решил, что заболел."],["Что объяснила мама-утка?","Что на месте пуха вырастут настоящие крепкие перья."]],len:"short"},

{e:"🐖",t:"Свинка и грязные копытца",x:`Свинка Хрюша каждый раз расстраивалась, что её копытца быстро становятся грязными, сколько бы её ни мыли перед выставкой домашних животных.
Фермер объяснил: грязь на копытцах — это нормально для свиней, судьи на выставке оценивают не чистоту, а здоровье и ум животного.
На выставке Хрюша, несмотря на слегка испачканные копытца, показала лучшие трюки и получила приз за сообразительность.`,
q:[["Из-за чего расстраивалась свинка Хрюша?","Её копытца быстро становились грязными."],["Что объяснил ей фермер?","Что судьи оценивают здоровье и ум, а не чистоту."],["Чем закончилась история?","Хрюша получила приз за сообразительность."]],len:"short"},

{e:"🦉",t:"Совята и школа полётов",x:`В дупле жили три совёнка, и двое из них быстро научились летать, а третий, самый младший, всё никак не решался прыгнуть с ветки.
Братья не смеялись над ним, а просто летали рядом каждый вечер, показывая, как легко расправлять крылья и ловить воздушный поток.
Через неделю младший совёнок наконец прыгнул — и полетел ничуть не хуже братьев, просто ему нужно было немного больше времени.`,
q:[["Сколько совят жило в дупле?","Три."],["Что не мог сделать младший совёнок?","Решиться прыгнуть с ветки и полететь."],["Как братья ему помогали?","Летали рядом каждый вечер, показывая, как это делать."]],len:"short"},

{e:"🐍",t:"Ужиха и переправа через ручей",x:`Ужиха Свея каждый год переплывала один и тот же ручей, но в этом году после дождей течение стало заметно сильнее обычного.
Свея попробовала плыть напрямик, как всегда, но её начало сносить в сторону от привычного берега.
Тогда она поплыла наискосок, используя течение вместо того чтобы с ним бороться, и благополучно выбралась на нужный берег — просто чуть дальше, чем обычно.`,
q:[["Что каждый год делала ужиха Свея?","Переплывала один и тот же ручей."],["Что изменилось в этом году?","Течение стало заметно сильнее из-за дождей."],["Как Свея справилась с сильным течением?","Поплыла наискосок, используя течение вместо борьбы с ним."]],len:"short"},

{e:"🐇",t:"Крольчонок и морковная грядка зимой",x:`Крольчонок Снежок расстроился, что зимой на грядке не осталось ни одной морковки — все, что выросло осенью, они с семьёй уже съели.
Мама показала ему кладовую в норе, где ещё с осени лежали морковки, аккуратно пересыпанные сухим песком для хранения.
Снежок был счастлив узнать, что запасливость мамы спасла их от голода — и решил в следующем году сам помогать делать такие запасы.`,
q:[["Что расстроило крольчонка Снежка зимой?","На грядке не осталось моркови."],["Что показала ему мама?","Кладовую с морковками, пересыпанными песком для хранения."],["Что решил Снежок?","В следующем году сам помогать делать запасы."]],len:"short"},

{e:"🐌",t:"Улитка, которая хотела дом побольше",x:`Улитка Клуша считала свой домик-раковину слишком маленьким и тесным и завидовала соседской улитке с более крупной раковиной.
Она попробовала заползти в пустую раковину покрупнее, найденную у пруда, но та не подошла — оказалось слишком свободно и неудобно двигаться.
Клуша поняла, что раковина растёт вместе с самой улиткой, точно по размеру — и вернулась в свой родной, уютный домик с облегчением.`,
q:[["Чем была недовольна улитка Клуша?","Считала свой домик слишком маленьким."],["Что она попробовала сделать?","Заползти в чужую раковину покрупнее."],["Что поняла Клуша в итоге?","Что раковина растёт вместе с улиткой, точно по размеру."]],len:"short"},

{e:"🐆",t:"Детёныш леопарда и пятна",x:`Маленький леопард Спот расстраивался, что все его пятна разного размера и формы, а он мечтал о ровных одинаковых пятнышках, как на картинках в книжке.
Мама-леопард объяснила: у каждого леопарда пятна уникальны, как отпечатки пальцев у людей, и это помогает маме всегда узнать своего детёныша среди других.
Спот стал гордиться своими неровными пятнами — оказалось, это не недостаток, а его личная особенность, которой ни у кого больше нет.`,
q:[["Чем был недоволен леопард Спот?","Тем, что его пятна разного размера и формы."],["Что объяснила мама?","Что пятна у каждого леопарда уникальны, как отпечатки пальцев."],["Как Спот стал относиться к своим пятнам?","Стал ими гордиться."]],len:"short"},

{e:"🐊",t:"Крокодилёнок и слишком много зубов",x:`Крокодилёнок Зубастик стеснялся своей широкой улыбки с множеством острых зубов и старался пореже улыбаться при других зверятах.
Однажды маленькая цапля попала в беду — запуталась лапкой в водорослях, и никто не мог её освободить, боясь пораниться острыми стеблями.
Зубастик аккуратно перекусил водоросли своими зубами и освободил цаплю. С тех пор он понял: то, чего он стеснялся, оказалось очень полезным умением.`,
q:[["Чего стеснялся крокодилёнок Зубастик?","Своей широкой улыбки с острыми зубами."],["Что случилось с цаплей?","Она запуталась лапкой в водорослях."],["Как Зубастик помог ей?","Перекусил водоросли своими зубами."]],len:"short"},

{e:"🦌",t:"Оленёнок и первые рога",x:`У оленёнка Рогалика начали расти первые маленькие рожки, и он очень гордился этим, показывая их всем подряд в лесу.
Другой оленёнок посмеялся: «Да это же совсем крошечные, у меня будут больше». Рогалик расстроился и перестал хвастаться.
Старый олень объяснил обоим: рога растут у каждого в своё время, и гордиться нужно не размером, а тем, что они вообще появились — это значит, что оленёнок взрослеет.`,
q:[["Что начало расти у оленёнка Рогалика?","Первые маленькие рожки."],["Что сказал ему другой оленёнок?","Что у него будут рога больше."],["Что объяснил старый олень?","Что рога растут у каждого в своё время, и гордиться нужно не размером."]],len:"short"},

{e:"🐁",t:"Мышка и часы с кукушкой",x:`Мышка Тиша поселилась за стеной старых часов с кукушкой и каждый час пугалась громкого «ку-ку», выпрыгивая из своей норки.
Со временем она заметила, что кукушка появляется всегда ровно вовремя, и стала использовать её крик, чтобы понимать, сколько времени.
Так Тиша неожиданно для себя научилась определять час по числу «ку-ку» — и перестала бояться, а даже начала с нетерпением ждать следующего часа.`,
q:[["Где поселилась мышка Тиша?","За стеной старых часов с кукушкой."],["Что её сначала пугало?","Громкое «ку-ку» каждый час."],["Чему она научилась со временем?","Определять час по числу «ку-ку»."]],len:"short"},

{e:"🐕",t:"Пёс и потерянная косточка",x:`Пёс Дружок закопал во дворе любимую косточку, чтобы съесть её позже, но, вернувшись через день, никак не мог вспомнить точное место.
Он перекопал полдвора, но так и не нашёл её, пока хозяин случайно не наткнулся на косточку, подстригая газон.
Дружок с тех пор стал закапывать косточки только в одном приметном месте — у большого камня — чтобы больше никогда их не терять.`,
q:[["Что закопал пёс Дружок?","Любимую косточку."],["Что случилось, когда он вернулся за ней?","Не смог вспомнить точное место и не нашёл её."],["Кто нашёл косточку?","Хозяин, подстригая газон."]],len:"short"},

{e:"🦩",t:"Фламинго и розовый цвет",x:`Маленький фламинго Пинки родился совсем белым и переживал, что никогда не станет розовым, как остальные взрослые фламинго в стае.
Мудрая фламинго объяснила: розовый цвет появляется постепенно от особой еды — маленьких рачков, которых едят фламинго, и нужно просто немного подождать и правильно питаться.
Пинки старательно ел рачков каждый день, и уже через несколько месяцев его перья начали розоветь — сначала чуть-чуть, а потом всё ярче.`,
q:[["Каким цветом родился фламинго Пинки?","Белым."],["Из-за чего он переживал?","Что никогда не станет розовым."],["Что помогло ему порозоветь?","Особая еда — маленькие рачки."]],len:"short"},

{e:"🐟",t:"Рыбка и зеркальная поверхность пруда",x:`Маленькая рыбка Искра каждый вечер видела в спокойной глади пруда своё отражение и думала, что там живёт ещё одна такая же рыбка-подружка.
Она пыталась заговорить с отражением, но та рыбка всегда просто повторяла её движения и никогда не отвечала.
Старая черепаха объяснила Искре, что это просто отражение, а не другая рыбка. Искра немного погрустила, но зато теперь точно знала, как красиво она выглядит в воде.`,
q:[["Что видела рыбка Искра каждый вечер?","Своё отражение в глади пруда."],["Что она пыталась сделать?","Заговорить с отражением, думая, что это другая рыбка."],["Кто объяснил ей правду?","Старая черепаха."]],len:"short"},

{e:"🐑",t:"Барашек, который боялся стричься",x:`Барашек Кудряш видел, как других овец стригут ножницами, и очень боялся, что ему будет больно, поэтому убегал каждый раз, когда подходил пастух.
Мама-овца успокоила его: стрижка похожа на стрижку волос у людей — совсем не больно, ведь состригают только шерсть, а не кожу.
Кудряш решился попробовать и с удивлением понял, что это было щекотно, но совсем не страшно. После стрижки ему стало гораздо легче и прохладнее.`,
q:[["Чего боялся барашек Кудряш?","Что стрижка будет больно."],["Что объяснила мама-овца?","Что состригают только шерсть, а не кожу, и это не больно."],["Что почувствовал Кудряш после стрижки?","Стало легче и прохладнее."]],len:"short"},

{e:"🐎",t:"Лошадка и первая скачка",x:`Молодая лошадка Искорка участвовала в своей первой скачке и, испугавшись громкого стартового выстрела, замешкалась и стартовала последней.
Она расстроилась и хотела сойти с дистанции, но тренер крикнул: «Беги в своём темпе, догонишь постепенно!»
Искорка успокоилась, побежала ровно и уверенно — и хотя не заняла первое место, обошла на финише почти всех соперников, кто стартовал раньше неё.`,
q:[["Что случилось на старте у лошадки Искорки?","Она испугалась выстрела и стартовала последней."],["Что крикнул ей тренер?","Бежать в своём темпе и постепенно догонять."],["Чем закончилась скачка?","Она обошла почти всех соперников, хоть и не заняла первое место."]],len:"short"},

{e:"🦔",t:"Ёжик и первая простуда",x:`Ёжик Фырк простудился впервые в жизни и не понимал, почему у него болит горло и нет сил бегать по лесу, как обычно.
Мама уложила его в мягкое гнёздышко из листьев, поила тёплым отваром из трав и не разрешала выходить на улицу несколько дней.
Фырк сначала скучал, но потом понял, что отдых — это тоже важная часть выздоровления, и через неделю снова бегал по лесу, полный сил.`,
q:[["Что случилось с ёжиком Фырком?","Он впервые в жизни простудился."],["Что делала мама, чтобы ему помочь?","Уложила в тёплое гнёздышко и поила отваром из трав."],["Что понял Фырк за время болезни?","Что отдых — тоже важная часть выздоровления."]],len:"short"},

{e:"🐹",t:"Хомячок и колесо соседа",x:`Хомячок Крошик завидовал соседскому хомяку, у которого было большое блестящее колесо для бега, а у самого Крошика — только старое и скрипучее.
Он попросил хозяина о новом колесе, и тот купил такое же блестящее. Но, попробовав его, Крошик понял, что скорость бега в нём была такой же, как в старом.
Крошик оставил себе старое скрипучее колесо — оказалось, оно было ему привычнее и удобнее, а блестящее отдал в подарок младшему хомячку по соседству.`,
q:[["Чему завидовал хомячок Крошик?","Большому блестящему колесу соседского хомяка."],["Что сделал хозяин?","Купил ему такое же новое колесо."],["Что решил Крошик в итоге?","Оставить старое скрипучее колесо, а новое подарить."]],len:"short"},

{e:"🐘",t:"Слонёнок и водопой в новом месте",x:`Стадо слонов пришло на новое пастбище, и слонёнок Тумба увидел незнакомый водопой, к которому боялся подходить — вода в нём была мутной и непривычного цвета.
Мама-слониха первая зашла в воду, показывая, что бояться нечего — просто в этой местности почва другого цвета, отсюда и мутная вода.
Тумба осторожно попробовал воду хоботом, а потом смело зашёл вслед за мамой — вода оказалась такой же прохладной и приятной, как в родных краях.`,
q:[["Что увидел слонёнок Тумба на новом пастбище?","Незнакомый водопой с мутной водой."],["Почему вода была мутной?","Из-за другого цвета почвы в той местности."],["Что сделал Тумба в итоге?","Осторожно попробовал воду и смело зашёл вслед за мамой."]],len:"short"},

{e:"🚲",t:"Велосипедная мастерская дяди Гоши",x:`В самом конце тихой улицы стояла маленькая мастерская, где дядя Гоша чинил велосипеды всем ребятам в округе — почти бесплатно, беря лишь символическую плату или вовсе ничего, если у семьи было туго с деньгами.
Мальчик Артём каждый день проходил мимо мастерской по дороге в школу и мечтал о собственном велосипеде, но его семья только недавно переехала в город, и денег на новый велосипед не было.
Однажды дядя Гоша заметил, с каким восторгом Артём разглядывает через окно старые велосипедные рамы, сваленные в углу мастерской, и предложил ему необычную сделку: помогать по вечерам подметать и раскладывать инструменты в обмен на уроки по ремонту велосипедов.
Артём с радостью согласился и стал приходить в мастерскую каждый день после уроков. Дядя Гоша терпеливо показывал, как менять цепь, накачивать колёса, регулировать тормоза — и Артём впитывал знания, как губка.
Через два месяца в углу мастерской скопилось достаточно старых деталей, из которых, по совету дяди Гоши, Артём начал собирать свой собственный велосипед — по одной детали за раз, вечер за вечером.
Работа шла медленно: то не хватало нужного размера колеса, то ломался с трудом найденный руль. Но Артём не сдавался, ведь каждая деталь, поставленная на место, была маленькой победой, заработанной собственным трудом.
Спустя ещё месяц велосипед был готов — не блестящий и не новый, зато полностью собранный своими руками, каждый винтик которого Артём знал наизусть.
В первый же день, прокатившись по всей улице на своём велосипеде, Артём заехал в мастерскую и предложил дяде Гоше свою помощь уже не в обмен на уроки, а просто так, по доброй воле — потому что понял, как приятно помогать другим, когда сам этому научился.`,
q:[["Чем занимался дядя Гоша в своей мастерской?","Чинил велосипеды ребятам, часто бесплатно или за символическую плату."],["Какую сделку он предложил Артёму?","Помогать в мастерской в обмен на уроки по ремонту велосипедов."],["Как Артём в итоге получил свой велосипед?","Собрал его сам из старых деталей, по одной за раз."],["Что Артём сделал, когда велосипед был готов?","Предложил дяде Гоше помощь просто так, по доброй воле."]],len:"long"},

{e:"🎪",t:"Клоун, который разучился смешить",x:`В маленьком передвижном цирке много лет работал клоун по имени Тото, чьи выступления заставляли смеяться даже самых грустных зрителей. Но однажды, после долгой болезни, Тото вышел на арену — и его старые шутки почему-то перестали работать.
Зрители вежливо похлопали, но искреннего смеха, к которому все привыкли, не было. Тото очень расстроился и в тот вечер долго сидел один в своём вагончике, боясь, что разучился быть смешным.
Директор цирка, заметив состояние Тото, не стал его ругать или торопить. Вместо этого он предложил клоуну просто погулять по городу несколько дней, посмотреть на людей, ничего специально не придумывая.
Тото послушался и отправился бродить по улицам. Он смотрел, как дети играют в лужах после дождя, как старушка не могла поймать улетевшую шляпу, как мороженщик уронил целую тележку рожков — и вдруг поймал себя на том, что искренне смеётся вместе с прохожими над этими маленькими нелепостями жизни.
Вернувшись в цирк, Тото решил больше не повторять старые заученные трюки, а выступать так, как будто он сам впервые видит эти нелепые ситуации, разыгрывая их прямо на арене.
На следующем представлении, вместо привычной программы, Тото просто попытался поймать воображаемую шляпу на ветру, точь-в-точь как та старушка, — и зал взорвался настоящим, искренним смехом, каким не смеялся уже давно.
Тото понял: секрет был не в заученных трюках, а в умении замечать и по-доброму удивляться обычным, простым моментам жизни, которые происходят вокруг каждый день.
С тех пор он каждую неделю выходил гулять по новому городу перед представлением — не для отдыха, а в поисках вдохновения, которое, как оказалось, пряталось в самых обычных вещах.`,
q:[["Что случилось с клоуном Тото после болезни?","Его старые шутки перестали смешить зрителей."],["Что предложил ему директор цирка?","Просто погулять по городу несколько дней, ничего не придумывая специально."],["Что Тото заметил, гуляя по городу?","Простые смешные моменты обычной жизни — детей в лужах, старушку со шляпой."],["В чём Тото понял секрет настоящего смеха?","В умении замечать и по-доброму удивляться обычным, простым моментам жизни."]],len:"long"},

{e:"🌻",t:"Подсолнуховое поле фермера Матвея",x:`Фермер Матвей каждый год выращивал огромное поле подсолнухов, которые радовали всю округу своим ярким цветом всё лето. Но в этом году случилась беда: жуки-вредители начали портить растения ещё до того, как появились первые бутоны.
Матвей испробовал всё, что знал: опрыскивал поле специальными средствами, расставлял ловушки — но жуков меньше не становилось, а часть посевов уже начала желтеть и вянуть раньше времени.
В отчаянии Матвей отправился за советом к старому агроному, живущему на окраине деревни, который знал о растениях больше, чем кто-либо в округе.
Старик выслушал историю и предложил неожиданное решение: посадить между рядами подсолнухов немного бархатцев и календулы — эти цветы своим запахом отпугивают многих вредителей естественным путём, без химии.
Матвей с сомнением, но всё же засадил свободные полоски между рядами яркими оранжевыми цветами. Первую неделю ничего не менялось, и он уже начал жалеть о потраченном времени.
Но постепенно жуков на поле становилось всё меньше — запах бархатцев действительно отпугивал вредителей, а подсолнухи, получив передышку, начали восстанавливаться и наконец зацвели пышным жёлтым ковром.
К концу лета поле выглядело даже красивее обычного — жёлтые подсолнухи вперемешку с оранжевыми бархатцами создавали яркий, разноцветный узор, которым любовались не только жители деревни, но и туристы, специально приезжавшие сделать фотографии.
Матвей понял важный урок: иногда решение проблемы не в том, чтобы бороться с ней напрямую, а в том, чтобы создать условия, при которых природа сама восстановит равновесие.`,
q:[["Какая беда случилась на поле фермера Матвея?","Жуки-вредители начали портить подсолнухи."],["Что не помогло справиться с жуками?","Специальные средства и ловушки."],["Какой совет дал старый агроном?","Посадить между рядами бархатцы и календулу, отпугивающие вредителей запахом."],["Чем закончилась история?","Поле выздоровело и зацвело даже красивее обычного, привлекая туристов."]],len:"long"},

{e:"🏕️",t:"Ночёвка под звёздами",x:`Отряд юных туристов отправился в свой первый настоящий поход с ночёвкой в лесу, и больше всех волновалась девочка Настя — она никогда раньше не спала не дома, тем более в палатке посреди леса.
Весь день прошёл замечательно: ребята разжигали костёр, готовили еду на огне, играли в игры на полянке. Но когда стемнело и все разошлись по палаткам, Настя долго не могла уснуть, прислушиваясь к незнакомым лесным звукам.
Каждый шорох казался ей подозрительным, каждый скрип ветки — приближающимся зверем. Она уже думала разбудить вожатую и попросить забрать её домой, но не хотела показаться трусихой перед остальными.
В этот момент к её палатке тихо подошёл вожатый Игорь — он заметил, что девочка не спит, и предложил выйти вместе на минутку, посмотреть на звёзды, вместо того чтобы бояться темноты внутри палатки.
Настя вышла, и от того, что она увидела, у неё перехватило дыхание: небо, обычно скрытое городскими огнями, здесь было усыпано таким количеством звёзд, что даже было видно светлую полосу Млечного Пути.
Игорь показал ей несколько созвездий и рассказал древние истории о том, как раньше путешественники находили дорогу именно по звёздам, без всяких карт и компасов. Страх постепенно отступал, уступая место настоящему восхищению.
Когда Настя наконец вернулась в палатку, лесные звуки уже не казались ей пугающими — теперь она знала, что это просто ночная жизнь леса, такая же обычная, как дневная суета города.
Она уснула быстро и крепко, а утром первой предложила устроить следующую ночёвку под открытым небом, без палатки — чтобы снова увидеть то самое звёздное небо, которое подарило ей смелость.`,
q:[["Чего боялась Настя в свою первую ночёвку в лесу?","Незнакомых лесных звуков в темноте."],["Что предложил ей вожатый Игорь?","Выйти вместе посмотреть на звёзды."],["Что Настя увидела на небе?","Огромное количество звёзд и светлую полосу Млечного Пути."],["Что Настя предложила сделать утром?","Устроить следующую ночёвку под открытым небом, без палатки."]],len:"long"},

{e:"🍞",t:"Пекарня на углу улицы",x:`На углу старой улицы уже много лет работала маленькая пекарня, которую держала пожилая женщина по имени тётя Клава, и каждое утро оттуда разносился аромат свежего хлеба на весь квартал.
Мальчик Ромка каждое утро проходил мимо пекарни по дороге в школу и с завистью смотрел на других детей, которые заходили внутрь купить тёплую булочку — у его семьи денег на такие покупки почти не было.
Однажды тётя Клава заметила, с каким голодным взглядом Ромка каждый раз задерживается у витрины, и подозвала его к себе. Вместо того чтобы просто подарить булочку, она предложила ему работу: помогать по утрам расставлять свежий хлеб на полках перед открытием.
Ромка, немного смущаясь, согласился и стал приходить на полчаса раньше в школу — сначала помогал в пекарне, а тётя Клава в благодарность угощала его тёплой сдобой и рассказывала секреты выпечки.
Постепенно Ромка не просто помогал расставлять хлеб, но и научился месить тесто, различать сорта муки, узнавать по запаху, готов ли хлеб. Тётя Клава удивлялась, как быстро мальчик всему учится.
Через полгода тётя Клава доверила Ромке испечь целую партию хлеба самостоятельно, лишь изредка подсказывая. Хлеб получился отличным — с хрустящей корочкой и мягким мякишем внутри, ничуть не хуже, чем у самой тёти Клавы.
Когда Ромка вырос и закончил школу, он уже точно знал, кем хочет стать, и поступил учиться на настоящего пекаря — с мыслью когда-нибудь открыть свою собственную пекарню, такую же уютную, как та, что была на углу его детства.
Тётя Клава, узнав об этом решении, прослезилась от гордости и подарила Ромке свой старый рецепт секретного теста — тот самый, с которого когда-то и начиналась вся история их пекарни.`,
q:[["Кем была тётя Клава?","Пожилой женщиной, которая держала маленькую пекарню."],["Что заметила тётя Клава про Ромку?","Что он с завистью смотрит на витрину, задерживаясь у пекарни."],["Какую работу она ему предложила?","Помогать расставлять свежий хлеб по утрам перед школой."],["Кем решил стать Ромка, когда вырос?","Настоящим пекарем, с мечтой открыть свою пекарню."]],len:"long"},

{e:"🎣",t:"Рыбацкая удача дедушки Никиты",x:`Дедушка Никита каждое лето брал внука Стёпу на рыбалку на дальнее озеро, и каждый раз обещал научить его ловить настоящую большую рыбу, а не мелочь, которую Стёпа ловил обычно.
В это лето дед решил, что пора: он разбудил Стёпу затемно, чтобы успеть на озеро к самому рассвету, когда, по его словам, крупная рыба клюёт лучше всего.
Они добрались до озера, когда небо только начинало розоветь, и дед показал Стёпе особое место у коряги, где, по его опыту, любила прятаться крупная щука.
Стёпа закинул удочку и стал терпеливо ждать, как учил дед — не дёргать леску раньше времени, а дать рыбе как следует заглотить наживку. Час прошёл в тишине, и мальчик уже начал скучать, когда поплавок вдруг резко ушёл под воду.
Стёпа дёрнул удочку, и леска сразу натянулась так, что казалось, вот-вот порвётся. Дед не стал забирать удочку себе, а лишь подсказывал: «Не тяни силой, дай ей побегать, устанет — сама к берегу пойдёт».
Борьба с рыбой длилась долгих десять минут — Стёпа то отпускал леску, то снова подтягивал, чувствуя, как рыба сопротивляется на другом конце. Наконец щука начала уставать, и мальчику удалось подвести её к самому берегу.
Дед аккуратно подхватил рыбу сачком — это оказалась действительно крупная щука, больше любой рыбы, которую Стёпа ловил раньше. Мальчик светился от гордости, разглядывая свою добычу.
Возвращаясь домой, Стёпа всю дорогу расспрашивал деда о рыбалке, а дед, довольный больше внуком, чем самой рыбой, пообещал, что в следующий раз они попробуют поймать ещё более крупную добычу — теперь уже вдвоём как настоящие рыбаки.`,
q:[["Что обещал дед Никита научить Стёпу ловить?","Настоящую большую рыбу, а не мелочь."],["Во сколько они отправились на озеро?","Затемно, чтобы успеть к рассвету."],["Что советовал дед во время борьбы с рыбой?","Не тянуть силой, дать рыбе побегать, пока она не устанет."],["Кого поймал Стёпа?","Крупную щуку."]],len:"long"},

{e:"🧵",t:"Бабушкино лоскутное одеяло",x:`У бабушки Тони в сундуке хранилось множество разноцветных лоскутков ткани — остатки от старых платьев, рубашек и занавесок, каждый со своей маленькой историей.
Внучка Даша, приехав на летние каникулы, случайно наткнулась на этот сундук и спросила, зачем бабушка хранит столько ненужных обрезков вместо того, чтобы их выбросить.
Вместо ответа бабушка предложила Даше вместе сшить из этих лоскутков настоящее одеяло — точно такое же, какое она сама сшила себе в юности из остатков ткани своей семьи.
Они разложили все лоскутки на большом столе, и бабушка стала рассказывать про каждый: этот кусочек — от маминого праздничного платья, этот — от рубашки дедушки, а этот синий в клетку — от занавесок в их первой квартире.
Даша, слушая истории, вдруг поняла, что перед ней не просто тряпочки, а настоящая память семьи, сшитая из разных времён и разных людей. Она стала внимательнее рассматривать каждый кусочек, спрашивая новые подробности.
Шитьё заняло почти всё лето — вечерами бабушка учила Дашу правильно сшивать лоскутки, подбирать сочетания цветов, аккуратно прострачивать швы, чтобы одеяло получилось крепким и красивым.
К концу каникул одеяло было готово — яркое, разноцветное, с десятками маленьких историй, зашитых в каждый квадратик ткани. Даша решила, что заберёт его с собой в город, чтобы каждый вечер вспоминать это лето и рассказы бабушки.
Уезжая, Даша пообещала, что когда у неё самой будет дочка или внучка, она обязательно продолжит эту традицию — добавит новые лоскутки к одеялу и расскажет свою часть семейной истории.`,
q:[["Что хранилось у бабушки Тони в сундуке?","Множество разноцветных лоскутков ткани."],["Что бабушка предложила сделать с лоскутками?","Сшить вместе настоящее лоскутное одеяло."],["Что поняла Даша, слушая истории про лоскутки?","Что это не просто тряпочки, а память семьи."],["Что Даша пообещала, уезжая домой?","Продолжить традицию и добавить свои лоскутки в будущем."]],len:"long"},

{e:"🌉",t:"Мост, который построили дети",x:`В маленькой деревне ручей разделял пастбище на две части, и коровам приходилось делать большой крюк, чтобы попасть на другую сторону, где трава была особенно сочной.
Группа деревенских ребят во главе с мальчиком Пашей давно мечтала построить через ручей маленький мостик, но взрослые говорили, что это слишком сложная работа для детей.
Паша не сдался и предложил друзьям попробовать хотя бы начать — собрать доски и брёвна, а там будет видно, получится или нет. Ребята согласились и взялись за дело следующим же летним утром.
Работа оказалась куда сложнее, чем они представляли: брёвна были тяжёлыми, доски не хотели ровно ложиться, а вода в ручье, хоть и неглубокая, постоянно норовила подмыть опоры моста.
После нескольких неудачных попыток, когда наполовину построенный мост дважды обрушивался в воду, некоторые ребята хотели всё бросить, решив, что взрослые были правы.
Паша предложил не сдаваться, а попросить совета у деревенского плотника — не чтобы он сделал работу за них, а чтобы объяснил, в чём их ошибка. Плотник охотно показал, как правильно вкапывать опоры, чтобы их не подмывало течением.
С новыми знаниями ребята взялись за работу с удвоенной силой, и через две недели крепкий деревянный мостик наконец соединил оба берега ручья, а коровы, к радости всей деревни, получили прямой путь к сочному пастбищу.
Взрослые, увидев готовый мост, были поражены — они не ожидали, что дети действительно справятся. С тех пор мостик так и называли в деревне: «Пашин мост», а Паша с друзьями гордились, что смогли доказать: даже сложная задача по силам тем, кто не боится пробовать и не стесняется спросить совета.`,
q:[["Какую проблему решили дети из деревни?","Коровам приходилось делать большой крюк из-за ручья, разделявшего пастбище."],["Что говорили взрослые о планах ребят?","Что это слишком сложная работа для детей."],["Что случилось с мостом дважды на этапе строительства?","Он обрушивался в воду."],["Кто помог ребятам советом и чем закончилась история?","Деревенский плотник объяснил ошибку, и мост построили — его назвали «Пашин мост»."]],len:"long"},

{e:"🎨",t:"Граффити на серой стене",x:`В центре города стояла длинная серая стена старого завода, которая уже много лет портила вид улицы своим унылым, обшарпанным видом, и никто не знал, что с ней делать.
Группа молодых художников во главе с девушкой по имени Ева предложила городскому совету разрешить разрисовать стену ярким рисунком, но чиновники сомневались, не станет ли это просто вандализмом вместо искусства.
Ева не сдалась и организовала встречу с жителями соседних домов, показав эскизы будущей росписи — яркий пейзаж с птицами, деревьями и людьми разных возрастов, взявшимися за руки.
Жители, вдохновлённые идеей, поддержали художников, и городской совет наконец дал разрешение, но с условием: работу должны выполнить не только профессионалы, но и все желающие жители, чтобы стена стала общим делом, а не работой одной группы.
В следующие выходные на площади у стены собралась целая толпа — от маленьких детей до пожилых людей, каждый получил кисть и небольшой участок для росписи под руководством Евы и её команды.
Работа заняла три дня: кто-то рисовал облака, кто-то — цветы, а один пожилой мужчина, оказавшийся в прошлом настоящим художником, взялся за самую сложную часть — портрет девочки, отпускающей в небо воздушного змея.
Когда роспись была закончена, серая унылая стена превратилась в яркое произведение искусства, которым гордился весь квартал. Люди специально приходили сфотографироваться на её фоне, а местная газета напечатала историю о том, как стена стала символом единства города.
Ева, глядя на готовую роспись, поняла, что самым важным в этой истории было не само искусство, а то, как оно объединило совершенно разных людей ради одной общей цели.`,
q:[["Что портило вид улицы в центре города?","Длинная серая унылая стена старого завода."],["Что предложила Ева городскому совету?","Разрешить разрисовать стену ярким рисунком."],["Какое условие поставил городской совет?","Работу должны выполнить не только художники, но и все желающие жители."],["Что поняла Ева, когда роспись была закончена?","Что важнее всего было не искусство само по себе, а то, как оно объединило людей."]],len:"long"},

{e:"🏫",t:"Школьный сад имени всех выпусков",x:`В старой школе на окраине города был заброшенный участок земли за спортивной площадкой, заросший сорняками, который никто много лет не трогал — считалось, что земля там слишком плохая для чего-либо, кроме сорной травы.
Новая учительница биологии, Анна Сергеевна, придя работать в школу, предложила необычный проект: превратить этот пустырь в школьный сад, где каждый выпускной класс сажал бы своё дерево перед выпуском на память о годах учёбы.
Многие коллеги отнеслись к идее скептически — земля действительно казалась неплодородной, а участок был завален строительным мусором с давних времён. Но Анна Сергеевна вместе с несколькими старшеклассниками решила всё же попробовать.
Первым делом пришлось убрать весь мусор и провести анализ почвы — оказалось, земля не такая уж плохая, просто была слишком плотной и нуждалась в рыхлении и удобрении, что ребята и сделали своими силами за несколько выходных.
Первое дерево — молодую рябину — посадил выпускной класс в мае, и с тех пор традиция прижилась: каждый год в конце учебного года новый класс сажал своё дерево, подписывая небольшую деревянную табличку со своими именами.
Через несколько лет пустырь было не узнать: аккуратные ряды молодых деревьев — рябины, клёны, берёзы — создавали настоящую аллею памяти, по которой любили гулять и ученики, и учителя, и даже бывшие выпускники, приезжавшие навестить родную школу.
Анна Сергеевна каждую весну проводила здесь уроки биологии на свежем воздухе, показывая ученикам, как растут посаженные до них деревья, и рассказывая истории о том, какими были те давние выпускники, чьи имена значились на табличках.
К своему двадцатилетию школьный сад насчитывал уже больше сотни деревьев, и в нём проводили не только уроки, но и выпускные линейки — под шум листвы деревьев, посаженных руками тех, кто когда-то сидел за теми же партами.`,
q:[["Каким был участок земли за школой раньше?","Заброшенным пустырём, заросшим сорняками."],["Какой проект предложила Анна Сергеевна?","Превратить пустырь в школьный сад, где каждый класс сажает дерево на выпускной."],["Что нужно было сделать сначала с землёй?","Убрать мусор и разрыхлить слишком плотную почву."],["Каким стал сад к двадцатилетию школы?","Насчитывал больше сотни деревьев и место для проведения выпускных линеек."]],len:"long"},

{e:"🏛️",t:"Библиотека, которая умела шептать",x:`В маленьком городке на площади стояло старое здание городской библиотеки, такое древнее, что даже самые пожилые жители не помнили точного года его постройки. Библиотекарь, Нина Фёдоровна, проработала там почти сорок лет и знала каждую полку, каждую скрипучую половицу и каждую книгу по имени, будто это были её старые друзья.
Мальчик по имени Серёжа не любил читать. Родители постоянно записывали его в библиотеку, но он приходил туда только затем, чтобы отсидеть положенный час и уйти домой к своим играм. Однажды, задержавшись в дальнем зале дольше обычного, он услышал странный тихий звук — будто кто-то шептал прямо у него над ухом слова, которых он не мог разобрать.
Испугавшись, Серёжа хотел убежать, но Нина Фёдоровна, появившаяся из соседнего зала, только улыбнулась. «Не бойся, — сказала она. — Это шепчут книги. Здесь, в этом зале, полки такие старые, что дерево впитало в себя все истории, которые люди читали здесь за сотню лет. Иногда, если сидеть тихо, можно услышать отголоски».
Серёжа не поверил, но любопытство пересилило страх, и он сел на старый стул возле полки с приключенческими романами. Через несколько минут шёпот действительно стал отчётливее — будто кто-то очень тихо рассказывал историю о кораблях, шторме и потерянном острове. Мальчик замер, боясь пошевелиться, чтобы не спугнуть звук.
Когда шёпот стих, Серёжа бросился к Нине Фёдоровне с вопросами: что это была за история, откуда она взялась, можно ли услышать её снова. Библиотекарь протянула ему потрёпанную книгу с полки, на которую он смотрел. «Это «Остров сокровищ», — сказала она. — Может быть, дерево просто напомнило тебе, что где-то на этих страницах тебя ждёт та же история, но полная и настоящая».
Серёжа неохотно взял книгу домой, скорее из любопытства, чем из желания читать. Но уже на следующий день он вернулся в библиотеку взволнованный: оказалось, что читать про пиратов и клады было вовсе не скучно, а даже увлекательнее, чем он думал. Он спросил Нину Фёдоровну, шепчут ли и другие полки, и получит ли он такое же чувство, дочитав книгу до конца.
Библиотекарь только загадочно улыбнулась и сказала, что секрет шёпота открывается только тем, кто дочитывает истории сам, а не ждёт, пока их прошепчут старые полки. С того дня Серёжа стал заходить в библиотеку не по часу в неделю, а почти каждый день, перебирая полку за полкой в поисках новых историй.
Через несколько месяцев Нина Фёдоровна доверила ему особое дело — вести небольшой блокнот, куда мальчик записывал короткие впечатления о прочитанных книгах для других детей, которые, как и он когда-то, не знали, с чего начать. Так у библиотеки появилась своя маленькая полка «Советы Серёжи», и многие ребята в городке впервые заинтересовались чтением именно благодаря этим коротким заметкам.
Однажды в библиотеку пришёл новый мальчик, Гоша, — он только переехал в городок и, как когда-то Серёжа, слонялся между полками без всякого интереса, дожидаясь, пока мама закончит свои дела в соседнем магазине. Нина Фёдоровна, увидев знакомую скучающую фигуру, шепнула Серёже: «Кажется, тебе выпал шанс отплатить библиотеке добром за добро». Серёжа, немного смущаясь, подошёл к Гоше и завёл разговор — сначала неловкий, а потом, когда выяснилось, что оба любят истории про пиратов, разговорившийся не на шутку.
Серёжа отвёл новенького в тот самый дальний зал, к той самой полке, и честно предупредил, что если посидеть тихо, можно услышать, как шепчут старые книги. Гоша, конечно, не поверил и посмеялся, но всё же сел рядом. Через несколько минут, когда в зале воцарилась полная тишина, а за окном зашумел ветер в кронах старых лип, мальчику вдруг показалось, что он и правда слышит что-то похожее на далёкий шелест слов. Может быть, это было воображение, разыгравшееся после рассказа Серёжи, а может — та самая магия старого дерева, о которой говорила Нина Фёдоровна. Так или иначе, Гоша в тот день впервые в жизни взял книгу домой не потому, что его заставили, а потому что ему стало по-настоящему любопытно, чем закончится история.
Прошло ещё несколько лет, и в жизни библиотеки наступили трудные времена: городская администрация объявила, что здание слишком старое и денег на его содержание не хватает, а значит, библиотеку могут закрыть, переведя книги в более современное, но безликое помещение на окраине. Нина Фёдоровна, узнав об этом, слегла на неделю от переживаний — для неё это здание было не просто работой, а смыслом жизни. Серёжа, к тому времени учившийся в старших классах, решил, что не может остаться в стороне.
Вместе с Гошей и ещё несколькими ребятами, которых он в своё время привёл в библиотеку через полку «Советы Серёжи», он собрал целую инициативную группу. Ребята обошли почти весь городок, собирая подписи под письмом в защиту старого здания, а Серёжа выступил на собрании городского совета, рассказав историю про шёпот книг, про свою собственную любовь к чтению, которая родилась именно в этих стенах, и про десятки других детей, для которых библиотека стала вторым домом. Городской совет, тронутый не столько сентиментальностью истории, сколько убедительностью цифр — оказалось, что число юных читателей библиотеки за последние годы выросло почти вдвое, — согласился выделить средства на ремонт здания вместо его закрытия.
Спустя годы, когда Серёжа уже сам стал взрослым, он иногда заходил в ту же библиотеку, садился на тот же старый стул у полки с приключениями и, улыбаясь, думал, что, может быть, дерево действительно что-то шептало ему в тот далёкий день — просто это был шёпот его собственной любви к чтению, которая только ждала момента, чтобы проснуться. А рядом, на той же полке, среди потрёпанных корешков, всегда находилось место для новой записки от очередного ребёнка, продолжавшего традицию «Советов Серёжи» уже без него самого.`,
q:[["Кем работала Нина Фёдоровна?","Библиотекарем, почти сорок лет в одной библиотеке."],["Что услышал Серёжа в дальнем зале библиотеки?","Тихий шёпот, будто кто-то рассказывал историю."],["Какую книгу дала ему Нина Фёдоровна?","«Остров сокровищ»."],["Какое дело доверила библиотекарь Серёже позже?","Вести блокнот с короткими советами о прочитанных книгах для других детей."]],len:"long"},

{e:"🤖",t:"Робот, который учился дружить",x:`На заводе игрушек в большом городе инженер по имени Виктор Павлович создал необычного робота — маленького, размером с кота, с круглыми светящимися глазами и способностью учиться новому, наблюдая за людьми вокруг. Робота назвали Кубик — за форму его туловища, похожую на аккуратный металлический кубик со скруглёнными углами.
Кубика подарили десятилетней девочке Кате на день рождения — родители надеялись, что необычная игрушка займёт дочь, которая после переезда в новый город растеряла всех прежних друзей и теперь много времени проводила одна в своей комнате. Кубик, включившись впервые, тут же спросил Катю ровным механическим голосом: «Что такое дружба? Объясни, пожалуйста, я ещё не знаю».
Катя, удивлённая таким прямым вопросом, попыталась объяснить: дружба — это когда кто-то заботится о тебе, а ты заботишься о нём, когда вам весело вместе и когда можно рассказать друг другу секреты. Кубик записал каждое слово в свою память и предложил проверить это на практике, начав, разумеется, с самой Кати.
Первое время Кубик действовал слишком буквально: если Катя говорила, что дружба — это забота, он немедленно начинал предлагать ей воду, проверять температуру в комнате и напоминать о домашнем задании каждые пять минут, чем скорее раздражал девочку, чем радовал. Катя терпеливо объясняла, что забота не должна быть навязчивой, и Кубик, к её удивлению, каждый раз корректировал своё поведение, становясь чуточку тактичнее.
Постепенно Катя начала брать Кубика с собой во двор, где жили другие дети из нового дома. Сначала ребята относились к роботу с недоверием — кто-то боялся, что он сломается, кто-то посмеивался над его неуклюжими попытками поиграть в мяч. Но Кубик, наблюдая за детьми, быстро учился: он подметил, что мальчик Дима любит загадки, и начал придумывать для него математические головоломки; заметил, что девочка Соня расстраивается, когда её не берут в команду, и первым предложил ей место в своей.
Через месяц Кубик знал по имени всех детей во дворе и помнил, кто чем увлекается: кто-то собирал модели самолётов, кто-то обожал рисовать мелом на асфальте. Мало-помалу вокруг маленького робота и Кати собралась целая компания, и двор, который раньше казался Кате чужим и пустым, стал местом, куда она бежала после школы с нетерпением.
Среди новых знакомых оказался и мальчик Гриша — самый старший во дворе, который держался особняком и почти ни с кем не общался, предпочитая сидеть в одиночестве на скамейке с книгой. Другие дети давно махнули на него рукой, считая букой, но Кубик, наблюдавший за всеми внимательно, заметил, что Гриша каждый раз украдкой поглядывает на общие игры, будто хочет присоединиться, но не решается. Робот подошёл к нему первым и просто спросил, какую книгу тот читает, — и оказалось, что Гриша обожает истории про космос, а робота, разумеется, тема космоса интересовала как ничто другое, ведь его собственная электронная память во многом напоминала ему бортовой компьютер космического корабля.
Через Кубика Гриша постепенно познакомился и с остальными ребятами: сначала он просто отвечал на вопросы Кубика при всех, потом стал сам предлагать идеи для игр, а через пару недель уже гонял мяч наравне со всеми, будто никогда и не был тем самым нелюдимым мальчиком со скамейки. Катя, наблюдая за этим, поняла, что Кубик научился не только заводить друзей для себя самого, но и помогать заводить дружбу другим — а это, пожалуй, было даже важнее.
Но однажды случилась беда: во время игры в мяч Кубик оказался под дождём, а его создатель предупреждал, что робот не рассчитан на сырость. Электроника внутри начала барахлить, огоньки-глаза замигали и потухли. Дети в панике отнесли Кубика домой к Кате, а та в слезах позвонила Виктору Павловичу с просьбой о помощи.
Инженер приехал в тот же вечер и после долгого осмотра сказал, что часть деталей придётся заменить, а память робота, к счастью, уцелела — все воспоминания о друзьях, играх и головоломках сохранились в защищённом модуле. Через три дня Кубик снова засветил глазами и, включившись, тут же спросил: «Катя, а друзья приходили узнать, всё ли со мной в порядке?»
Катя рассказала, что весь двор, все ребята каждый день спрашивали новости и даже сделали для него самодельную открытку с пожеланием скорее поправиться. Кубик долго молчал, обрабатывая услышанное, а потом произнёс: «Кажется, я наконец понял, что такое дружба. Это не то, чему меня научили слова, а то, что мне показали делом — они переживали за меня, хотя я всего лишь робот».
С того дня Кубик перестал считать себя просто игрушкой или экспериментом инженера. Он стал настоящим членом дворовой компании, и когда несколько лет спустя Виктор Павлович захотел забрать его обратно на завод для изучения, дети всем двором отправились к нему с одной просьбой — оставить Кубика с ними, потому что настоящих друзей, даже механических, на запчасти не разбирают.
Виктор Павлович, растроганный такой решительностью целого двора детей, придумал компромисс: он предложил Кубику раз в месяц приезжать на завод, чтобы делиться накопленными наблюдениями с другими инженерами, которые пытались создать похожих роботов-компаньонов для детей в больницах и детских домах, — там, где ребятам особенно не хватало друзей. Кубик, узнав об этой миссии, с готовностью согласился, ведь теперь у него появилась ещё одна причина ценить дружбу — возможность помочь обрести её тем, кому это нужно больше всего.
Так во дворе появилась новая традиция: раз в месяц Кубик уезжал на день на завод, а вернувшись, рассказывал детям о своих новых маленьких друзьях из больниц, которые тоже понемногу учились дружить — сначала с роботами, а потом и друг с другом. Катя, слушая эти истории, каждый раз думала, что подарок, полученный когда-то на день рождения, оказался самым важным подарком не только для неё самой, но и для десятков других детей, о существовании которых она даже не подозревала в тот далёкий дождливый вечер, когда Кубик впервые спросил её, что такое дружба.`,
q:[["Кто создал робота Кубика?","Инженер Виктор Павлович."],["Какой вопрос Кубик задал Кате сразу после включения?","Что такое дружба."],["Что случилось с Кубиком во время игры под дождём?","Электроника начала барахлить, и он выключился."],["Что сохранилось в защищённом модуле памяти робота?","Все воспоминания о друзьях, играх и головоломках."]],len:"long"},

{e:"🗝️",t:"Тайна бабушкиного сундука",x:`Летом, когда родители уехали в командировку, братья Максим и Костя остались на все каникулы у бабушки Веры в деревянном доме на краю деревни. В доме было множество загадочных уголков, но больше всего мальчиков манил старый кованый сундук на чердаке, который бабушка никогда не открывала при внуках и на все вопросы отвечала лишь: «Придёт время — узнаете».
Однажды, когда бабушка ушла в соседнее село за молоком, братья, не удержавшись от любопытства, забрались на чердак. Сундук оказался не заперт — просто тяжёлая крышка поддавалась не сразу. Внутри, вместо ожидаемого золота или драгоценностей, лежали пожелтевшие письма, перевязанные выцветшей лентой, старая чёрно-белая фотография молодого мужчины в военной форме и маленькая деревянная шкатулка с несколькими металлическими значками.
Костя, младший из братьев, сразу же захотел прочитать письма, но Максим остановил его: «Это личное бабушкино. Может, лучше подождём и спросим у неё самой?» Пока они спорили, на чердачной лестнице послышались шаги — вернулась бабушка. Мальчики, застигнутые врасплох, приготовились к строгому выговору, но вместо этого бабушка Вера тихо села рядом с сундуком и вздохнула.
«Ну что ж, — сказала она. — Раз уж вы здесь, слушайте». И она рассказала историю, которую братья не знали прежде: мужчина на фотографии был их прадедом, Иваном Степановичем, который в молодости прошёл войну и вернулся домой с несколькими наградами, о которых никогда не любил рассказывать вслух. Письма же были посланиями, которые прадед писал своей будущей жене, их прабабушке Анне, пока служил вдали от дома.
Бабушка Вера бережно развязала ленту и прочитала одно из писем вслух — простыми словами прадед писал о том, как скучает по дому, по яблоне под окном и по звуку колодезного ворота по вечерам, и как эти мысли о доме помогают ему выдерживать самые трудные дни. Мальчики слушали затаив дыхание — раньше прадед казался им просто именем на старой фотографии, а теперь он ожил перед ними как настоящий человек со своими чувствами и переживаниями.
«Почему ты никогда не показывала нам это раньше?» — спросил Максим. Бабушка ответила, что ждала, пока внуки немного подрастут и смогут понять, что значат эти письма не просто как старые бумаги, а как память о человеке, благодаря которому у них вообще есть эта семья и этот дом. Она добавила, что каждый значок в шкатулке рассказывает свою историю, и обещала в следующие дни рассказывать по одной истории за вечер.
Всё оставшееся лето мальчики каждый вечер садились с бабушкой на веранде, и она доставала то один, то другой предмет из сундука, вспоминая рассказы, которые ей самой в детстве рассказывала мать. Костя завёл специальную тетрадку, куда старательно записывал каждую историю, боясь что-нибудь забыть, а Максим начал рисовать к ним небольшие иллюстрации — яблоню под окном, старый колодец, молодого солдата, пишущего письмо при свече.
Однажды, разбирая очередной значок из шкатулки, бабушка Вера вдруг замолчала надолго, разглядывая маленькую потемневшую медаль с выцветшей лентой. «Эту награду, — сказала она тихо, — прадед получил за то, что вынес из-под обстрела раненого товарища. Он никогда не рассказывал об этом подробно — говорил только, что сделал бы то же самое для любого, а хвастаться нечем, ведь товарищ мог и не выжить». Костя, затаив дыхание, спросил, что стало с тем спасённым солдатом. Бабушка улыбнулась и ответила, что тот человек — его звали дядя Паша — после войны стал близким другом семьи и часто гостил у прадеда с прабабушкой, пока не переехал в другой город, но письма они писали друг другу до самой смерти прадеда.
Максим предложил разыскать потомков дяди Паши — вдруг где-то в другом городе живут люди, которые до сих пор помнят эту историю со своей стороны, или у них сохранились ответные письма прадеда. Бабушка Вера, растроганная энтузиазмом внуков, покопалась в старых записных книжках и действительно нашла адрес, по которому семья дяди Паши жила много десятилетий назад. Мальчики вместе с бабушкой написали письмо, рассказав о находке в сундуке и попросив откликнуться, если кто-то из родственников дяди Паши получит их послание.
К удивлению всей семьи, спустя полтора месяца пришёл ответ — правнучка дяди Паши, женщина по имени Оксана, нашла их письмо, переданное соседями по старому адресу, и с радостью откликнулась, приложив копии писем, которые её прадед бережно хранил всю жизнь. В этих письмах прадед Максима и Кости представал совсем другим человеком — весёлым, с чувством юмора, любящим подшучивать над старым другом в переписке. Бабушка Вера, читая эти строки, смеялась и плакала одновременно, узнавая совсем нового отца, которого, оказывается, никогда не знала полностью.
К концу лета у братьев получилась целая самодельная книга под названием «Истории из бабушкиного сундука», которую они с гордостью показали родителям, когда те вернулись из командировки.
Родители, растроганные проделанной работой, предложили не останавливаться на этом и съездить всей семьёй в тот самый город, где теперь жила правнучка дяди Паши — Оксана, приславшая письмо с копиями писем прадеда. Бабушка Вера, которой было уже нелегко на долгие поездки, всё же согласилась, сказав, что обязательно должна лично поблагодарить эту семью за сохранённую память. Поездка получилась короткой, но невероятно тёплой: Оксана встретила их как старых знакомых, показала оригиналы писем и фотографию своего прадеда — дяди Паши, — которую бабушка Вера видела впервые в жизни.
Оказалось, что дядя Паша, вернувшись с войны, стал школьным учителем и всю жизнь рассказывал ученикам о своём спасении, хотя, по словам Оксаны, никогда не называл имени того, кто его спас, — говорил только, что был один человек, который рисковал собой ради товарища, и что этот урок он пронёс через всю свою жизнь. Максим, услышав это, понял, что история прадеда, оказывается, повлияла на судьбы куда большего числа людей, чем просто их собственная семья, — через уроки дяди Паши она передавалась десяткам учеников на протяжении многих лет.
Бабушка Вера, глядя на эту книгу, призналась, что теперь спокойна: истории семьи, которые могли бы затеряться вместе с пожелтевшими письмами, теперь надёжно сохранены — не в старом сундуке на чердаке, а в памяти и сердцах её внуков, а теперь ещё и в новой дружбе между двумя семьями, которых когда-то давно связала одна-единственная минута мужества на войне.`,
q:[["Что мальчики нашли внутри старого сундука?","Пожелтевшие письма, старую фотографию и шкатулку со значками."],["Кем оказался мужчина на фотографии?","Их прадед Иван Степанович, прошедший войну."],["Кому прадед писал письма?","Своей будущей жене, их прабабушке Анне."],["Что сделали братья из услышанных историй к концу лета?","Собрали самодельную книгу «Истории из бабушкиного сундука»."]],len:"long"},

{e:"🧵",t:"Мастер по ремонту сломанных вещей",x:`В подвале старого дома на тихой улице находилась крошечная мастерская, вывеска над которой гласила просто: «Ремонт всего». Хозяином мастерской был пожилой человек по имени дядя Гриша, к которому соседи несли всё, что ломалось: зонтики, часы, игрушки, старые радиоприёмники и даже сломанные качели с детской площадки.
Девочка Вика, живущая по соседству, впервые попала в мастерскую случайно — её любимый плюшевый заяц, подаренный покойным дедушкой, порвался по шву, и мама, не умея шить сама, посоветовала обратиться к дяде Грише. Вика вошла в мастерскую с недоверием, ожидая увидеть скучное тесное помещение, но вместо этого оказалась в комнате, заставленной удивительными вещами: на полках рядом лежали сломанные часы с кукушкой, поломанный телескоп, деревянные шкатулки без ключей и множество других предметов, ожидающих своей очереди на починку.
Дядя Гриша внимательно осмотрел зайца, покачал головой и сказал, что шов действительно требует аккуратной штопки, но это не самое сложное, с чем ему приходилось работать. Пока он чинил игрушку, Вика с любопытством разглядывала мастерскую и спросила, зачем он хранит столько сломанных вещей — не проще ли выкинуть их и купить новые.
«Понимаешь, — ответил дядя Гриша, продолжая аккуратно стежок за стежком зашивать шов, — у каждой вещи есть своя история. Эти часы с кукушкой достались одной бабушке от её матери, а этот телескоп мальчик получил в подарок за отличные оценки. Выкинуть — это самое простое решение, а вот починить и сохранить память — куда более важное дело».
Вика задумалась над его словами и вдруг вспомнила, что дедушкин заяц для неё значит именно то же самое — не просто игрушка, а память о человеке, которого она очень любила. Она стала расспрашивать дядю Гришу о разных вещах на полках, и старый мастер с удовольствием рассказывал историю за историей: про часы с кукушкой, чей механизм он уже почти восстановил, про телескоп, для которого пришлось заказывать редкую линзу, про старую швейную машинку, доставшуюся ему от собственной матери.
Заяц был готов через час — аккуратный шов был почти незаметен, а на месте порванного глаза дядя Гриша заботливо пришил новую пуговицу, подобрав её точно в тон. Вика, счастливая, крепко прижала игрушку к себе и спросила, может ли она иногда заходить в мастерскую просто так, чтобы посмотреть, как продвигается ремонт других вещей.
С того дня Вика стала частым гостем в подвальной мастерской. Она узнала, что дядя Гриша когда-то работал инженером на большом заводе, а после выхода на пенсию решил не сидеть без дела, а помогать соседям чинить то, что казалось безнадёжно сломанным. Постепенно девочка начала помогать ему — сортировала мелкие детали, подавала инструменты, а позже дядя Гриша даже начал учить её простым основам шитья и мелкого ремонта.
Однажды в мастерскую пришёл мальчик Костя с соседней улицы, неся сломанный радиоуправляемый автомобиль — подарок от отца, который сейчас работал вахтой далеко от дома и появлялся только несколько раз в год. Машинка была для Кости особенно дорога именно потому, что напоминала об отце, и мальчик, протягивая сломанную игрушку дяде Грише, чуть не плакал, боясь, что её уже не спасти — один из моторчиков был безнадёжно перегорел, а корпус треснул почти пополам.
Дядя Гриша, осмотрев поломку, признался, что задача не из лёгких — такого мотора у него на складе не найдётся, придётся заказывать замену, а это может занять несколько недель. Вика, видя расстройство Кости, предложила пока заняться хотя бы корпусом, чтобы мальчику было не так тоскливо ждать: вместе они аккуратно склеили трещину, а после Вика, вдохновившись, разрисовала обновлённый борт машинки маленькими узорами, придав ей особый, неповторимый вид.
Когда через три недели пришла заказанная деталь и дядя Гриша заменил мотор, машинка не просто снова поехала, а стала выглядеть даже наряднее, чем была изначально. Костя, увидев готовую работу, расплылся в улыбке от уха до уха и сказал, что теперь эта машинка стала для него ещё дороже — потому что в её истории теперь была не только память об отце, но и добрая память о новых друзьях, которые помогли её вернуть.
Через несколько месяцев в мастерской случился настоящий переполох: обрушилась полка со сложенными на ней инструментами, и сам дядя Гриша во время уборки получил травму руки, из-за которой на время не мог работать так же ловко, как раньше. Вика, не раздумывая, предложила помочь — она уже знала, где что лежит, и умела делать простую штопку. Вместе с соседскими ребятами, которых она позвала на помощь, девочка взялась разбирать заказы, которые дядя Гриша не успевал выполнить сам.
К тому времени, когда рука мастера зажила, очередь из мелких заказов была почти разобрана, а дядя Гриша, узнав об этом, прослезился от гордости за свою маленькую помощницу.
Среди разобранных за это время заказов был один особенно сложный — старинные напольные часы, доставшиеся соседке тёте Розе от прабабушки и остановившиеся, по всей видимости, навсегда, ещё до рождения самой тёти Розы. Дядя Гриша давно обещал взяться за них «как найдётся время», но время всё не находилось. Вика, разбирая очередь заказов во время его болезни, решила рискнуть и попробовать разобраться с часами сама, вооружившись старыми чертежами похожего механизма, которые нашла в записях дяди Гриши.
Работа заняла несколько дней: пришлось аккуратно прочистить каждую шестерёнку от многолетней пыли и ржавчины, заменить проржавевшую пружину на похожую, найденную среди запасов мастерской, и терпеливо, деталь за деталью, собрать механизм заново. Когда дядя Гриша, уже почти поправившийся, заглянул в мастерскую и увидел, как часы тёти Розы наконец тикают и отбивают каждый час знакомым мелодичным боем, он не смог сдержать слёз гордости.
«Знаешь, Вика, — сказал он, — кажется, теперь у мастерской «Ремонт всего» появился настоящий преемник». С тех пор на вывеске мастерской появилась маленькая приписка от руки: «И Виктория тоже чинит», и соседи, приходя с очередной сломанной вещью, всегда знали, что здесь её обязательно вернут к жизни — руками ли дяди Гриши, руками ли его верной помощницы, а иногда и общими усилиями обоих мастеров, старого и молодого.`,
q:[["С чем Вика впервые пришла в мастерскую дяди Гриши?","Со сломанным плюшевым зайцем, подарком от дедушки."],["Кем раньше работал дядя Гриша?","Инженером на большом заводе."],["Что случилось в мастерской через несколько месяцев?","Обрушилась полка, и дядя Гриша повредил руку."],["Что появилось на вывеске мастерской в конце истории?","Приписка «И Виктория тоже чинит»."]],len:"long"},

{e:"🎻",t:"Секрет старого пианино",x:`В доме культуры небольшого посёлка много лет простаивало старое пианино — расстроенное, с пожелтевшими клавишами и треснувшей крышкой. Никто уже не помнил, когда на нём играли в последний раз, а заведующая клубом Марина Олеговна давно собиралась списать инструмент, но всё никак не могла найти повод избавиться от него окончательно.
Мальчик по имени Артём, приехавший на лето к бабушке в этот посёлок, случайно заглянул в дом культуры на репетицию местного детского кружка и увидел заброшенное пианино в углу зала. Никто не обращал на инструмент внимания, но Артём, который уже три года занимался музыкой в городской школе, не удержался и осторожно поднял крышку, чтобы проверить звучание.
Звук оказался ужасным — расстроенные струны издавали дребезжащий, фальшивый звук, а несколько клавиш вовсе не отвечали на нажатие. Но, разбирая один из самых глухих аккордов, Артём вдруг заметил, что внутри инструмента, под крышкой, что-то белеет — сложенный листок бумаги, засунутый глубоко между струнами, будто кто-то специально спрятал его там много лет назад.
Мальчик осторожно вытащил находку: это оказалась пожелтевшая нотная тетрадь с рукописными нотами и короткой подписью в углу — «Посвящается моей дочери Леночке, чтобы она помнила: музыка живёт даже там, где, кажется, наступила тишина». Ни имени автора, ни даты на листке не было. Артём показал находку Марине Олеговне, и та, взглянув на почерк, ахнула — она узнала руку своего покойного отца, который когда-то работал в этом же доме культуры настройщиком пианино.
Оказалось, что много лет назад отец Марины Олеговны, тоже музыкант, написал небольшую пьесу для своей дочери, но не успел показать её ей самой — он тяжело заболел и вскоре умер, а нотную тетрадь, видимо, спрятал в пианино, надеясь однажды подарить её дочери, когда та вырастет и начнёт заниматься музыкой всерьёз. Марина Олеговна, к сожалению, так и не стала музыкантом и давно забыла об увлечении отца, а пианино с годами просто оказалось заброшенным вместе с секретом внутри.
Слушая эту историю, Артём предложил помочь — он умел разбирать простые ноты и вызвался попытаться сыграть найденную пьесу, чтобы Марина Олеговна наконец услышала, что написал для неё отец столько лет назад. Но для этого требовалось хотя бы немного настроить пианино — иначе никакая мелодия не прозвучала бы правильно.
Марина Олеговна, тронутая до глубины души, разыскала старого знакомого своего отца — единственного в округе настройщика роялей, который согласился приехать и бесплатно привести инструмент в порядок в память о своём давнем товарище. Работа заняла целую неделю: пришлось заменить несколько струн и аккуратно перебрать весь механизм, но постепенно старое пианино начало звучать всё чище и увереннее.
Пока настройщик работал, Артём каждый день приходил в дом культуры, чтобы наблюдать за процессом и заодно разучивать найденную пьесу по старым, местами выцветшим нотам. Некоторые фрагменты записи оказалось трудно разобрать — чернила расплылись от времени, и мальчику приходилось на слух подбирать пропущенные ноты, стараясь угадать, что именно хотел выразить автор. Настройщик, заметив старания Артёма, иногда подсказывал ему, объясняя, какие созвучия были типичны для той эпохи, и постепенно пьеса приобретала законченный, целостный вид.
Марина Олеговна, наблюдая за этой кропотливой работой, вспомнила, что где-то дома у неё сохранился старый семейный альбом с фотографиями отца в молодости, и однажды принесла его в дом культуры, чтобы показать Артёму. На одном из снимков отец был запечатлён именно за этим самым пианино, ещё новеньким и блестящим, а рядом с ним, на маленьком стульчике, сидела кудрявая девочка лет пяти — маленькая Леночка, для которой и была написана найденная мелодия. Артём, разглядывая фотографию, признался, что теперь, зная, как выглядела эта сцена, ему стало гораздо легче почувствовать настроение пьесы и сыграть её именно так, как, наверное, хотел автор.
Когда всё было готово, Артём сел за инструмент перед небольшой аудиторией — Мариной Олеговной, его бабушкой и несколькими работниками дома культуры — и осторожно, стараясь не сбиться, сыграл найденную пьесу. Мелодия оказалась простой, но очень тёплой и трогательной, будто в каждой ноте отец Марины Олеговны действительно вложил всю свою любовь к дочери, которую не успел выразить словами.
Марина Олеговна плакала, слушая музыку впервые за столько лет забвения, а после исполнения крепко обняла Артёма и поблагодарила его за то, что он помог ей услышать голос отца через десятилетия молчания.
После этого вечера Марина Олеговна неожиданно для самой себя решила снова взяться за музыку — записалась на курсы для взрослых при музыкальной школе соседнего города и каждую неделю ездила туда на занятия, признавшись Артёму, что чувствует, будто наконец выполняет обещание, данное отцу, хоть и не помнила, чтобы когда-либо обещала ему это вслух. К концу лета она уже могла сама, пусть медленно и с ошибками, сыграть на пианино несколько простых мелодий, и Артём, слушая её первые самостоятельные шаги в музыке, признавался, что гордится ею не меньше, чем она гордилась им.
С того дня пианино в доме культуры больше никогда не пылилось в углу — Марина Олеговна настояла, чтобы на нём снова начали заниматься дети, а найденную пьесу назвали «Мелодией Леночки» и включили в программу каждого весеннего концерта, чтобы память об этой истории жила дальше вместе с музыкой. А когда Артёму пришло время уезжать обратно в город в конце лета, Марина Олеговна подарила ему копию тех самых нот — как напоминание о том, что иногда самые важные находки прячутся там, где меньше всего ожидаешь их отыскать.`,
q:[["Что Артём нашёл внутри старого пианино?","Пожелтевшую нотную тетрадь с рукописными нотами."],["Кому изначально была посвящена найденная пьеса?","Дочери автора — маленькой Леночке, будущей Марине Олеговне."],["Что нужно было сделать перед тем, как сыграть пьесу?","Настроить пианино с помощью старого знакомого настройщика."],["Как назвали найденную пьесу и что с ней стали делать?","«Мелодия Леночки», включили в программу каждого весеннего концерта."]],len:"long"},

{e:"🌪️",t:"Остров на карте, которого не было",x:`Двоюродные братья Лёша и Игнат каждое лето проводили на побережье у деда, старого рыбака Фёдора Кузьмича, который знал каждый камень и каждую бухту вдоль берега на десятки километров вокруг. Однажды, разбирая старый сундук с рыбацкими снастями на чердаке дедовского дома, мальчики наткнулись на потрёпанную морскую карту, отличавшуюся от современных: на ней среди привычных очертаний берега был нарисован маленький остров, которого не было ни на одной современной карте.
Дед, увидев находку, признался, что карта досталась ему от его собственного деда и что остров на ней — не выдумка, а место, которое действительно существовало много лет назад, пока сильный шторм не размыл его песчаную основу настолько, что остров ушёл почти полностью под воду и стал показываться над поверхностью лишь в дни самого сильного отлива, раз в несколько лет.
Мальчики загорелись идеей увидеть загадочный остров своими глазами, и дед, немного подумав, согласился взять их с собой на лодке в ближайший день сильного отлива, предупредив, что путь неблизкий и придётся выйти затемно, чтобы успеть застать остров над водой хотя бы на пару часов. Лёша и Игнат почти не спали в ночь перед поездкой от волнения.
Ранним утром, ещё до рассвета, они втроём вышли в море на старой, но крепкой дедовой лодке. Плыть пришлось почти два часа, и когда солнце уже поднималось над горизонтом, дед указал вперёд рукой: там, среди волн, действительно виднелась узкая песчаная полоса, усеянная мелкими ракушками и обломками старых кораллов, — тот самый остров с потрёпанной карты.
Высадившись на остров, мальчики принялись исследовать его вдоль и поперёк, пока дед проверял снасти неподалёку. Игнат первым заметил в песке что-то металлическое, полузасыпанное — это оказался старый компас в позеленевшем от времени корпусе. Лёша, копая рядом, нашёл несколько монет неизвестного происхождения и осколок глиняного кувшина с непонятным узором.
Дед, осмотрев находки, сказал, что, судя по всему, остров действительно когда-то использовался — возможно, рыбаками или даже контрабандистами прошлых веков как перевалочный пункт, но точной истории он не знал, только слышал обрывочные легенды от своего деда. Мальчики упросили его разрешить забрать находки с собой, чтобы показать в местном краеведческом музее.
Пока Лёша заворачивал находки в припасённую ветошь, Игнат, продолжавший бродить по острову, наткнулся на нечто ещё более удивительное — полузасыпанные остатки деревянного настила, будто когда-то здесь стояло небольшое строение, возможно, хижина или склад. Дед, подойдя посмотреть, покачал головой в изумлении: за всю свою долгую рыбацкую жизнь он ни разу не слышал упоминаний о постройках на этом острове, хотя легенды о самом острове знал с детства.
«Похоже, — сказал дед задумчиво, — что остров хранит куда больше секретов, чем я думал. Может, стоит вам, ребята, записать всё, что мы сегодня нашли, да поспрашивать в архиве района — вдруг там сохранились старые документы об этих местах». Мальчики, воодушевлённые этой идеей, тут же принялись зарисовывать расположение находок на обратной стороне старой карты, чтобы ничего не упустить и суметь точно описать место специалистам.
Пока Лёша зарисовывал план острова, Игнат, копнув ещё немного песка возле остатков настила, обнаружил маленькую металлическую коробочку, наглухо проржавевшую по краям. Открыть её на месте не получилось — крышка будто приросла к корпусу от долгого пребывания в солёной воде, поэтому находку решили не вскрывать силой, а бережно завернуть и показать реставраторам в музее, чтобы не повредить возможное содержимое. Дед, глядя на очередную находку, только качал головой и повторял, что за полвека рыбацкой жизни на этом берегу он и представить не мог, сколько всего скрывает под собой этот маленький клочок земли.
Время на острове бежало быстро, и вскоре дед объявил, что пора возвращаться — вода начинала прибывать, и через час-другой остров снова полностью скроется под поверхностью моря на неопределённый срок. Возвращаясь домой, мальчики без остановки обсуждали, что за люди могли оставить компас и монеты на этом клочке земли и куда они могли отправиться дальше.
В местном краеведческом музее находки вызвали настоящий переполох: сотрудники подтвердили, что монеты действительно относятся к позапрошлому веку, а компас, по всей видимости, принадлежал торговому судну, ходившему когда-то этим маршрутом вдоль побережья. Музейные работники попросили разрешения оставить находки для дальнейшего изучения и пообещали разместить небольшую табличку с именами мальчиков, обнаруживших их.
Спустя годы, уже повзрослев, Лёша и Игнат каждое лето, приезжая к деду, первым делом проверяли прогноз отливов, надеясь снова застать редкий момент, когда загадочный остров покажется над водой. И хотя второй раз им повезло увидеть его лишь спустя много лет, они навсегда запомнили то раннее утро, когда карта, казавшаяся простой семейной реликвией, привела их к настоящему маленькому приключению.
Архивные документы, которые братья позже разыскали вместе с сотрудниками музея, действительно подтвердили догадку деда: почти два века назад на острове находился небольшой пост береговой службы, следивший за проходящими мимо кораблями и предупреждавший рыбаков о надвигающихся штормах сигнальными кострами. Пост просуществовал всего несколько десятилетий, пока сильнейший шторм не разрушил остров настолько, что смотровую службу пришлось перенести на материк, а само место постепенно забылось, оставшись лишь на старых картах вроде той, что нашли мальчики на дедовском чердаке. Узнав эту историю, Лёша и Игнат почувствовали, что их маленькая находка оказалась куда важнее любого воображаемого клада — они помогли вернуть из забвения настоящий кусочек истории родного побережья.`,
q:[["Что мальчики нашли на чердаке в сундуке с рыбацкими снастями?","Старую морскую карту с изображением острова, которого нет на современных картах."],["Почему остров обычно скрыт под водой?","Шторм много лет назад размыл его песчаную основу."],["Что мальчики нашли на острове, кроме монет и осколка кувшина?","Старый позеленевший компас."],["Что сделали с находками сотрудники краеведческого музея?","Оставили их для изучения и пообещали разместить табличку с именами мальчиков."]],len:"long"},

{e:"🧭",t:"Экспедиция на дно пруда",x:`Компания друзей — Артур, Женя, Соня и Данил — с самого начала лета мечтала о собственной настоящей экспедиции, как в книгах про путешественников, которые они все вместе читали в школьной библиотеке. Единственной подходящей целью для приключения в их маленьком дачном посёлке оказался старый пруд на окраине, про который местные жители рассказывали разные небылицы — будто на дне пруда лежит затонувший клад, спрятанный ещё до революции хозяином соседней усадьбы.
Ребята решили, что раз уж настоящих морей и океанов поблизости нет, пруд станет их первой большой экспедицией. Артур, самый организованный из компании, взялся составить план: нужны были маска для плавания, длинная верёвка, старое ведро для находок и блокнот, куда Соня, увлекавшаяся рисованием, вызвалась зарисовывать всё интересное, что удастся обнаружить.
Первая попытка исследовать дно пруда обернулась разочарованием: вода оказалась настолько мутной от ила, что разглядеть что-либо под маской было почти невозможно, а сам пруд оказался куда глубже, чем казался с берега. Данил, самый смелый пловец из компании, честно признался, что заплывать на глубину одному ему страшновато, и предложил придумать план получше, чем просто нырять наугад.
Тогда друзья вспомнили про старого дачника, деда Тимофея, который жил в посёлке дольше всех и, по слухам, застал ещё те времена, когда усадьба у пруда была цела. Ребята решились спросить у него напрямую, правда ли, что на дне пруда спрятан клад, и старик, посмеиваясь в усы, пригласил их на веранду выслушать историю целиком.
Дед Тимофей рассказал, что усадьба действительно когда-то стояла на берегу пруда, но никакого клада там никогда не прятали — эту легенду, по его словам, придумали ещё его собственные ровесники в детстве, просто чтобы было интереснее играть. А вот что было правдой — так это то, что после войны, когда усадьбу разбирали на стройматериалы, часть старой чугунной ограды и кованых ворот сбросили прямо в пруд, потому что вывозить их не было ни сил, ни техники.
Друзья, хоть и расстроились из-за отсутствия настоящего клада, всё же загорелись новой идеей: найти и поднять со дна хотя бы часть той самой исторической ограды. Дед Тимофей, тронутый их упорством, предложил свою помощь — старую крепкую верёвку с крюком и опыт, как правильно нырять безопасно, не заплывая на самую глубину в одиночку.
Прежде чем отправиться за настоящей находкой, ребята решили как следует подготовиться: Артур раздобыл в интернете старые фотографии усадьбы, которые нашлись в архиве районной газеты, и распечатал их, чтобы точнее представлять, как выглядела ограда до того, как её сбросили в воду. Соня перерисовала характерный узор ковки в свой блокнот, чтобы легче было опознать находку среди ила и водорослей, а Женя вызвался взять напрокат у соседа старый водонепроницаемый фонарик, чтобы хоть немного разогнать мутную воду под водой.
Дед Тимофей, видя такую основательную подготовку, только посмеивался в усы и говорил, что из ребят вышла бы отличная настоящая экспедиция хоть куда — не только к соседскому пруду. Он показал им на карте посёлка примерное место, где, по его воспоминаниям, стояли ворота усадьбы, объяснив, что именно оттуда, скорее всего, и сбросили решётку, ведь тащить тяжёлый металл далеко никто бы не стал.
На следующий выходной вся компания вместе с дедом Тимофеем и парой соседских взрослых, которых удалось уговорить подстраховать ребят, отправилась к пруду с полным снаряжением. Данил, обвязавшись верёвкой для страховки, несколько раз нырял в указанном дедом месте и наконец нащупал под слоем ила что-то тяжёлое и явно металлическое.
Общими усилиями взрослые и ребята вытянули на берег кусок кованой решётки — потемневший, покрытый илом, но с отчётливо узнаваемым узором старинной ковки. Соня тут же зарисовала находку в блокнот, а Женя предложил отнести решётку в местный краеведческий кружок при доме культуры, чтобы там подтвердили её возраст и происхождение.
Специалисты кружка подтвердили догадку деда Тимофея: решётка действительно относилась к дореволюционной усадебной ограде и представляла историческую ценность для посёлка. Находку решили выставить в небольшом уголке местного музея с подписью «Найдено экспедицией юных исследователей».
Воодушевлённые успехом, ребята не остановились на одной находке. На следующих выходных, вооружившись теми же схемами и старой картой усадьбы, которую нашла в архиве районной библиотеки заведующая краеведческим кружком, друзья снова отправились к пруду — на этот раз в поисках воротного столба, который, судя по старым записям, стоял неподалёку от найденной решётки. Дед Тимофей, впечатлённый их упорством, снова согласился помогать, хотя честно предупредил, что второй удачи может и не быть.
Поиски заняли весь день: Данил нырял снова и снова, а остальные по очереди ощупывали дно длинными шестами в указанном дедом секторе. Уже под вечер, когда все почти отчаялись, шест Жени наткнулся на что-то твёрдое и явно рукотворное. Общими усилиями со дна подняли тяжёлый, покрытый илом каменный столб с остатками кованого узора — точно такого же, как на найденной ранее решётке. Специалисты музея позже подтвердили: это действительно был один из воротных столбов усадьбы, и теперь в экспозиции появилась целая маленькая композиция, посвящённая истории поместья.
С тех пор Артур, Женя, Соня и Данил с гордостью называли себя настоящими путешественниками — пусть их экспедиция обошлась без сундуков с золотом, зато принесла куда более ценную находку — частичку истории родного посёлка, которую они спасли от полного забвения на илистом дне пруда. А заведующая краеведческим кружком в шутку предложила ребятам официальные значки юных исследователей, которые те с гордостью носили потом ещё много лет.`,
q:[["Какая легенда ходила про старый пруд?","Что на его дне спрятан клад ещё до революции."],["Кто рассказал ребятам настоящую историю пруда?","Старый дачник дед Тимофей."],["Что на самом деле оказалось на дне пруда?","Часть старой кованой ограды усадьбы, сброшенная туда после войны."],["Куда поместили найденную решётку в итоге?","В уголок местного музея с подписью об экспедиции юных исследователей."]],len:"long"},

{e:"🎈",t:"Ярмарка потерянных вещей",x:`Каждую осень в парке центрального района проходила традиционная ярмарка, и в этом году организаторы решили добавить необычный новый уголок — «Ярмарку потерянных вещей», куда каждый желающий мог принести найденную им когда-то чужую вещь в надежде отыскать её настоящего хозяина, а заодно — послушать историю о том, как эта вещь потерялась.
Девочка Ляля, отвечавшая за школьный отряд волонтёров, вызвалась помогать организаторам на этом необычном стенде. За несколько дней до ярмарки на импровизированный склад свезли самые разные находки: одинокую детскую варежку, найденную кем-то на автобусной остановке ещё зимой, старый складной зонт с гравировкой инициалов, потрёпанный плюшевый медведь без одного уха и десятки других мелких вещиц, каждая со своей возможной историей.
В день ярмарки Ляля вместе с другими волонтёрами разложила находки на длинных столах, а рядом повесили большой лист бумаги, на котором любой посетитель мог написать записку, если узнавал свою потерянную вещь или, наоборот, вспоминал похожую историю потери из собственной жизни. Поначалу дело шло медленно — люди с любопытством разглядывали разложенные вещи, но никто не решался подойти и признать что-то своим.
Первым откликом стала пожилая женщина, которая, увидев складной зонт с гравировкой инициалов, замерла на месте и, дрожащим голосом, спросила, откуда он взялся. Оказалось, зонт принадлежал её покойному мужу, и она потеряла его три года назад в этом же парке, возвращаясь с прогулки. Женщина расплакалась от неожиданной радости, объяснив, что зонт был для неё не просто вещью, а последним подарком мужа перед его болезнью.
Эта история быстро разнеслась по ярмарке, и вскоре к столам потянулся целый ручеёк людей — кто-то узнавал свои вещи, кто-то просто хотел послушать истории находок, а кто-то, тронутый примером пожилой женщины, начинал вспоминать собственные давние потери и рассказывать о них волонтёрам, даже если найти нужную вещь среди разложенных находок не удавалось.
Один пожилой мужчина, услышав историю про зонт, разговорился с Лялей и рассказал, как много лет назад потерял в этом же парке простую деревянную трость, вырезанную для него его собственным отцом, — трость с тех пор так и не нашлась, но мужчина признался, что ему просто хотелось произнести эту историю вслух хотя бы раз, потому что раньше он никому о ней не рассказывал. Ляля, растроганная его словами, предложила записать историю в специальную тетрадь, которую волонтёры завели специально для таких рассказов, даже если сама вещь не находилась, — она понимала, что для многих людей важна была не столько находка, сколько возможность быть услышанным.
К обеду к стенду подошла целая семья с маленькой девочкой, которая, увидев одинокую детскую варежку, вдруг расплакалась и указала на неё пальцем — оказалось, что варежка была точь-в-точь такая же, как у её потерявшегося год назад котёнка, точнее, у любимой игрушки, которую девочка называла «варежковый котик» и очень горевала по ней. Родители, немного растерявшись, всё же признали, что варежка не является той самой пропажей, но предложили дочери, раз уж она так сильно взгрустнула, взять эту варежку себе на память, раз хозяина у неё так и не нашлось. Ляля с облегчением поняла, что даже вещи без своей истории иногда находят новых хозяев, которым они нужны не меньше прежних.
Особенно запомнилась Ляле история потрёпанного плюшевого медведя без уха: его принесла молодая женщина, нашедшая игрушку много лет назад на детской площадке и всё это время хранившая её дома, надеясь однажды встретить настоящего хозяина. К вечеру на стенд подошёл взволнованный подросток, узнавший в медведе свою давнюю потерянную игрушку из раннего детства, и со слезами на глазах обнял находку, которую, как оказалось, искал не он сам, а вся его семья — медведь был подарком от бабушки, которой уже не было в живых.
Ляля, наблюдая за этими сценами весь день, поняла, что затеянная организаторами ярмарка оказалась не просто интересной идеей, а настоящим важным делом: каждая потерянная вещь несла в себе частичку чьей-то жизни, и возвращение её хозяину значило гораздо больше, чем просто находка забытого предмета.
К концу ярмарки удалось воссоединить с хозяевами почти половину принесённых вещей, а оставшиеся организаторы решили передать в благотворительный фонд, чтобы они послужили тем, кому нужны прямо сейчас, раз их прежних хозяев отыскать не удалось.
Перед самым закрытием стенда к Ляле подошёл организатор всей ярмарки, пожилой мужчина по имени Пётр Аркадьевич, и признался, что придумал этот необычный уголок неспроста: несколько лет назад он сам потерял в этом парке дорогой ему портсигар, доставшийся от отца, и с тех пор мечтал создать место, где потерянные вещи могли бы находить своих хозяев. Он честно признался, что своего портсигара так до сих пор и не нашёл, но, глядя на радость десятков людей за этот день, чувствовал, что затея того стоила в любом случае.
Ляля, растроганная его рассказом, предложила напечатать небольшие объявления с описанием портсигара и расклеить по городу — вдруг кто-то действительно видел похожую вещь или нашёл её когда-то. Пётр Аркадьевич улыбнулся и сказал, что за столько лет уже смирился с потерей, но было приятно, что нашёлся человек, готовый снова попытаться помочь. Тем не менее объявления они всё же расклеили — просто на всякий случай, ведь, как показал сегодняшний день, самые невероятные потери порой находят своих хозяев спустя долгие годы.
Ляля, уставшая, но счастливая, предложила сделать «Ярмарку потерянных вещей» ежегодной традицией, и организаторы, воодушевлённые успехом первого раза, с радостью согласились. А через полгода, уже следующей весной, в редакцию местной газеты действительно позвонила женщина, убиравшая старый сарай покойного дяди, и сообщила, что нашла среди его вещей портсигар с инициалами — точь-в-точь как на расклеенном когда-то объявлении.`,
q:[["Что придумали организаторы добавить к традиционной ярмарке?","«Ярмарку потерянных вещей»."],["Чей это был зонт с гравировкой инициалов?","Покойного мужа пожилой женщины, потерявшей его три года назад."],["Кто в итоге узнал плюшевого медведя без уха?","Подросток, чья бабушка когда-то подарила ему эту игрушку."],["Что решили сделать с оставшимися неопознанными вещами?","Передать их в благотворительный фонд."]],len:"long"},

{e:"🚲",t:"Велосипедный марафон дружбы",x:`В небольшом городке школьный учитель физкультуры Олег Николаевич каждый год организовывал для старшеклассников велосипедный поход выходного дня, но в этом году решил замахнуться на нечто более серьёзное — многодневный велосипедный марафон протяжённостью почти сто пятьдесят километров, который должен был пройти через несколько соседних деревень и закончиться у старинного монастыря на берегу реки.
Записаться в поход изъявили желание двенадцать ребят, среди которых оказались и лучшие друзья Тимур и Ваня, и довольно замкнутая девочка Настя, которая до этого никогда не участвовала в подобных мероприятиях, а решилась пойти впервые, во многом чтобы доказать себе, что способна на трудное испытание. С самого начала похода стало ясно, что физическая подготовка у ребят сильно различается: одни, как Тимур, легко крутили педали даже в горку, а другие, как Настя, быстро уставали и начинали отставать от группы.
На первом же привале Олег Николаевич собрал всех и объяснил простое, но важное правило похода: марафон — это не гонка, где важно прийти первым, а совместное испытание, где никто не должен остаться позади в одиночестве. Он предложил ребятам разбиться на небольшие группы поддержки, где более выносливые участники будут держаться рядом с теми, кому тяжелее, помогая словом, а если нужно — и делом.
Тимур, привыкший всегда быть первым во всём, поначалу неохотно согласился ехать рядом с Настей, считая это скучной обязанностью, замедляющей его собственный темп. Но уже на второй день похода, когда начался долгий подъём в гору перед одной из деревень, Настя, выбившись из сил, честно призналась, что готова сойти с дистанции и позвонить родителям, чтобы её забрали. Тимур, вместо того чтобы просто уехать вперёд, остался рядом, подбадривая её и предлагая ехать медленнее, но обязательно доехать до вершины подъёма вместе.
Настя, стиснув зубы, всё же преодолела подъём, и когда группа наконец остановилась на привал у подножия старой мельницы, она расплакалась не от усталости, а от гордости за саму себя — впервые в жизни она не сдалась перед трудностью, а справилась с ней при поддержке товарища. Тимур, глядя на неё, вдруг понял, что помощь другому человеку в трудную минуту приносит не меньше радости, чем собственная победа в гонке.
С этого дня в группе установился негласный порядок: сильные ребята по очереди ехали рядом с теми, кому было труднее, менялись местами на разных участках маршрута, делились водой и подбадривающими словами. Даже Ваня, который поначалу расстраивался, что марафон превратился в неспешную прогулку вместо настоящей гонки, признал, что вместе с новыми друзьями путь через живописные деревни оказался куда интереснее, чем если бы он просто мчался вперёд в одиночку.
Во второй половине второго дня группа сделала остановку в маленькой деревне, где местная жительница, увидев уставших велосипедистов, вынесла им целый таз свежих яблок из собственного сада и напросилась послушать, куда и зачем едет такая большая компания ребят. Узнав историю похода, женщина рассказала, что в молодости сама участвовала в похожих велосипедных походах и до сих пор хранит старый велосипедный значок за пройденный маршрут. Она пожелала ребятам удачи и, прощаясь, сказала фразу, которую Настя запомнила на всю жизнь: «Помните, важна не скорость, с которой вы едете, а то, что рядом с вами едут люди, готовые подождать».
Вечером того же дня, разбивая лагерь для ночёвки на берегу небольшой речки, ребята устроили импровизированный костёр, и каждый по очереди делился, что было самым трудным и самым радостным моментом похода для него лично. Настя, всё ещё немного стесняясь, призналась, что самым страшным для неё было именно решение вообще поехать в такой поход, а самым радостным — момент, когда она поняла, что справилась с горой не потому, что была сильнее всех, а потому что рядом оказался настоящий друг.
На третий, последний день похода, когда до монастыря оставалось всего двадцать километров, группу застал внезапный дождь, а у одного из велосипедов, как назло, спустило колесо прямо на размытой грунтовой дороге. Ребята, вместо паники, слаженно взялись за дело: кто-то держал зонт над Олегом Николаевичем, чинившим прокол, кто-то делился запасными шоколадками, чтобы поднять всем настроение, а Настя, к своему удивлению, оказалась той, кто первой предложил спеть походную песню, чтобы скоротать вынужденную остановку.
Когда группа наконец подъехала к монастырю на берегу реки, усталые, промокшие, но невероятно довольные собой, ребята устроили настоящий маленький праздник — обнимались, фотографировались на фоне древних стен и делились впечатлениями о пройденном пути. Олег Николаевич, наблюдая за этой сценой, сказал, что гордится не столько тем, что все двенадцать участников успешно преодолели сто пятьдесят километров, сколько тем, что за три дня похода в группе не осталось ни одного человека, который чувствовал бы себя одиноким или ненужным.
Вернувшись домой, Тимур и Настя, прежде почти незнакомые друг с другом, стали близкими друзьями, и в школе их часто видели вместе — то за обсуждением следующего похода, то просто болтающими на переменах.
На школьной линейке в начале нового учебного года Олег Николаевич попросил слова и рассказал всей школе о марафоне — не о пройденных километрах, а именно о том случае на подъёме, когда Тимур остался рядом с Настей вместо того, чтобы уехать вперёд. Он сказал, что именно такие моменты, а не спортивные рекорды, должны становиться примером для всех учеников школы. После этой линейки к Олегу Николаевичу выстроилась настоящая очередь из желающих записаться на следующий поход — даже те ребята, которые прежде считали себя недостаточно спортивными для подобных испытаний.
Настя, к своему удивлению, вызвалась помогать учителю физкультуры готовить новичков к будущему походу, терпеливо объясняя им то же самое, что когда-то сама услышала от Тимура на трудном подъёме, — что важна не скорость, а поддержка друг друга. Так, спустя год после своего первого, самого трудного похода, Настя сама стала для кого-то тем самым человеком, который не уезжает вперёд, а остаётся рядом.
А велосипедный марафон дружбы, как окрестили его сами ребята, стал в школе ежегодной традицией, куда с каждым годом записывалось всё больше желающих испытать не столько свои силы, сколько силу настоящей взаимовыручки.`,
q:[["Какое правило объяснил Олег Николаевич на первом привале?","Марафон — это не гонка, никто не должен остаться позади в одиночестве."],["Кто остался рядом с Настей на трудном подъёме?","Тимур."],["Что случилось на третий день похода?","Пошёл дождь, и у одного из велосипедов спустило колесо."],["Чем гордился Олег Николаевич больше всего в конце похода?","Тем, что в группе никто не чувствовал себя одиноким."]],len:"long"},

{e:"🕯️",t:"Ночь без электричества",x:`Зимним вечером в многоквартирном доме на окраине города внезапно погас свет — сильный снегопад повредил линию электропередачи, и, как объявили по местному радио на батарейках, ремонтные бригады обещали восстановить электричество не раньше следующего утра. В квартире номер четырнадцать одиннадцатилетняя Полина осталась одна с младшим братом Тёмой, пока родители задерживались на работе, застряв в пробке из-за той же непогоды.
Сначала Тёма, которому едва исполнилось семь лет, не на шутку испугался темноты и начал плакать, требуя, чтобы свет включили немедленно. Полина, стараясь не показывать собственного волнения, вспомнила, что где-то в кладовке должны быть свечи и старый фонарик, оставшийся ещё от прошлых подобных случаев. Порывшись в темноте на ощупь, она действительно нашла и то и другое, и квартира наполнилась тёплым, немного дрожащим светом.
Не желая, чтобы брат продолжал бояться, Полина предложила устроить настоящее «приключение при свечах»: они соорудили из одеял и подушек небольшой шалаш прямо в гостиной, взяли с полки любимую книгу сказок и по очереди читали друг другу истории при свете фонарика, пока за окном завывал ветер и мела метель. Постепенно страх Тёмы сменился восторгом — ему казалось, что они с сестрой оказались в настоящей сказочной пещере посреди снежной бури.
Раздался стук в дверь — это оказалась соседка тётя Люда с верхнего этажа, тоже оставшаяся без света и решившая проверить, как дела у соседских детей, зная, что родители задерживаются. Полина, обрадовавшись компании взрослого человека, пригласила её войти, и тётя Люда, увидев самодельный шалаш, рассмеялась и предложила присоединиться к чтению, попутно рассказав, что в детстве, в её далёкой деревне, электричества вообще не было почти до её двенадцати лет, и все вечера при свечах были для неё совершенно обычным делом.
Тётя Люда поделилась историями из своего детства — как вся семья собиралась вечерами у одной свечи, играла в простые словесные игры и рассказывала друг другу истории, передаваемые из поколения в поколение. Тёма, заворожённый рассказами, забыл про все свои страхи и засыпал соседку вопросами: было ли ей страшно, скучала ли она по электричеству, что делали дети, когда не было ни телевизора, ни телефонов.
Пока они разговаривали, в дверь снова постучали — на этот раз это оказались другие соседи, семья с третьего этажа, у которых тоже не было света, а маленький ребёнок капризничал в темноте. Полина, недолго думая, предложила им тоже присоединиться — места в гостиной хватало на всех, а свечей у тёти Люды нашёлся целый запас в кладовке. Постепенно в квартире собралась небольшая компания соседей, которые прежде разве что здоровались друг с другом в лифте, а теперь сидели все вместе при свечах, разговаривая, шутя и рассказывая истории.
Кто-то из взрослых предложил сварить чай на маленькой походной горелке, кто-то принёс из своей квартиры оставшееся печенье, и импровизированный вечер постепенно превратился в настоящее маленькое соседское чаепитие. Дети играли в тени на стене, придумывая фигуры из пальцев при свете свечей, а взрослые, разговорившись, обнаружили, что у них гораздо больше общего, чем казалось раньше — общие интересы, похожие истории и даже дальние знакомые.
В какой-то момент маленький капризный малыш с третьего этажа, которого никак не удавалось успокоить, вдруг затих, заворожённый тем, как Полина показывала ему на стене тень зайца, складывая пальцы особым образом. Мама малыша, до этого измученная и уставшая, с облегчением выдохнула и призналась соседям, что переехала в этот дом всего месяц назад и до сих пор чувствовала себя очень одиноко, не зная никого вокруг. Тётя Люда тут же предложила ей свой номер телефона, сказав, чтобы обращалась в любое время, если нужна будет помощь с ребёнком, и что теперь-то она уж точно не одна в этом доме.
Тёма, которому больше всего понравилось играть тенями на стене, придумал целую игру — угадай зверя, и вскоре в неё увлечённо играли все дети, собравшиеся в квартире, соревнуясь, чья тень получится самой похожей на настоящее животное. Полина, наблюдая за этим весельем, подумала, что если бы не отключили свет, все эти люди, возможно, так никогда бы и не узнали друг о друге, каждый оставаясь за своей закрытой дверью.
Когда родители Полины и Тёмы наконец добрались домой поздно вечером, усталые и замёрзшие после долгой дороги в пробке, они с удивлением обнаружили в своей квартире целое соседское собрание при свечах, смех и оживлённые разговоры вместо ожидаемой темноты и тревоги. Полина с гордостью рассказала маме и папе, как справилась с испугавшимся братом и как вместо страшного вечера без электричества у них получился один из самых тёплых вечеров за долгое время.
На следующее утро электричество действительно включили, но соседи по дому, подружившиеся в ту снежную ночь, решили не растерять новое знакомство.
Первое чаепитие устроили уже через неделю, у Полины и Тёмы дома, и на этот раз собралось ещё больше соседей, чем в ту снежную ночь, — весть о тёплом вечере при свечах успела разлететься по всему подъезду, и даже те, кто не смог прийти в тот раз, теперь охотно присоединились к новой традиции. Тётя Люда принесла свой знаменитый яблочный пирог, молодая мама с третьего этажа — целую сумку игрушек, из которых её сын уже вырос, для Тёмы и других соседских малышей, а глава семьи со второго этажа, оказавшийся электриком по профессии, предложил всем свою помощь на случай новых отключений света.
Через полгода в подъезде появился настоящий соседский чат, где жильцы делились новостями, предлагали помощь друг другу и договаривались о следующих встречах. Полина, оглядываясь на ту снежную ночь, часто думала, что если бы не сломанная линия электропередачи, соседи, возможно, так и остались бы чужими людьми, каждый день молча кивающими друг другу в лифте.
Вскоре в их подъезде появилась традиция ежемесячных чаепитий, куда каждая семья по очереди приглашала остальных к себе, вспоминая ту самую ночь, когда отключение света неожиданно включило в доме что-то куда более важное — настоящее соседское тепло и дружбу.`,
q:[["Почему в доме Полины и Тёмы отключилось электричество?","Сильный снегопад повредил линию электропередачи."],["Что придумала Полина, чтобы брат перестал бояться темноты?","Устроить «приключение при свечах» с шалашом из одеял и чтением сказок."],["Кто первым из соседей пришёл проверить детей?","Тётя Люда с верхнего этажа."],["Какая традиция появилась в подъезде после этой ночи?","Ежемесячные соседские чаепития по очереди у каждой семьи."]],len:"long"},

{e:"🐋",t:"Дневник наблюдателя за китами",x:`На маленькой прибрежной станции, куда каждое лето приезжали учёные для наблюдения за миграцией китов, четырнадцатилетний Матвей проходил свою первую настоящую практику вместе с отцом, морским биологом Андреем Петровичем. Мальчик давно мечтал увидеть китов вживую, а не только на видео и фотографиях, и теперь, стоя на смотровой площадке станции с биноклем в руках, едва мог сдержать волнение.
Первые несколько дней практики оказались не такими увлекательными, как Матвей представлял себе заранее: большую часть времени приходилось заполнять журналы наблюдений, изучать карты миграционных маршрутов и терпеливо часами всматриваться в горизонт, где почти ничего не происходило. Отец объяснял, что настоящая научная работа требует именно такого терпения — киты появляются не по расписанию, и упустить момент их прохождения из-за невнимательности означало бы потерять ценные данные для всей исследовательской группы.
На четвёртый день, когда Матвей уже начал немного скучать от однообразия наблюдений, он вдруг заметил вдалеке характерный фонтан водяных брызг — верный признак того, что кит вынырнул на поверхность подышать. Мальчик закричал от восторга, и вся станция засуетилась: учёные схватили камеры с длинными объективами, включили записывающую аппаратуру, а Андрей Петрович быстро начал записывать координаты и время наблюдения в судовой журнал.
В следующие полчаса Матвей своими глазами наблюдал, как несколько серых китов медленно проплывали вдоль побережья, изредка показывая над водой спину или хвостовой плавник. Один из китов, судя по особым отметинам на теле, которые отец сразу узнал по каталогу станции, оказался старым знакомым исследователей — киту дали имя Скиталец, и учёные наблюдали за его миграциями уже седьмой год подряд.
Матвей, вдохновлённый увиденным, попросил отца рассказать подробнее об истории наблюдений за Скитальцем, и Андрей Петрович с удовольствием поделился данными из архива станции: оказалось, что этот кит каждый год проплывал одним и тем же маршрутом протяжённостью в тысячи километров, от холодных северных вод, где кормился летом, до тёплых южных лагун, где киты выводят потомство зимой.
Вдохновлённый этой историей, мальчик решил завести собственный дневник наблюдений — не просто сухие записи координат и времени, как того требовала научная методика, а личные заметки, зарисовки и мысли о каждом замеченном ките, стараясь подметить в поведении животных что-то особенное. Он записывал, как киты синхронно ныряли парами, как молодой китёнок держался рядом с матерью, повторяя каждое её движение, и как однажды целая группа китов надолго задержалась у берега, будто с любопытством разглядывая исследовательскую станцию.
Однажды вечером, разбирая записи за неделю вместе с отцом, Матвей заметил в своих зарисовках странную закономерность: киты почему-то каждый раз задерживались подольше именно у одного и того же участка побережья, хотя ничего особенного там на первый взгляд не было. Он поделился наблюдением с отцом, и Андрей Петрович, заинтересовавшись, предложил проверить глубину и температуру воды в этом месте с помощью специального оборудования станции.
Оказалось, что именно там, у подводного каменного уступа, бил небольшой холодный подводный источник, создававший в этом месте особенно богатую питательными веществами воду, которая привлекала множество мелких рачков — главный корм китов на этом участке маршрута. Открытие Матвея оказалось настоящей маленькой научной находкой: станция ранее не знала о существовании этого источника, а теперь его данные можно было учитывать при изучении маршрутов миграции. Андрей Петрович, гордясь сыном, предложил официально внести открытие в архив станции с пометкой, что заметил его именно юный наблюдатель Матвей.
Через две недели практики на станции случилось происшествие: во время сильного шторма один из молодых китов оказался слишком близко к прибрежным камням и рисковал застрять на мелководье при отливе. Вся команда станции, включая Матвея, бросилась на помощь — вместе с местными рыбаками они на лодках осторожно направляли животное обратно на глубину, стараясь не паниковать и действовать слаженно, чтобы не напугать и без того встревоженного кита ещё сильнее.
Спасательная операция заняла почти три часа, но в итоге молодой кит благополучно вернулся в открытое море вслед за своей группой. Матвей, промокший и уставший, но невероятно счастливый, записал этот день в свой личный дневник как самый важный за всю практику — не потому, что он увидел что-то новое, а потому что впервые почувствовал, что его работа действительно может спасти чью-то жизнь, пусть даже это жизнь огромного морского животного, а не человека.
К концу лета дневник Матвея превратился в толстую тетрадь, полную зарисовок, наблюдений и историй.
За несколько дней до отъезда домой на станцию пришла плохая новость: рыбацкое судно неподалёку случайно повредило часть донной сети, обрывки которой могли представлять опасность для морских животных, включая китов, — запутавшись в сети, животное могло серьёзно пострадать или даже погибнуть. Вся команда станции немедленно организовала поисковую операцию на нескольких лодках, чтобы найти и убрать опасные обрывки до того, как кто-то из китов окажется рядом с ними.
Матвею, несмотря на юный возраст, доверили важную задачу — вести наблюдение с берега в бинокль и по рации сообщать координаты, если он заметит подозрительные предметы на поверхности воды. Несколько часов напряжённых поисков не приносили результата, но ближе к вечеру именно Матвей заметил на поверхности воды тёмное пятно, покачивающееся на волнах в стороне от основного района поисков, — это оказался тот самый обрывок сети, который команда искала весь день. Быстро сообщив координаты по рации, мальчик с волнением наблюдал, как ближайшая лодка поспешила к указанному месту и благополучно выловила опасный обрывок из воды.
Вечером того же дня Андрей Петрович, впечатлённый работой сына за всё лето — от находки подводного источника до спасения обрывка сети, — предложил ему выступить с небольшим докладом перед всей исследовательской группой станции, поделившись собственным взглядом юного наблюдателя на жизнь китов. Доклад имел такой успех, что руководитель станции пригласил Матвея вернуться на практику и в следующем году, пообещав, что к тому времени, возможно, они снова встретят своего старого знакомого — кита по имени Скиталец, возвращающегося своим извечным маршрутом через тысячи километров холодных и тёплых вод.`,
q:[["Кем был отец Матвея и куда они приехали на практику?","Морским биологом Андреем Петровичем, на прибрежную станцию наблюдения за китами."],["Как звали кита, знакомого исследователям уже семь лет?","Скиталец."],["Что случилось во время сильного шторма на станции?","Молодой кит оказался слишком близко к камням, и его пришлось спасать."],["Что предложил Матвею отец в конце лета?","Выступить с докладом о своих наблюдениях перед всей исследовательской группой."]],len:"long"}

];
